package com.cinebox.tv
internal val hdBatchCatalog = listOf(
    Movie(id = 1000000, title = "Sen, Ben, Biz", overview = "Hayatını kendi kurallarıyla yaşamayı seven bir kadın ve sıcak bir yuva kurarak baba olmayı isteyen bir adam, çocuk evlat edinme kararıyla birlikte ilişkilerinin en büyük sınavıyla karşılaşır. Birbirinden farklı beklentileri ve yaşam tarzları, aralarındaki bağı sorgulamalarına neden olurken geleceklerini birlikte şekillendirip şekillendiremeyecekleri belirsizleşir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/you-me-us-2026-izle.webp", backdrop = "", year = "2026", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sen-ben-biz-2026-izle/", category = "Film"),
    Movie(id = 1000001, title = "Ali G: Ben Kimim?", overview = "Hayatı boyunca sorumluluklardan uzak duran ve vaktini eğlenceyle geçiren Ali G’nin dünyası, sevgilisi Julie’nin sekiz aylık hamile olduğunu öğrenmesiyle tamamen değişir. Yakında baba olacağını fark eden Ali G, hayatını düzene sokmak ve eski şöhretini yeniden kazanmak amacıyla Amerika’ya gider. Fakat yeni bir başlangıç yapma hayali, karşısına çıkan tehlikeli kişiler yüzünden beklenmedik bir mücadeleye dönüşür. Üstelik artık yalnızca kendi hayatını değil, doğacak çocuğunun geleceğini de korumak zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/ali-g-ben-kimim-2026-izle.webp", backdrop = "", year = "2026", score = 5.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ali-g-ben-kimim/", category = "Film"),
    Movie(id = 1000002, title = "Kırmızı Bülten", overview = "FBI’ın en başarılı profil uzmanı John Hartley’nin, dünyanın en çok aranan sanat hırsızının izini sürdüğü bir aksiyon-komedi. Interpol’ün kırmızı bülten yayınlamasıyla göreve atanan Hartley, efsanevi hırsız The Bishop’u yakalamak için hiç beklemediği bir isimle, usta sanat hırsızı Nolan Booth ile aynı safta yer almak zorunda kalır. Birbirine güvenmeyen bu ikili, kovalamacanın her aşamasında hem birbirleriyle hem de peşlerindeki tehlikelerle mücadele eder. Uzak bir hapishaneden lüks bir dans salonuna, oradan balta girmemiş ormanlara uzanan bu macerada kimin kime oyun oynadığı son ana kadar belirsiz kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/red-notice-2021-izle.webp", backdrop = "", year = "2021", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kirmizi-bulten-2021-izle-1/", category = "Film"),
    Movie(id = 1000003, title = "Sürüş – Yalancılar", overview = "Yarış dünyasında başarılı olmak isteyen genç bir kadın, ünlü ancak tartışmalı bir pilotla nişanlıymış gibi davranarak kendine yeni bir kapı açar. Başlangıçta pilotun itibarını korumaya yönelik bir anlaşma olan bu planın arkasında, genç kadının direksiyon başına geçme arzusu vardır. Ne var ki birlikte geçirdikleri zaman, sahte ilişkinin sınırlarını ortadan kaldırmaya başlar. Gerçek hisler ve saklanan amaçlar birbirine karışırken bu oyun, ikisinin de kariyerini ve geleceğini riske atar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/surus-yalancilar-2026-izle.webp", backdrop = "", year = "2026", score = 5.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/surus-yalancilar/", category = "Film"),
    Movie(id = 1000004, title = "Verity: Gerçeğin Diğer Kıyısı", overview = "Colleen Hoover’ın aynı adlı romanından uyarlanan bir psikolojik gerilim. Ünlü yazar Verity Crawford, geçirdiği ağır bir araba kazasının ardından yazmaya devam edemez hale gelir. Eşi Jeremy, yarım kalan kitap serisini tamamlaması için zor durumdaki genç yazar Lowen’a yüklü bir teklifte bulunur. Teklifi kabul eden Lowen, Crawford’ların görkemli evine taşınır ve Verity’nin notları ile el yazmaları arasında çalışmaya başlar. Ancak sayfaların arasında ürkütücü sırlar bulur ve Verity’nin gerçek niyetinden, şimdiki durumundan şüphe etmeye başlar. Yazılanlar bir psikopatın tehlikeli oyununun parçası mı, yoksa hepsi sadece kurgu mu?", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/verity-2026-izle.webp", backdrop = "", year = "2026", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/verity-gercegin-diger-kiyisi/", category = "Film"),
    Movie(id = 1000005, title = "Muhteşem Gatsby", overview = "1920’lerin hareketli New York’una gelen Nick Carraway, yazar olma hayalini gerçekleştirmek için yeni bir hayata adım atar. Bu süreçte, ihtişamlı partileri ve sınırsız servetiyle tanınan gizemli milyoner Jay Gatsby ile tanışır. Kısa sürede lüksün, eğlencenin ve gösterişin hüküm sürdüğü bir dünyanın içine çekilen Nick, bu göz alıcı yaşamın ardında saklanan sırları, kırgınlıkları ve yaklaşan çöküşü keşfetmeye başlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-great-gatsby-2013-izle.webp", backdrop = "", year = "2013", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/muhtesem-gatsby/", category = "Film"),
    Movie(id = 1000006, title = "Yalanlar Üstüne", overview = "Roger Ferris, Irak’ta görev yapmış deneyimli bir gazetecidir. El Kaide’nin üst düzey isimlerinden birini yakalamakla görevlendirildiğinde CIA ile iş birliği yapmaya başlar. Ancak gazetecilikten istihbarat dünyasına uzanan bu yeni görev, Roger’ı alışık olmadığı tehlikelerle, karmaşık operasyonlarla ve güvenin kolayca sarsıldığı bir ortamla karşı karşıya bırakır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/yalanlar-ustune-2008-izle.webp", backdrop = "", year = "2008", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yalanlar-ustune-izle/", category = "Film"),
    Movie(id = 1000007, title = "Son Mohikan", overview = "1757 yılında, İngiliz ve Fransız kuvvetleri Kuzey Amerika’daki kolonilerin hâkimiyeti için amansız bir savaşa tutuşmuştur. Çatışmaların gölgesinde yaşayan Hawkeye, Mohikan halkından Chingachgook’un oğlu olarak vahşi doğada hayatta kalmayı öğrenmiş cesur bir savaşçıdır. Bir gün Fransızların müttefiki olan yerlilerin kurduğu pusudan İngiliz bir grubu kurtaran Hawkeye, aralarında Cora Munro’nun da bulunduğu yolculara güvenli bir şekilde rehberlik etmeyi kabul eder. Ancak yolculuk ilerledikçe savaşın acımasızlığı ve düşman saldırıları işleri zorlaştırır. Hayatta kalabilmek için birbirlerine güvenmek zorunda kalan bu insanlar, kendilerini hem tehlikeli çatışmaların hem de beklenmedik duyguların içinde bulur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/son-mohikan-1992-izle.webp", backdrop = "", year = "1992", score = 7.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/son-mohikan/", category = "Film"),
    Movie(id = 1000008, title = "Belalılar", overview = "1930’ların Chicago’sunda geçen hikâyede, yakın arkadaşlarını acımasız bir gangsterin yüzünden kaybeden iki dolandırıcı, intikam almak için kusursuz bir plan hazırlamaya karar verir. Hedeflerindeki kişi, kumar dünyasında güçlü bir konuma sahip olan tehlikeli bir suçludur. Onu alt etmek isteyen ikili, zekâlarını ve ustalıklarını kullanarak büyük bir tuzak kurar. Ancak bu planı hayata geçirmek, göründüğü kadar kolay değildir. Her ayrıntının titizlikle hesaplanması gereken bu mücadelede, en küçük hata bile bütün çabalarını boşa çıkarabilir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/belalilar-1973-izle.webp", backdrop = "", year = "1973", score = 8.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/belalilar-1973-izle/", category = "Film"),
    Movie(id = 1000009, title = "Yağmur Altında", overview = "Don Lockwood, uzun yıllar boyunca gösterdiği çaba ve yeteneği sayesinde Hollywood’un en gözde yıldızlarından biri olmayı başarmıştır. Şöhretinin zirvesinde olduğu dönemde, oyunculara karşı mesafeli tavrıyla dikkat çeken Kathy Selden ile tanışması hayatında yeni bir sayfa açar. Başlangıçta yaşadığı hayal kırıklıklarının ardından Kathy’ye âşık olan Don, bir yandan duygularıyla yüzleşirken diğer yandan kendisini isteyen bencil ve kıskanç rol arkadaşı Lina Lamont ile uğraşmak zorunda kalır. Gene Kelly’nin yönetmenliğini ve başrolünü üstlendiği Singin’ in the Rain, Hollywood’un değişen yüzünü, aşkı ve müzikal eğlenceyi unutulmaz bir hikâyede buluşturan sinema klasiklerinden biridir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/yagmur-altinda-1952-izle.webp", backdrop = "", year = "1952", score = 8.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yagmur-altinda/", category = "Film"),
    Movie(id = 1000010, title = "Gran Turismo", overview = "Yıllarını Gran Turismo oyununda geçiren yetenekli bir genç, sanal dünyada geliştirdiği sürüş becerilerini gerçek yarış pistlerine taşıma şansı elde eder. Nissan’ın düzenlediği zorlu yarış programında başarılı sonuçlar alarak dikkatleri üzerine çeken genç, kendisini profesyonel pilotluğa götürecek büyük bir mücadelenin içine girer. Fakat oyunlarda kazanmakla gerçek otomobillerin direksiyonunda yarışmak arasında büyük fark vardır. Tehlikelerle dolu bu yolculukta yeteneklerini geliştirmesi, baskıyla başa çıkması ve kendine inanması gereken genç, hayalini gerçeğe dönüştürmek için tüm gücüyle mücadele eder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/gran-turismo-2023-izle.webp", backdrop = "", year = "2023", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/gran-turismo/", category = "Film"),
    Movie(id = 1000011, title = "Werewolf By Night", overview = "Gecenin karanlığında ortaya çıkan sıra dışı bir canavar avcıları grubu, liderlerinin hayatını kaybetmesinin ardından Kan Taşı Tapınağı’nda toplanır. Yas tutmak için düzenlenen bu gizemli buluşma, kısa sürede çok daha tehlikeli bir amaca hizmet etmeye başlar. Avcılar, olağanüstü güçlere sahip olduğu söylenen değerli bir yadigârı ele geçirmek için birbirleriyle yarışır. Ancak hırsları onları geri dönüşü olmayan bir yola sürükler. Başlangıçta yalnızca bir rekabet gibi görünen bu mücadele, karşılarına çıkan korkunç bir canavarla birlikte hayatta kalma savaşına dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/werewolf-by-night-2022-izle.webp", backdrop = "", year = "2022", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/werewolf-by-night/", category = "Film"),
    Movie(id = 1000012, title = "Çıkış Yok", overview = "Hasta annesini görmek için yola çıkan Darby Thorne, şiddetli bir kar fırtınası nedeniyle yolculuğuna devam edemez ve bir dinlenme tesisine sığınır. Burada yolları kesişen yabancılarla aynı çatı altında beklemek zorunda kalan Darby, dışarıdaki araçlardan birinde kilitli tutulmuş küçük bir kız çocuğu fark eder. Çocuğun kaçırıldığını anlayınca harekete geçen genç kadın, tesiste bulunan kişilerden hangisinin bu olayın sorumlusu olduğunu ortaya çıkarmaya çalışır. Ancak çevresiyle bağlantısı kesilen Darby için zaman daralırken, kızı kurtarmak giderek daha tehlikeli bir mücadeleye dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/cikis-yok-2022-izle.webp", backdrop = "", year = "2022", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cikis-yok-2022-izle/", category = "Film"),
    Movie(id = 1000013, title = "Kayıp Şehir", overview = "Loretta Sage, romantik macera romanlarıyla tanınan, gözlerden uzak bir yaşam sürmeyi tercih eden başarılı bir yazardır. Kitaplarında anlattığı kayıp şehrin gerçek dünyada var olduğunun ortaya çıkmasıyla kendisini beklenmedik bir maceranın içinde bulur. Gizemli şehrin hazinesine ulaşmak isteyen milyarder Fairfax tarafından kaçırılan Loretta’yı kurtarmak ise kitaplarının kapaklarında yer alan model Alan’a düşer. Kendini romanlardaki cesur kahramanla özdeşleştiren Alan, Loretta’yı kurtarmak için tehlikelerle dolu bir yolculuğa çıkar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kayip-sehir-2022-izle.webp", backdrop = "", year = "2022", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kayip-sehir-2022-izle/", category = "Film"),
    Movie(id = 1000014, title = "Rogue One: Bir Star Wars Hikayesi", overview = "Galaksinin kaderini değiştirecek gizli bir görev, birbirinden farklı özelliklere sahip bir grup kahramanı bir araya getirir. Rogue One: Bir Star Wars Hikâyesi, İmparatorluk’un en güçlü silahı olan Ölüm Yıldızı’nın planlarını ele geçirmek için tehlikeli bir göreve atılan ekibin mücadelesini anlatıyor. İmkânsız gibi görünen bu operasyon, galaksiyi karanlıktan kurtarmak isteyenlerin cesaretini ve fedakârlığını sınar. Gareth Edwards’ın yönettiği film, Felicity Jones’un canlandırdığı Jyn Erso ve ekibinin hikâyesini merkezine alarak 1977 yapımı Yıldız Savaşları: Bölüm IV – Yeni Bir Umut filminde yaşanan olayların öncesini konu alıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/rogue-one-bir-star-wars-hikayesi-2016-izle.webp", backdrop = "", year = "2016", score = 7.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/rogue-one-bir-star-wars-hikayesi/", category = "Film"),
    Movie(id = 1000015, title = "Boynuzlar", overview = "Oregon’daki küçük ve sakin bir kasabada öğretmenlik yapan Julia, içine kapanık öğrencisi Lucas’ın davranışlarının ardındaki nedeni anlamaya çalışır. Diğer insanlarla iletişim kurmakta zorlanan çocuğun gizemli hâli, genç öğretmenin dikkatini çeker. Lucas’a yardım etmek isteyen Julia, kasabanın polis memuru olan erkek kardeşiyle birlikte öğrencisinin sakladığı gerçeği araştırmaya başlar. Ancak ortaya çıkarmaya çalıştıkları sır, düşündüklerinden çok daha karanlık ve tehlikelidir. Julia, gerçeğe yaklaştıkça kendisini hem Lucas’ın hem de bütün kasabanın geleceğini tehdit eden ürkütücü olayların ortasında bulur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/boynuzlar-2021-izle.webp", backdrop = "", year = "2021", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/boynuzlar-2021-izle/", category = "Film"),
    Movie(id = 1000016, title = "Gece Evi", overview = "Kocasının ölümünün ardından yalnız kalan Beth, geçmişin anılarıyla yaşamını sürdürmeye çalışırken geride bırakılan gizemli bir notla karşılaşır. Eşinin ölümden sonra hiçbir şey olmadığına dair sözleri, Beth’in bizzat tanık olduğu tuhaf olaylarla örtüşmez. Özellikle yalnız olduğu zamanlarda karşılaştığı açıklanamayan görüntüler, genç kadının huzurunu giderek bozar. Evin yakınındaki gölden gelen ayak izleri ve çevresinde beliren ürkütücü siluetler, yaşananların sıradan bir yas sürecinden ibaret olmayabileceğini düşündürür. Beth, hem kocasının geride bıraktığı mesajın anlamını hem de kendisini rahatsız eden karanlık gizemin kaynağını bulmaya çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-night-house-2020-izle.webp", backdrop = "", year = "2020", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/gece-evi-2020-izle/", category = "Film"),
    Movie(id = 1000017, title = "Vahşetin Çağrısı", overview = "Buck, Kaliforniya’da konforlu bir yaşam sürerken kendisini bir anda Alaska’nın dondurucu ve zorlu doğasında bulur. Evinden koparılarak kızak köpeği olarak çalıştırılmaya başlayan Buck, başlangıçta alışık olmadığı koşullara uyum sağlamakta güçlük çeker. Posta taşımacılığı yapan bir ekibin parçası hâline geldikçe hayatta kalmanın inceliklerini öğrenir ve karşılaştığı zorluklarla mücadele etmeyi başarır. Alaska’nın vahşi doğasında çıktığı bu yolculuk, Buck’ın yalnızca fiziksel gücünü değil, içindeki cesareti ve özgürlük arzusunu da keşfetmesini sağlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/vahsetin-cagrisi-2020-izle.webp", backdrop = "", year = "2020", score = 6.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/vahsetin-cagrisi/", category = "Film"),
    Movie(id = 1000018, title = "Tolkien", overview = "Dünya edebiyatının unutulmaz isimlerinden J.R.R. Tolkien’in hayatını anlatan film, ünlü yazarın çocukluğundan yetişkinlik dönemine uzanan bir yolculuğu konu alıyor. Küçük yaşta anne ve babasını kaybeden Tolkien’in eğitim hayatı, yakın arkadaşlarıyla kurduğu güçlü bağlar ve aşkı keşfetmesi, yaşamındaki önemli dönüm noktaları arasında yer alıyor. Ancak onun hayatı yalnızca edebiyat ve dostluklarla şekillenmiyor. I. Dünya Savaşı sırasında yaşadığı zorlu deneyimler de kişiliğini ve dünyaya bakışını derinden etkiliyor. Film, Tolkien’in yaşadıklarının, ileride Yüzüklerin Efendisi ve Hobbit gibi klasiklere dönüşecek hayal dünyasının oluşumundaki yerini gözler önüne seriyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/tolkien-2019-izle.webp", backdrop = "", year = "2019", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/tolkien-2019-izle/", category = "Film"),
    Movie(id = 1000019, title = "Biz", overview = "Adelaide ve Gabe Wilson, çocuklarıyla birlikte sakin ve mutlu bir yaşam sürmektedir. Yoğun geçen bir yılın ardından Kuzey Kaliforniya’daki sahil evlerine giderek ailece dinlenmek isterler. Ancak sahilde Tyler ailesiyle geçirdikleri keyifli günün ardından Adelaide, geçmişte yaşadığı travmatik olayların etkisiyle huzursuzlanmaya başlar. Gece olduğunda evlerinin yakınında el ele yürüyen dört yabancıyla karşılaşmaları, korkularını gerçeğe dönüştürür. Kısa süre içinde evlerine yapılan saldırıyla büyük bir kabusun içine sürüklenen Wilson ailesi, karşılarındaki kişilerin kendilerinin tıpatıp aynısı olduğunu fark eder. Hayatta kalmak için mücadele eden aileyi, kimsenin tahmin edemeyeceği kadar ürkütücü bir yüzleşme beklemektedir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/biz-2019-izle.webp", backdrop = "", year = "2019", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/biz-2019-izle/", category = "Film"),
    Movie(id = 1000020, title = "Hayvan Mezarlığı", overview = "Boston’daki hayatlarını geride bırakarak kırsal bir bölgeye yerleşen Creed ailesi, burada huzurlu bir yaşam kurmayı umut eder. Ancak küçük oğullarını trajik bir kazada kaybetmeleri, aileyi derin bir acıya sürükler. Yaşadıkları bu büyük kaybın ardından evcil kedileri de ölür ve ailenin evine yakın, gizemli olaylarla anılan bir mezarlığa gömülür. Kısa süre sonra kedinin yeniden hayata dönmesi, Creed ailesini mezarlığın karanlık sırrıyla yüzleştirir. Fakat ölümden geri dönmenin beraberinde getirdiği sonuçlar, tahmin ettiklerinden çok daha korkutucudur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hayvan-mezarligi-2019-izle.webp", backdrop = "", year = "2019", score = 5.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hayvan-mezarligi/", category = "Film"),
    Movie(id = 1000021, title = "Köpek Adası", overview = "Megasaki şehrinde alınan sıra dışı bir kararla, evcil ya da sokak köpeği ayrımı yapılmaksızın bütün köpekler şehrin dışındaki devasa bir çöp adasına sürgün edilir. Sürgüne gönderilenler arasında 12 yaşındaki Atari Kobayashi’nin sadık dostu Spots da vardır. Köpeğini geride bırakmayı kabullenemeyen Atari, küçük uçağıyla nehri aşarak onu bulmak için tehlikeli bir yolculuğa çıkar. Bu macerada kendisine bir grup melez köpek eşlik eder. Atari’nin dostunu bulmak için çıktığı bu yolculuk, yalnızca kendi hayatını değil, bütün bölgenin geleceğini de değiştirecek olayların başlangıcı olur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kopek-adasi-2018-izle.webp", backdrop = "", year = "2018", score = 7.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kopek-adasi/", category = "Film"),
    Movie(id = 1000022, title = "Oyun Gecesi", overview = "Max ve Annie’nin arkadaşlarıyla düzenlediği eğlenceli oyun gecesi, Max’in kardeşi Brooks’un sıra dışı bir planıyla bambaşka bir hâl alır. Sahte suçluların ve federal ajanların yer aldığı gizemli bir cinayet senaryosu hazırlayan Brooks, gecenin ilerleyen saatlerinde kaçırılınca herkes bunun oyunun bir parçası olduğunu düşünür. Ancak altı arkadaş olayın perde arkasını araştırmaya başladıkça karşılaştıkları durumların hiç de göründüğü gibi olmadığını anlar. Beklenmedik gelişmelerle dolu bu gecede ekip, eğlence için başladıkları oyunun içinden sağ salim çıkabilmek için mücadele etmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/oyun-gecesi-2018-izle.webp", backdrop = "", year = "2018", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/oyun-gecesi/", category = "Film"),
    Movie(id = 1000023, title = "Suyun Sesi", overview = "1963 yılında, Soğuk Savaş’ın gölgesindeki Amerika’da geçen hikâye, sessiz ve yalnız bir yaşam süren Elisa’nın hayatına odaklanıyor. Gizli bir devlet laboratuvarında temizlik görevlisi olarak çalışan Elisa, meslektaşı Zelda ile birlikte sıra dışı bir deneyin varlığını keşfeder. Laboratuvarın sıkı güvenlik önlemleri ardında saklanan bu gizemli keşif, Elisa’nın dünyasını tamamen değiştirir. İnsanlık, sevgi ve farklılıklar üzerine kurulu bu fantastik öykü, beklenmedik bir bağın hayatları nasıl değiştirebileceğini gözler önüne seriyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/suyun-sesi-2017-izle.webp", backdrop = "", year = "2017", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/suyun-sesi/", category = "Film"),
    Movie(id = 1000024, title = "Aramızdaki Sözler", overview = "Hayatta kalma mücadelesinin merkezinde yer alan Ben ve Alex, trajik bir uçak kazasından sonra kendilerini karla kaplı, ıssız bir dağda bulur. Yaralı ve şaşkın halde başlayan bu zorlu süreçte, dış dünyayla bağlantılarının olmadığını ve kurtarılmayı beklemenin yeterli olmayacağını anlarlar. Önlerinde uzanan yüzlerce kilometrelik vahşi doğayı aşmak için birlikte hareket etmek zorunda kalan ikili, dondurucu soğuk ve ölümcül engeller karşısında büyük bir sınav verir. Bu yolculuk, onlara hayatta kalmanın yanı sıra güvenmenin, dayanışmanın ve pes etmemenin önemini de gösterecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/aramizdaki-sozler-2017-izle.webp", backdrop = "", year = "2017", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/aramizdaki-sozler/", category = "Film"),
    Movie(id = 1000025, title = "Muhteşem Showman", overview = "Hayatı boyunca büyük hayaller kuran P. T. Barnum, küçük yaşlarda başladığı ticaret deneyimini sıra dışı bir projeye dönüştürmek ister. 1841 yılında, dünyanın daha önce tanık olmadığı bir eğlence deneyimi sunmak amacıyla kolları sıvar. Karısının da desteğiyle farklı özelliklere ve yeteneklere sahip insanları bir araya getirerek unutulmaz gösterilerin temelini atar. Başlangıçta cesur bir girişim olarak görülen bu fikir, zamanla geniş kitlelerin ilgisini çeker ve Barnum’un topluluğu Avrupa’ya kadar uzanan büyük bir üne kavuşur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/muhtesem-showman-2017-izle.webp", backdrop = "", year = "2017", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/muhtesem-showman/", category = "Film"),
    Movie(id = 1000026, title = "Küçülen Hayatlar", overview = "Paul Safranek ve eşi Audrey, daha huzurlu ve konforlu bir yaşam kurabilmek için Omaha’daki yoğun hayatlarını geride bırakmaya karar verir. Çözümü, insanların küçültülerek daha az kaynakla daha iyi bir yaşam sürdüğü yeni bir topluluğa katılmakta bulurlar. Ancak bu sıra dışı karar, çiftin beklediğinden çok daha farklı deneyimlerle karşılaşmasına neden olur. Matt Damon, Kristen Wiig ve Christoph Waltz’un başrollerini paylaştığı filmin yönetmenliğini Alexander Payne üstleniyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kuculen-hayatlar-2017-izle.webp", backdrop = "", year = "2017", score = 5.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kuculen-hayatlar/", category = "Film"),
    Movie(id = 1000027, title = "Kabuktaki Hayalet", overview = "Ölümcül bir kazanın ardından hayata döndürülen genç bir kadın, insanüstü yeteneklere sahip bir sayborg olarak yeniden yaratılır. Binbaşı adıyla tanınan bu özel ajan, 9. Birlik’in liderliğinde terörizm ve siber suçlarla mücadele ederek insanlığı tehdit eden tehlikeleri ortadan kaldırmaya çalışır. Teknolojinin insan zihnine müdahale edebildiği bu dünyada, yeni bir düşmanın peşine düşmesi onu beklenmedik gerçeklerle karşı karşıya getirir. Hafızasında boşluklar bulunan Binbaşı, geçmişi hakkında kendisine söylenenlerin bir yalandan ibaret olabileceğini fark eder. Kendisini kimin ve hangi amaçla değiştirdiğini öğrenmeye kararlı olan genç kadın, gerçek kimliğini bulmak için tehlikeli bir yolculuğa çıkar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kabuktaki-hayalet-2017-izle.webp", backdrop = "", year = "2017", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kabuktaki-hayalet/", category = "Film"),
    Movie(id = 1000028, title = "Muhteşem Yedili", overview = "Vahşi Batı’nın acımasız koşullarında, zengin sanayici Bartholow Bogue’un baskısı altında ezilen Rose Creek kasabası, yaklaşan büyük bir tehlikeyle karşı karşıyadır. Kasaba halkını korumak isteyenler, birbirinden farklı geçmişlere sahip yedi silahlı adamdan yardım ister. Sam Chisolm liderliğindeki bu ekipte ödül avcıları, kumarbazlar ve ölümcül yetenekleriyle tanınan savaşçılar bir araya gelir. Kasabayı savunmak için hazırlıklara başlayan yedi adam, düşmanlarına karşı mücadele ederken kendi cesaretlerini, inançlarını ve adalet anlayışlarını da sorgular. Antoine Fuqua’nın yönettiği filmde Denzel Washington, Chris Pratt ve Ethan Hawke gibi yıldız isimler başrolleri paylaşırken yapım, klasik Western atmosferini aksiyon dolu…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/muhtesem-yedili-2016-izle.webp", backdrop = "", year = "2016", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/muhtesem-yedili/", category = "Film"),
    Movie(id = 1000029, title = "Uzay Yolcuları", overview = "Uzak bir gezegene doğru yol alan devasa bir uzay gemisinde seyahat eden binlerce yolcu, yolculuk boyunca özel kapsüllerde uyutulmaktadır. Ancak beklenmedik bir arıza nedeniyle Jim ve Aurora, varış noktasına ulaşmalarına daha 90 yıl varken uyanır. Gemide tek başlarına kalan ikili, tüm konfor olanaklarına rağmen bu uzun yolculuğu yalnız geçirmek zorunda kalır. Zamanla birbirlerine yakınlaşan Jim ve Aurora, aralarında gelişen duygularla yeni bir hayata alışmaya çalışır. Fakat gemide ciddi bir sorun olduğunu fark ettiklerinde hem kendi hayatlarını hem de uyku hâlindeki 5.000 yolcunun geleceğini kurtarmak için zamana karşı mücadele etmek zorunda…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/uzay-yolculari-2016-izle.webp", backdrop = "", year = "2016", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/uzay-yolculari/", category = "Film"),
    Movie(id = 1000030, title = "Senden Önce Ben", overview = "Will Traynor, başarılı kariyeri, maddi imkânları ve renkli yaşamıyla her şeye sahip görünen genç bir adamdır. Ancak geçirdiği motosiklet kazası onu felç bırakınca hayata karşı bütün umudunu yitirir. Louisa Clark ise sıradan bir yaşam süren, kafede çalışırken işini kaybeden ve geleceği konusunda net bir yön çizemeyen genç bir kadındır. Will’in bakımını üstlenmek için işe başlayan Louisa, başlangıçta mesafeli ve karamsar olan bu adamın hayatına zamanla yeni bir anlam katar. Aralarında gelişen bağ, ikisinin de hayata bakışını değiştirirken sevgi, umut ve seçimler üzerine dokunaklı bir hikâye ortaya çıkar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/senden-once-ben-2016-izle.webp", backdrop = "", year = "2016", score = 7.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/senden-once-ben/", category = "Film"),
    Movie(id = 1000031, title = "Bu da Nereden Çıktı?", overview = "Ned Fleming, kızı Stephanie’ye düşkün ve onun mutluluğunu her şeyin üzerinde tutan korumacı bir babadır. Ancak Stephanie artık kendi hayatını kurmaya hazırdır ve bir gün erkek arkadaşı Laird ile ailesini tanıştırır. Genç yaşta internet üzerinden büyük bir servet kazanan Laird, samimi fakat sınır tanımayan davranışlarıyla Ned’in kısa sürede tepkisini çeker. Üstelik Laird, Stephanie ile evlenmeyi düşündüğünü açıklayınca işler daha da karmaşık bir hâl alır. Ailesinin geri kalanı Laird’e ısınırken Ned, kızının bu sıra dışı adamla evlenmesini engellemek için elinden geleni yapar. Böylece iki farklı karakter arasında bol kahkahalı bir mücadele…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/bu-da-nereden-cikti-2016-izle.webp", backdrop = "", year = "2016", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/bu-da-nereden-cikti/", category = "Film"),
    Movie(id = 1000032, title = "Victor Frankenstein", overview = "İnsan hayatının sınırlarını aşmayı hedefleyen sıra dışı bir bilim insanı ile onun sadık yardımcısının tehlikeli macerasını anlatıyor. Sirkte kamburu nedeniyle kötü muamele gören Igor, olağanüstü zekâsıyla dikkat çeker ve genç doktor Victor Frankenstein tarafından kurtarılır. İkili, insanlığı ölümün sınırlarından kurtarabilecek deneyler üzerinde birlikte çalışmaya başlar. Ancak Victor’un bilimsel merakı zamanla tehlikeli bir takıntıya dönüşür. Ölüleri yeniden hayata döndürme arzusu, onu geri dönüşü olmayan bir yola sürüklerken Igor da hayranlık duyduğu doktorun gerçek amaçlarını sorgulamaya başlar. Kontrolden çıkan deneyler korkunç sonuçlar doğururken Igor, hem arkadaşını kendi hırslarından korumaya hem de ortaya…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/victor-frankenstein-2015-izle.webp", backdrop = "", year = "2015", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/victor-frankenstein/", category = "Film"),
    Movie(id = 1000033, title = "Yarının Dünyası", overview = "Bilim ve hayal gücünün iç içe geçtiği gizemli bir evrende geçen heyecan dolu bir macerayı konu alıyor. Bilime ve yeni keşiflere büyük ilgi duyan zeki genç Casey, beklenmedik bir şekilde kendisini sırlarla dolu bir yolculuğun içinde bulur. Bu yolculukta, geçmişte dahi bir çocuk olarak tanınan ancak zamanla umutlarını kaybeden Frank ile yolları kesişir. İkili, zaman ve uzayın ötesinde var olduğu söylenen Yarının Dünyası’nın gizemini çözmek için güçlerini birleştirir. Ancak bu sıra dışı yere ulaşmak ve ardındaki gerçekleri ortaya çıkarmak, onları tehlikelerle dolu bir maceraya sürükler. İnsanlığın geleceğini değiştirebilecek sırların peşine…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/yarinin-dunyasi-2015-izle.webp", backdrop = "", year = "2015", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yarinin-dunyasi/", category = "Film"),
    Movie(id = 1000034, title = "Seninle Bir Ömür", overview = "Luke, geçmişte elde ettiği başarıları yeniden yakalamak isteyen eski bir boğa binicisi, Sophia ise New York’un sanat dünyasında kendine bir yer edinmeye çalışan genç bir üniversite öğrencisidir. Farklı hayallere ve yaşam hedeflerine sahip olan ikili, yollarının kesişmesiyle kendilerini beklenmedik bir aşkın içinde bulur. Ancak kariyer planları ve gelecek kaygıları, ilişkilerini zor bir sınavdan geçirir. Hayatları, Ira adında yaşlı bir adamla tanışmalarıyla bambaşka bir yöne ilerler. Ira’nın eşi Ruth ile yaşadığı büyük aşkı anlatan eski mektuplar, Luke ve Sophia’nın sevgiye, bağlılığa ve hayatın gerçek değerlerine bakışını değiştirir. Geçmişle bugünü bir araya…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/seninle-bir-omur-2015-izle.webp", backdrop = "", year = "2015", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/seninle-bir-omur/", category = "Film"),
    Movie(id = 1000035, title = "Göç: Tanrılar ve Krallar", overview = "Hz. Musa’nın hikâyesi, Mısır’ın hükümdar ailesinde büyümesiyle başlar. Ramses ile kardeş kadar yakın olan Musa, kraliyet ailesinin güvenini kazanmış başarılı bir komutan olarak yaşamını sürdürür. Fakat İbrani kökeninin ortaya çıkması, saraydaki konumunu kaybetmesine ve çöle sürgün edilmesine neden olur. Yaşadığı olayların ardından hayatına yeni bir yön veren Musa, Tanrı’nın kendisine halkını kurtarma görevi verdiğine inanır. Mısır’da kölelik altında ezilen İbranilerin özgürlüğü için harekete geçerek firavun Ramses’e karşı durur. Böylece geçmişte kardeş gibi olan iki adam, inançları ve amaçları uğruna karşı karşıya gelir. Musa’nın önderliğinde başlayan büyük göç, halkını vaat edilmiş…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/goc-tanrilar-ve-krallar-2014-izle.webp", backdrop = "", year = "2014", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/goc-tanrilar-ve-krallar/", category = "Film"),
    Movie(id = 1000036, title = "Sihirli Orman", overview = "Grimm Kardeşler’in unutulmaz masal kahramanlarını aynı hikâyede buluşturarak klasik öykülere farklı bir bakış açısı getiriyor. Kırmızı Başlıklı Kız, Külkedisi ve Rapunzel gibi tanınmış karakterlerin yolları, dileklerini gerçekleştirmeye çalışan bir fırıncı ve eşinin macerasıyla kesişiyor. Çocuk sahibi olmak isteyen çift, kendilerini lanetleyen cadının isteğini yerine getirebilmek için gizemli ormanın derinliklerinde zorlu bir arayışa çıkar. Cadının talep ettiği özel eşyaları bulmaya çalışırken birbirinden farklı masal kahramanlarıyla karşılaşan fırıncı, beklenmedik olayların içine sürüklenir. Fantastik atmosferi, müzikal anlatımı ve tanıdık masalları bir araya getiren film, dileklerin bedeli, seçimlerin sonuçları ve hayallerin peşinden gitmek üzerine…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/sihirli-orman-2014-izle.webp", backdrop = "", year = "2014", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sihirli-orman/", category = "Film"),
    Movie(id = 1000037, title = "Arınma Gecesi: Sonsuza Dek", overview = "Amerika’yı yıllardır etkisi altına alan Arınma Gecesi geleneği, kontrolden çıkan yeni bir tehditle karşı karşıyadır. Bir grup radikal, suç işleme özgürlüğünün yalnızca bir geceyle sınırlı kalmasını istemez ve ülkeyi bitmeyen bir şiddet dalgasına sürüklemek için harekete geçer. Bu karanlık planın etkileri Teksas’a kadar ulaşırken Adela ve Juan kendilerini büyük bir tehlikenin ortasında bulur. Juan’ın çalıştığı Tucker ailesine ait çiftliğe düzenlenen saldırı, iki ailenin hayatını altüst eder. Maskeli katillerin peşlerine düşmesiyle birlikte birbirinden farklı geçmişlere sahip bu insanlar, hayatta kalmak için birlikte mücadele etmek zorunda kalır. Arınma Gecesi: Sonsuza Dek, korkunun…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/arinma-gecesi-sonsuza-dek-2021-izle.webp", backdrop = "", year = "2021", score = 5.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/arinma-gecesi-sonsuza-dek/", category = "Film"),
    Movie(id = 1000038, title = "İlk Arınma Gecesi", overview = "Amerika’da suç oranlarını azaltmak isteyen yönetim, insan doğasının karanlık yönlerini ortaya çıkarmayı amaçlayan radikal bir yöntemi devreye sokar. Yeni Kurucu Atalar tarafından hazırlanan plan kapsamında, seçilmiş bir bölgede yaşayan insanlar bir gece boyunca tüm suçların cezasız kaldığı bir deneyin parçası olur. Ancak bastırılmış öfkenin serbest bırakılmasıyla başlayan süreç, kısa sürede beklenmedik bir şiddet dalgasına dönüşür. Deneyin hedefindeki topluluk, saldırılar ve intikam arayışları arasında hayatta kalmaya çalışırken uygulama giderek daha geniş bir alana yayılır. Yaşananlar, ilerleyen yıllarda ülkenin kaderini belirleyecek kanlı bir geleneğin başlangıcı olur. İlk Arınma Gecesi, serinin karanlık geçmişini…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/ilk-arinma-gecesi-2018-izle.webp", backdrop = "", year = "2018", score = 5.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ilk-arinma-gecesi/", category = "Film"),
    Movie(id = 1000039, title = "Arınma Gecesi 3: Seçim Yılı", overview = "Amerika’nın Yeni Kurucuları tarafından her yıl düzenlenen ve 12 saat boyunca tüm suçların serbest bırakıldığı Arınma Gecesi, bu kez çok daha tehlikeli bir boyuta ulaşır. Ülkede yaklaşan seçimlerde öne çıkan bir senatör, bu acımasız uygulamayı sona erdirmek için mücadele etmektedir. Ancak planlarını hayata geçiremeden Arınma Gecesi başlar ve onun karşısında duran gruplar harekete geçer. Bu düzenin devam etmesini isteyen saldırganlar, senatörü ortadan kaldırmak için harekete geçerken onu korumakla görevli kişiler de amansız bir hayatta kalma savaşına sürüklenir. James DeMonaco’nun yönettiği Arınma Gecesi 3, siyasi entrikaları, yüksek tempolu aksiyonu ve karanlık…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-purge-election-year-2016-izle.webp", backdrop = "", year = "2016", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/arinma-gecesi-3-secim-yili/", category = "Film"),
    Movie(id = 1000040, title = "Arınma Gecesi 2: Anarşi", overview = "Yılın en korkunç gecesinde, kanunların ve cezaların geçerliliğini yitirmesiyle Los Angeles adeta bir savaş alanına dönüşür. Arınma Gecesi başlamadan önce evlerine dönmeye çalışan bir çift, çocuklarıyla birlikte yolda mahsur kalınca kendilerini ölümcül bir tehlikenin içinde bulur. Bu sırada oğlunu kaybetmenin acısını yaşayan Leo, intikamını almak üzere harekete geçerken saldırıya uğrayan evinden kızıyla kaçan bir anne de güvenli bir yer bulmaya çalışır. Farklı hikâyelere sahip beş yabancı, şiddetin her köşeye yayıldığı bu gecede bir araya gelir. Peşlerindeki tehlikelerden kurtulmak için birbirlerine güvenmek zorunda kalan grup, sabaha ulaşabilmek adına amansız bir mücadeleye…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-purge-anarchy-2014-izle.webp", backdrop = "", year = "2014", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/arinma-gecesi-2-anarsi/", category = "Film"),
    Movie(id = 1000041, title = "Arınma Gecesi", overview = "Amerika’da suçla mücadele ve hapishanelerdeki aşırı yoğunluk, hükümeti radikal bir karar almaya iter. Belirlenen tek bir gecede, 12 saat boyunca bütün suçlar cezasız kalacak ve güvenlik güçleri hiçbir olaya müdahale etmeyecektir. İnsanların kendi adaletlerini sağlamaya bırakıldığı bu karanlık zaman diliminde, James ve Mary ailelerini koruyabilmek için evlerine kapanır. Güvenlik önlemlerine güvenerek geceyi atlatmayı uman aile, kızlarının sokakta tehlike altındaki bir adamı evlerine getirmesiyle büyük bir kabusun içine sürüklenir. Dışarıdaki şiddet giderek kapılarına dayanırken, aile hem kendisini hem de evine aldığı yabancıyı korumak için ölümcül bir mücadele vermek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/arinma-gecesi-2013-izle.webp", backdrop = "", year = "2013", score = 5.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/arinma-gecesi-2013-izle/", category = "Film"),
    Movie(id = 1000042, title = "Yaban", overview = "Hayatında peş peşe yaşadığı acılar, Cheryl Strayed’i kendisine zarar veren bir yaşamın içine sürükler. Çok sevdiği annesi Bobbi’yi kaybetmesi, evliliğinin bitmesi ve bağımlılıkla mücadelesi, genç kadının kendisini tamamen kaybolmuş hissetmesine neden olur. Artık geçmişini geride bırakmak ve hayatına yeni bir yön vermek isteyen Cheryl, tek başına uzun bir yürüyüşe çıkmaya karar verir. Amerika’nın etkileyici ama zorlu doğasında uzanan Pasifik Crest Yolu boyunca ilerlerken hem fiziksel sınırlarını zorlar hem de geçmişiyle yüzleşir. Her adımda acılarını anlamlandırmaya ve yeniden güç kazanmaya çalışan Cheryl’in hikâyesi, insanın en karanlık dönemlerinden sonra bile kendisi için…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/yaban-2014-izle.webp", backdrop = "", year = "2014", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yaban-2014-izle/", category = "Film"),
    Movie(id = 1000043, title = "Trans", overview = "Müzayede dünyasının deneyimli isimlerinden Simon, gangster Franck ile yaptığı iş birliği sonucunda milyonlarca dolar değerindeki bir sanat eserinin çalınmasına yardım eder. Ancak operasyon sırasında yaşadığı talihsiz olay, bütün planları altüst eder. Başına aldığı darbe nedeniyle hafızasını kaybeden Simon, tablonun saklandığı yeri bir türlü hatırlayamaz. Franck, aradığı bilgiye ulaşmak için Elizabeth adlı hipnoz uzmanından yardım alırken Simon’un zihnindeki kapalı kapılar yavaş yavaş aralanmaya başlar. Geçmişin izleri belirginleştikçe Simon’un bastırdığı arzular ve unutulmuş duygular da yeniden ortaya çıkar. Danny Boyle imzalı bu gerilim filmi, izleyiciyi hafızanın güvenilirliğini ve insan zihninin gizemli yönlerini…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/trans-2013-izle.webp", backdrop = "", year = "2013", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/trans-2013-izle/", category = "Film"),
    Movie(id = 1000044, title = "Kitap Hırsızı", overview = "İkinci Dünya Savaşı’nın gölgesinde geçen hikâye, dokuz yaşındaki Liesel Meminger’in Almanya’da işçi sınıfının yaşadığı bir mahallede yeni bir hayata başlamasıyla şekillenir. Kitaplara karşı giderek büyüyen bir sevgi besleyen Liesel, zamanla kitap çalmaya başlar ve ele geçirdiği eserleri üvey babasıyla ve çevresindeki insanlarla paylaşır. Kelimelerin gücünü keşfettikçe savaşın acımasızlığına karşı kendine farklı bir dünya kurar. Markus Zusak’ın çok satan romanından uyarlanan bu etkileyici hikâye, dostluğun, umudun ve edebiyatın en karanlık zamanlarda bile insanlara güç verebileceğini anlatıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kitap-hirsizi-2013-izle.webp", backdrop = "", year = "2013", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kitap-hirsizi/", category = "Film"),
    Movie(id = 1000045, title = "Yolda Kaldım", overview = "Seattle sokaklarında eski Toyota Camry marka arabasında yaşamını sürdüren Amanda Ogle, hayatını ayakta tutmaya çalışırken beklenmedik bir sorunla karşı karşıya kalır. Kendisi için bir barınaktan çok daha fazlasını ifade eden arabası çalınıp ardından el konulunca, onu geri alabilmek için zorlu bir hukuk mücadelesine girişir. Karşısında duyarsız bir sistem ve aşması gereken sayısız engel bulan Amanda, hakkını aramaktan vazgeçmez. Tow, bir kadının adalet arayışını, hayata tutunma çabasını ve en zor koşullarda bile onurunu koruma mücadelesini anlatan etkileyici bir dram hikâyesi sunuyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/yolda-kaldim-2025-izle.webp", backdrop = "", year = "2025", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yolda-kaldim-2025-izle/", category = "Film"),
    Movie(id = 1000046, title = "Sefiller", overview = "19. yüzyıl Fransa’sında geçen Sefiller, geçmişin yüküyle mücadele eden bir adamın umut, sevgi ve özgürlük arayışını konu alıyor. Jean Valjean, yıllarca süren mahkûmiyetinin ardından serbest bırakılır ve hayatına yeni bir yön vermeye karar verir. Ancak peşini bırakmayan müfettiş Javert, onun geçmişinden tamamen kurtulmasını zorlaştırır. Valjean’ın, zor şartlarda yaşam mücadelesi veren Fantine’in kızı Cosette’in sorumluluğunu üstlenmesiyle her ikisinin de hayatı farklı bir yola girer. Toplumsal eşitsizliklerin, adaletsizliğin ve devrimci hareketlerin gölgesinde gelişen hikâye; fedakârlık, merhamet ve insanın kendini yeniden yaratma çabasını etkileyici bir şekilde ele alıyor. Victor Hugo’nun ölümsüz eserinden uyarlanan…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/sefiller-2012-izle.webp", backdrop = "", year = "2012", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sefiller-2012-izle/", category = "Film"),
    Movie(id = 1000047, title = "Doğaüstü", overview = "Hayatları sıradan bir şekilde devam eden üç genç, gizemli bir yer altı geçidinde yaptıkları keşfin ardından olağanüstü yetenekler kazanır. Artık yalnızca zihinlerini kullanarak eşyaları hareket ettirebilen ve çevrelerindeki olaylara müdahale edebilen arkadaşlar, bu güçleri ilk başlarda eğlenmek ve sınırlarını denemek amacıyla kullanır. Fakat zaman geçtikçe deneyleri kontrolden çıkmaya, aldıkları kararlar ise kendileri ve çevrelerindeki insanlar için ciddi bir tehdit oluşturmaya başlar. Yaşadıkları her anın kamera kayıtlarına yansıması, bu sıra dışı hikâyeyi daha gerçekçi bir anlatımla izleyiciye aktarır. Süper güçlerin getirdiği sorumlulukları ve yanlış seçimlerin sonuçlarını ele alan filmin yönetmen koltuğunda…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/chronicle-2012-izle.webp", backdrop = "", year = "2012", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/dogaustu-2012-izle/", category = "Film"),
    Movie(id = 1000048, title = "Hitchcock", overview = "Alfred Hitchcock’un sinema dünyasında iz bırakan gerilim klasiği Sapık’ın (Psycho) nasıl ortaya çıktığını anlatan Hitchcock, ünlü yönetmenin kariyerindeki önemli bir dönemi beyazperdeye taşıyor. Hikâyenin merkezinde, yeni filmini gerçekleştirmek için alışılmışın dışında bir yol izleyen Hitchcock ile bu süreçte hem en yakın destekçisi hem de hayat arkadaşı olan Alma Reville bulunuyor. Anthony Hopkins ve Helen Mirren’in başrollerini paylaştığı yapım, ikilinin evliliklerini, mesleki iş birliklerini ve film çekimleri sırasında karşılaştıkları sorunları ele alıyor. Yönetmen Sacha Gervasi’nin imzasını taşıyan film, Stephen Rebello’nun Hitchcock’un efsanevi yapımının perde arkasını inceleyen kitabından esinleniyor. Scarlett Johansson, James…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hitchcock-2012-izle.webp", backdrop = "", year = "2012", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hitchcock-2012-izle/", category = "Film"),
    Movie(id = 1000049, title = "Buz Devri 5: Büyük Çarpışma", overview = "Scrat, her zamanki gibi meşe palamudunun peşinden koşarken farkında olmadan evrenin dengesini değiştirecek kozmik olayları başlatır. Bu olayların etkisi, Manny, Sid, Diego ve diğer dostlarına kadar ulaşır ve Dünya’yı bir kez daha büyük bir felaketin eşiğine getirir. Bu kez gezegeni tehdit eden tehlike, hızla yaklaşan devasa bir meteor çarpmasıdır. Yaşanan sıra dışı gelişmelerin ardından ekip, dünyayı kurtarmanın bir yolunu bulmak için harekete geçer. Zeki ve maceracı Buck’ın öncülüğünde Geotopia adlı gizemli bir yere doğru yola çıkan kahramanlarımız, burada bulunan özel kristallerin felaketi önlemenin anahtarı olabileceğini keşfeder. Ancak Dünya’yı kurtarmak için…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/buz-devri-5-buyuk-carpisma-2016-izle.webp", backdrop = "", year = "2016", score = 5.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/buz-devri-5-buyuk-carpisma/", category = "Film"),
    Movie(id = 1000050, title = "Buz Devri 4: Kıtalar Ayrılıyor", overview = "Manny, Diego ve Sid’in hayatı, dünyayı değiştiren büyük bir felaketin ardından tamamen altüst olur. Kıtaların birbirinden ayrılmasıyla arkadaşlarından uzak düşen üçlü, kendilerini uçsuz bucaksız denizlerde sürüklenirken bulur. Bir buzdağını gemiye dönüştürerek eve dönmenin yollarını arayan kahramanlarımız, yolculuk sırasında egzotik deniz canlılarıyla ve acımasız korsanlarla karşı karşıya gelir. Bu zorlu macerada dostlukları ve cesaretleri sınanırken, meşe palamudunun peşinden ayrılmayan Scrat da kendine özgü talihsizlikleriyle ortalığı karıştırmaya devam eder. Buz Devri’nin sevilen karakterleri, bu kez denizlerde geçen heyecan dolu bir serüvenle izleyicilerin karşısına çıkar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/buz-devri-4-kitalar-ayriliyor-2012-izle.webp", backdrop = "", year = "2012", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/buz-devri-4-kitalar-ayriliyor/", category = "Film"),
    Movie(id = 1000051, title = "Buz Devri 3: Dinozorların Şafağı", overview = "Manny, Sid ve Diego’nun maceraları bu kez dinozorların hüküm sürdüğü gizemli bir dünyaya taşınır. Kendilerini beklenmedik bir tehlikenin ortasında bulan üç arkadaş, karşılarına çıkan dev yaratıklara rağmen birlikte hareket ederek kurtulmanın bir yolunu arar. Ellie ve diğer dostları da bu zorlu yolculukta onlara eşlik ederken ekip, daha önce hiç karşılaşmadıkları olaylarla yüzleşir. Her zamanki gibi meşe palamudunun peşinden ayrılmayan Scrat ise kendine özgü sakarlıklarıyla olayları içinden çıkılmaz bir hâle getirir. Eğlence, aksiyon ve sürprizlerle dolu bu macera, kahramanlarımızı yepyeni sınavlarla karşı karşıya bırakır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/buz-devri-3-dinozorlarin-safagi-2009-izle.webp", backdrop = "", year = "2009", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/buz-devri-3-dinozorlarin-safagi/", category = "Film"),
    Movie(id = 1000052, title = "Buz Devri 2: Erime Başlıyor", overview = "Mamut Manny, artık bir aile kurmanın hayalini gerçekleştirmek istemektedir. Ancak uzun zamandır başka bir mamuta rastlamadığı için bu isteğinin gerçekleşeceğine dair umudu giderek azalmıştır. Ta ki Ellie adında bir mamutla karşılaşana kadar! Ne var ki Ellie, kendisini bir opossum sanmaktadır ve bu durum Manny ile arasındaki ilişkiyi oldukça karmaşık hâle getirir. Diğer yandan yükselen sıcaklıklar, vadiyi büyük bir sel felaketinden koruyan devasa buz setini eritmeye başlamıştır. Yaklaşan tehlikeyi fark eden Manny, Sid ve Diego, Ellie ile opossum kardeşlerini de yanlarına alarak güvenli bir yere ulaşmak için zorlu ve heyecan dolu…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/buz-devri-2-erime-basliyor-2006-izle.webp", backdrop = "", year = "2006", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/buz-devri-2-erime-basliyor/", category = "Film"),
    Movie(id = 1000053, title = "Buz Devri", overview = "Buzul Çağı’nın hüküm sürdüğü dünyada, dondurucu soğuklar ve zorlu yaşam koşulları hayvanları hayatta kalabilmek için mücadele etmeye zorlar. Bu tehlikeli dönemde yolları kesişen üç sıra dışı dost, kendilerini beklenmedik bir maceranın içinde bulur. Kendi hâlinde bir mamut, güçlü ve kurnaz bir kılıç dişli kaplan ile yaramaz bir tembel hayvan, buldukları insan bebeğini ailesine ulaştırmak için birlikte yola çıkar. Birbirlerinden oldukça farklı karakterlere sahip olan bu üçlü, yol boyunca karşılaştıkları tehlikeleri aşmaya çalışırken dostluğun ve dayanışmanın önemini keşfeder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/buz-devri-2002-izle.png", backdrop = "", year = "2002", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/buz-devri-2002-izle/", category = "Film"),
    Movie(id = 1000054, title = "İyi Olan Kazansın", overview = "CIA bünyesinde görev yapan son derece yetenekli iki ajan, aynı zamanda birbirlerinin en yakın dostu ve güvenilir iş ortağıdır. Dünyanın en tehlikeli düşmanlarına karşı omuz omuza mücadele eden bu ikilinin kusursuz ortaklığı, aynı kadına âşık olmalarıyla sarsılır. Lauren’ın kalbini kazanmak isteyen iki ajan, sahip oldukları üstün becerileri ve gelişmiş teknolojik imkânları bu kez birbirlerine karşı kullanmaya başlar. Bir zamanlar birlikte görev yapan iki yakın arkadaş, şimdi aşk uğruna kıyasıya bir rekabete girişirken olaylar aksiyon ve komedi dolu bir maceraya dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/iyi-olan-kazansin-2012-izle.webp", backdrop = "", year = "2012", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/iyi-olan-kazansin/", category = "Film"),
    Movie(id = 1000055, title = "Gözüm Üzerinizde", overview = "Ailelerinden ve günlük hayatın stresinden biraz uzaklaşmak isteyen bir grup erkek, mahallelerinin güvenliğini sağlamak bahanesiyle bir suç gözetleme ekibi kurar. Başlangıçta yalnızca birlikte vakit geçirip kafa dağıtmayı amaçlayan bu ekip, beklenmedik olayların yaşanmasıyla kendilerini ciddi bir maceranın içinde bulur. Çok geçmeden karşılarına çıkan gizemli bir komplo, yalnızca mahallelerini değil, tüm dünyayı tehdit eden büyük bir tehlikenin parçası olduklarını ortaya çıkarır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/gozum-uzerinizde-2012-izle.webp", backdrop = "", year = "2012", score = 5.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/gozum-uzerinizde/", category = "Film"),
    Movie(id = 1000056, title = "Aşk Yemini", overview = "Paige ve Leo, hayatlarını birlikte geçirmeye karar vermiş, birbirlerine tutkuyla bağlı genç bir çifttir. Ancak geçirdikleri talihsiz bir kaza, mutluluklarını bir anda altüst eder. Paige’in yıllarca komada kalmasının ardından yeniden hayata dönmesi, Leo için büyük bir sevinç olsa da bu mutluluk kısa sürede yerini derin bir üzüntüye bırakır. Çünkü Paige, kazadan önceki yaşamını ve sevdiği adamla paylaştığı anıların çoğunu hatırlamamaktadır. Leo, karısının kalbinde yeniden yer edinebilmek için geçmişte yaşadıkları güzel günleri yeniden canlandırmaya çalışır. Şimdi onu bekleyen en büyük mücadele, hafızasını kaybeden kadına aşklarını yeniden hissettirmek ve ilişkilerini baştan inşa…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/ask-yemini-2012-izle.webp", backdrop = "", year = "2012", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ask-yemini-2012-izle/", category = "Film"),
    Movie(id = 1000057, title = "Aşkın Büyüsü", overview = "Cornell Üniversitesi’nde veterinerlik eğitimi alan Jacob Jankowski, mezuniyet sınavlarına hazırlandığı sırada anne ve babasını korkunç bir trafik kazasında kaybeder. Yaşadığı büyük acının ardından eğitimini yarıda bırakan genç adam, kendisini gezici bir sirkin treninde bulur. Veterinerlik bilgisini fark eden sirk sahibi, hayvanların bakımını Jacob’a emanet eder. Burada, eğitilmesi oldukça güç olan Rosie adlı fil ile arasında özel bir bağ kurulur. Ancak Jacob’ın hayatı yalnızca hayvanlarla ilgilenmekten ibaret değildir; sirkin sert mizaçlı eğitmeni August ve onun büyüleyici eşi Marlena ile kurduğu ilişkiler, genç adamı aşk, tutku ve tehlike arasında zor bir seçime…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/askin-buyusu-2011-izle.webp", backdrop = "", year = "2011", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/askin-buyusu-2011-izle/", category = "Film"),
    Movie(id = 1000058, title = "Hayat Sana Güzel", overview = "Mitch ve Dave, çocukluk yıllarından beri dost olmalarına rağmen yetişkinlik döneminde bambaşka yollara sapmıştır. Dave, ailesi ve yoğun iş hayatıyla uğraşırken Mitch, özgürlüğünün tadını çıkararak sorumluluk almaktan kaçınır. Her ikisi de diğerinin yaşamına özenirken birlikte geçirdikleri bir gecenin ardından kendilerini hiç beklemedikleri bir durumun içinde bulurlar: Bedenleri değişmiştir. Artık Mitch, Dave’in aile ve kariyer sorumluluklarını üstlenmek; Dave ise Mitch’in dağınık yaşamına ayak uydurmak zorundadır. Üstelik çevrelerindeki insanların da işleri zorlaştırmasıyla ikili, eski hayatlarına dönebilmek için birbirinden komik olaylarla mücadele eder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hayat-sana-guzel-2011-izle.webp", backdrop = "", year = "2011", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hayat-sana-guzel-2011-izle/", category = "Film"),
    Movie(id = 1000059, title = "Büyük Yarış", overview = "Hayatlarını kuş gözlemciliğine adamış üç adam, Kuzey Amerika’nın dört bir yanında nadir türleri keşfetmek ve yılın en başarılı gözlemcisi olmak için kıyasıya bir yarışa girişir. Her biri bu mücadeleye farklı beklentilerle katılırken yolculuk boyunca hava koşulları, beklenmedik aksilikler ve kişisel sorunlarla yüzleşmek zorunda kalır. Başlangıçta yalnızca bir rekabet gibi görünen bu serüven, zamanla hayata dair önemli dersler barındıran bir yolculuğa dönüşür. Owen Wilson, Jack Black ve Jim Parsons’ın başrollerini paylaştığı film, doğa sevgisini mizah ve insan ilişkileriyle buluşturur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/buyuk-yaris-2011-izle.webp", backdrop = "", year = "2011", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/buyuk-yaris-2011-izle/", category = "Film"),
    Movie(id = 1000060, title = "Korku Gecesi", overview = "Charlie Brewster, lisede popülerliğiyle dikkat çeken ve güzel bir kız arkadaşı olan sıradan bir genç gibi görünür. Ancak yeni komşusu Jerry’nin mahalleye taşınmasıyla hayatı korkunç bir hal almaya başlar. İlk bakışta oldukça çekici ve nazik biri olan Jerry’nin davranışlarından şüphelenen Charlie, onun aslında insanları avlayan tehlikeli bir vampir olduğunu keşfeder. Ne var ki annesi ve arkadaşları, Charlie’nin uyarılarına inanmaz. Genç adam, kimsenin kendisine yardım etmeyeceğini anlayınca hem sevdiklerini korumak hem de kanlı bir felaketi önlemek için kendi mücadelesini vermek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/korku-gecesi-2011-izle.webp", backdrop = "", year = "2011", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/korku-gecesi-2011-izle/", category = "Film"),
    Movie(id = 1000061, title = "Hayatım Yalan", overview = "Danny, başarılı kariyerine rağmen özel hayatında işleri biraz karıştıran bir plastik cerrahtır. Genç ve güzel bir öğretmene gönlünü kaptırınca, geçmişte söylediği bir yalanı sürdürmek zorunda kalır. Çözüm olarak asistanı Katherine’den boşanma aşamasındaki eşi rolünü üstlenmesini ister. Fakat Katherine’in çocuklarının da katıldığı bu plan, beklenmedik gelişmelerle bambaşka bir boyuta ulaşır. Hawaii’ye uzanan bu karmaşık yolculukta karakterler, birbirinden komik durumlarla karşılaşırken aşkın ve dürüstlüğün önemini de yeniden keşfeder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hayatim-yalan-2011-izle.webp", backdrop = "", year = "2011", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hayatim-yalan/", category = "Film"),
    Movie(id = 1000062, title = "Rango", overview = "Hayatı boyunca tehlikelerden uzak yaşayan Rango, beklenmedik bir olay sonucunda kendisini çölün ortasındaki kanunsuz Toprak kasabasında bulur. Birbirinden tuhaf ve tehlikeli canlıların yaşadığı bu yerde, tesadüfler onu kasabanın yeni şerifi haline getirir. Herkesin büyük umutlar bağladığı Rango, başlangıçta yalnızca dikkat çekmek için sergilediği kahramanlık numaralarını gerçeğe dönüştürmek zorunda kalır. Ancak karşısına çıkan acımasız düşmanlar ve zorlu sınavlar, onun yalnızca başkalarını değil, kendisini de tanımasını sağlayacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/rango-2011-izle.webp", backdrop = "", year = "2011", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/rango-2011-izle/", category = "Film"),
    Movie(id = 1000063, title = "Repo Men", overview = "Teknolojinin ilerlemesiyle yapay organların üretildiği bir gelecekte, ölümcül hastalıklarla mücadele etmek artık eskisi kadar zor değildir. İnsanlar, ihtiyaç duydukları organları satın alarak yaşamlarını sürdürebilir. Fakat bu yenilikçi çözümün ciddi bir koşulu vardır: Borçlarını zamanında ödeyemeyenlerin organları şirket tarafından geri alınabilir. İnsan hayatının ticari bir sözleşmeye bağlandığı bu acımasız düzende, ödeme yapamamak ölümcül sonuçlara yol açabilecek bir tehdide dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/repo-men-2010-izle.webp", backdrop = "", year = "2010", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/repo-men-2010-izle/", category = "Film"),
    Movie(id = 1000064, title = "Burlesque", overview = "Ali, müzik tutkusunu gerçeğe dönüştürmek ve büyük bir şarkıcı olmak isteyen genç bir kadındır. Hayallerine ulaşmak için Los Angeles’a giden Ali, ihtişamlı geçmişine rağmen eski popülerliğini kaybetmiş Burlesque Lounge adlı mekânda garson olarak işe başlar. Zamanla buranın büyülü atmosferine kapılan Ali, bir gün sahneye çıkıp kendi sesini duyurmaya karar verir. Yeteneğini kanıtlamak ve hayallerine bir adım daha yaklaşmak için tüm cesaretini ortaya koymaya hazırdır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/burlesque-2010-izle.webp", backdrop = "", year = "2010", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/burlesque-2010-izle/", category = "Film"),
    Movie(id = 1000065, title = "Karantina 2: Terminal", overview = "Bir yolcu uçağında ortaya çıkan gizemli bir virüs, yolcuların hayatını kısa sürede ölümcül bir tehlikeye sürükler. Uçak iniş yaptıktan sonra bölge karantina altına alınır ve dış dünyayla bağlantılar kesilir. Uçakta mahsur kalan yolcular, ne olduğunu tam olarak anlayamadıkları bu salgının ortasında hayatta kalmanın yollarını arar. Virüsün hızla yayılması ve belirsizliğin giderek büyümesiyle korku, panik ve güvensizlik herkesi etkisi altına alır. Kurtuluş umutları giderek azalırken yolcular, hem hastalığın yarattığı tehditle hem de içinde bulundukları kapalı ortamın tehlikeleriyle mücadele etmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/quarantine-2-terminal-2011-izle.webp", backdrop = "", year = "2011", score = 5.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/karantina-2-terminal/", category = "Film"),
    Movie(id = 1000066, title = "Karantina", overview = "Televizyon muhabiri Angela Vidal ve kameramanı, Los Angeles itfaiyesinin gece vardiyasını konu alan bir haber hazırlamak için itfaiyecilere eşlik eder. Başlangıçta sıradan görünen gece, acil yardım hattına gelen bir ihbarla bir anda korkunç bir kâbusa dönüşür. Ekip, küçük bir apartmandan yükselen çığlıklar üzerine olay yerine gider ve davranışları açıklanamayan bir kadınla karşılaşır. Ancak olayın arkasındaki gizem çözülmeden bina karantinaya alınır ve içeridekilerin dış dünyayla tüm bağlantısı kesilir. Angela ve ekibi, kapana kısıldıkları bu yerde hayatta kalmaya çalışırken yaşanan dehşeti kameraya kaydetmeye devam eder. Binada olup bitenleri aydınlatabilecek tek kanıt, geride…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/quarantine-2008-izle.webp", backdrop = "", year = "2008", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/karantina-2008-izle/", category = "Film"),
    Movie(id = 1000067, title = "Hitman: Ajan 47", overview = "İnsanüstü yeteneklere sahip olması için özel olarak geliştirilen Ajan 47, soğukkanlılığı ve kusursuz suikast becerileriyle tanınan ölümcül bir tetikçidir. Boynunun arkasındaki barkod, onun kimliğini belirleyen en önemli işarettir. Ancak 47’nin yeni görevi, kendi sırlarını açığa çıkarmak ve aynı yöntemlerle kendisi gibi suikastçılar üretmek isteyen güçlü bir şirketin planlarını durdurmaktır. Bu tehlikeli yolculukta Katia adlı genç bir kadının desteğini alan ajan, geçmişine dair beklenmedik gerçekleri keşfeder. Peşindeki düşmanlarla mücadele ederken kendi varlığının ardındaki gizemi de çözmeye çalışan 47, giderek büyüyen bir komplonun içinde hayatta kalmak için tüm yeteneklerini kullanır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hitman-ajan-47-2015-izle.webp", backdrop = "", year = "2015", score = 5.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hitman-ajan-47-2015-izle/", category = "Film"),
    Movie(id = 1000068, title = "Hitman", overview = "Profesyonel bir suikastçı olarak yetiştirilen Ajan 47, kusursuz planları, soğukkanlılığı ve ölümcül yetenekleriyle tanınmaktadır. Hayatını gizlilik ve disiplin üzerine kuran 47, bu kez kendisini beklenmedik bir komplonun ortasında bulur. Doğu Avrupa’da gerçekleştirdiği görevlerin ardından hedef hâline gelen ajan, kimlerin kendisini ortadan kaldırmak istediğini ve bu tuzağın arkasında hangi sırların bulunduğunu çözmeye çalışır. Ancak yalnızca karanlık güçler değil, Interpol ve Rus ordusu da peşine düşmüştür. Kaçış ve gerçeği ortaya çıkarma mücadelesi veren Ajan 47, hayatta kalmak için bütün yeteneklerini kullanmak zorunda kalacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hitman-2007-izle.webp", backdrop = "", year = "2007", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hitman-2007-izle/", category = "Film"),
    Movie(id = 1000069, title = "Son Şarkı", overview = "Hayatındaki değişimlere uyum sağlamakta zorlanan Ronnie, babasıyla yaşadığı kırgınlıklar nedeniyle ona karşı duvar örmüştür. Annesinin isteği üzerine yaz aylarını babasının yaşadığı sahil kasabasında geçirmek zorunda kalınca, kendisini istemediği bir ortamda bulur. Fakat burada tanıştığı Will ile yaşadığı romantik yakınlaşma, düşüncelerini ve hayata bakışını yavaş yavaş değiştirir. Kızıyla yeniden bağ kurmayı isteyen Steve, geçmişte kaybettikleri yakınlığı müzik sayesinde geri kazanmaya çalışır. Ronnie bir yandan ilk aşkın heyecanını yaşarken diğer yandan ailesiyle ilişkisini yeniden değerlendirmeye başlar. Sevgi, affetme ve büyümenin anlamını işleyen bu hikâye, insanın hayatında yeni bir sayfa açabileceğini hatırlatır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-last-song-2010-izle.webp", backdrop = "", year = "2010", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/son-sarki-2010-izle/", category = "Film"),
    Movie(id = 1000070, title = "Durdurulamaz", overview = "Deneyimli bir tren makinisti ile genç bir kondüktör, kontrolden çıkarak hızla ilerleyen sürücüsüz bir treni durdurmak için zamana karşı amansız bir mücadeleye girişir. İçinde tehlikeli yükler bulunan tren, kalabalık yerleşim bölgelerine doğru ilerlerken olası bir felaketin önüne geçmek için bütün seçenekler değerlendirilir. Yetkililer treni durdurmanın yollarını ararken iki demiryolu çalışanı, sınırlı imkânlarla büyük bir faciayı önlemeye çalışır. Her geçen saniyenin hayati önem taşıdığı bu tehlikeli mücadelede, trenin raydan çıkmasını ve yüzlerce insanın hayatının tehlikeye girmesini engellemek için cesaretlerini ve tecrübelerini ortaya koymaları gerekir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/durdurulamaz-2010-izle.webp", backdrop = "", year = "2010", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/durdurulamaz-2010-izle/", category = "Film"),
    Movie(id = 1000071, title = "Hırsızlar Şehri", overview = "Boston’ın Charlestown bölgesi, kuşaklar boyunca banka soygunları ve organize suçlarla anılan bir yer olmuştur. Bu çevrede yetişen Doug MacRay, birbirine aile kadar bağlı bir soyguncu grubunun lideridir. Hayatını suç üzerine kuran Doug, işini tehlikeye atmamak için kimseyle duygusal bağ kurmamaya özen gösterir. Ancak bir banka soygunu sırasında şube müdürü Claire Keesey’i rehin almak zorunda kalması, tüm dengeleri değiştirir. Claire’e karşı beklemediği duygular geliştiren Doug, bir yandan geçmişinden kurtulup yeni bir hayat kurmayı düşünürken diğer yandan hem ekibini hem de kendisini tehdit eden tehlikelerle yüzleşmek zorunda kalır. Aşk, sadakat ve suç…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hirsizlar-sehri-2010-izle.webp", backdrop = "", year = "2010", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hirsizlar-sehri-2010-izle/", category = "Film"),
    Movie(id = 1000072, title = "Yine mi Sen?", overview = "Lise yıllarının unutulmaz anıları, bazen insanın peşini yıllar geçse bile bırakmaz. Başarılı bir halkla ilişkiler uzmanı olan Marni, ağabeyinin evlilik hazırlıkları nedeniyle memleketine döndüğünde geçmişiyle yüzleşmek zorunda kalır. Çünkü ağabeyinin evleneceği kadın, okul yıllarında Marni’ye hayatı zehir eden eski düşmanından başkası değildir. Üstelik gelin, geçmişte yaptıklarını unutmuş ve hiçbir şey yaşanmamış gibi davranmaktadır. Aileler bir araya geldiğinde işler daha da karışır. Gelinin teyzesi ile Marni’nin annesi arasında da yıllar öncesine dayanan bir husumet ortaya çıkar. Eski hesapların yeniden açıldığı bu düğün hazırlıkları, kahkaha dolu bir hesaplaşmaya dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/yine-mi-sen-2010-izle.webp", backdrop = "", year = "2010", score = 5.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yine-mi-sen-2010-izle/", category = "Film"),
    Movie(id = 1000073, title = "İlişki Durumu: Karmaşık", overview = "Jane, boşandığı eşi Jake ile yıllar içinde dostça bir ilişki kurmuş ve üç yetişkin çocuğuyla hayatında yeni bir denge oluşturmuştur. Ancak bir mezuniyet töreni için birlikte şehir dışına çıktıklarında, aralarındaki eski çekim yeniden ortaya çıkar. Jake’in başka bir kadınla evli olması, bu yakınlaşmayı daha da karmaşık hâle getirir. Tam da bu sırada Jane’in evindeki mutfak yenileme işini üstlenen mimar Adam, ona âşık olmaya başlar. Bir yanda geçmişten gelen duygular, diğer yanda yeni bir ilişkinin heyecanı vardır. Jane, kendisini beklenmedik bir aşk üçgeninin içinde bulurken hem kalbinin sesini dinlemek hem de…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/iliski-durumu-karmasik-2009-izle.webp", backdrop = "", year = "2009", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/iliski-durumu-karmasik/", category = "Film"),
    Movie(id = 1000074, title = "Suretler", overview = "Teknolojinin insan hayatını tamamen değiştirdiği bir gelecekte, insanlar kendi kusursuz robot kopyaları olan suretler aracılığıyla dünyayla iletişim kurmaktadır. Sağlıklı, genç ve kusursuz görünümlü bu makineler, kullanıcılarının evlerinden çıkmadan dış dünyayı deneyimlemelerine olanak tanır. Ancak bir üniversite öğrencisinin gizemli biçimde öldürülmesi, bu kusursuz düzenin ardındaki karanlık sırları gün yüzüne çıkarır. FBI ajanları Greer ve Peters, cinayeti araştırırken suret teknolojisinin yaratıcısına uzanan tehlikeli bir soruşturmanın içine sürüklenir. İnsanların gerçek kimliklerini gizlediği bu dünyada ajanlar, kime güvenebileceklerini ve görünenin ardındaki gerçeğin ne olduğunu ortaya çıkarmak zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/suretler-2009-izle.webp", backdrop = "", year = "2009", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/suretler-2009-izle/", category = "Film"),
    Movie(id = 1000075, title = "Aşkzede", overview = "Mütevazı bir müzisyen olan Peter, uzun süredir birlikte olduğu televizyon yıldızı sevgilisi Sarah tarafından terk edilince büyük bir hayal kırıklığı yaşar. Ayrılığın acısını geride bırakmak ve biraz kafa dinlemek için Hawaii’ye tatile gitmeye karar verir. Ancak burada Sarah’ın yeni sevgilisiyle karşılaşması, kaçış planını tam bir kâbusa dönüştürür. Kıskançlık ve hayal kırıklığıyla baş etmeye çalışan Peter, otelde çalışan sevimli resepsiyoniste yakınlaşarak eski sevgilisini unutmaya çalışır. Fakat yeni bir başlangıç yapmak, geçmişin izlerinden kurtulmak kadar kolay olmayacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/askzede-2008-izle.webp", backdrop = "", year = "2008", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/askzede-2008-izle/", category = "Film"),
    Movie(id = 1000076, title = "Avustralya", overview = "İkinci Dünya Savaşı’nın gölgesinde geçen Avustralya, Nicole Kidman ve Hugh Jackman’ı unutulmaz bir aşk hikâyesinde buluşturuyor. İngiliz aristokrat Lady Sarah Ashley, kendisine miras kalan geniş toprakları yönetmek için Avustralya’ya gelir. Ancak bu yeni hayatta onu bekleyen zorluklar, alıştığı dünyadan çok farklıdır. Sarah, istemese de sert mizacı ve asi tavırlarıyla tanınan sığır sürücüsü Drover ile iş birliği yapmak zorunda kalır. Başlangıçta birbirlerine karşı mesafeli olan ikili, zamanla tutkulu bir aşka sürüklenir. Fakat tam da yeni bir hayat kurmaya çalışırken savaşın acımasız yüzüyle karşılaşırlar. Japon kuvvetlerinin Darwin şehrine düzenlediği saldırı, hem geleceklerini…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/australia-2008-izle.webp", backdrop = "", year = "2008", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/avustralya-2008-izle/", category = "Film"),
    Movie(id = 1000077, title = "Charlie’nin Çikolata Fabrikası", overview = "Willy Wonka’nın gizemlerle dolu çikolata fabrikasının kapıları açıldığında, ziyaretçileri hayal gücünün sınırlarını zorlayan olağanüstü bir dünya beklemektedir. Çikolata Nehri’nde yolculuk yapmaktan naneli şekerlerle kaplı çimenleri keşfetmeye, tuhaf icatlarla dolu odalardan yetenekli sincapların çalıştığı Fındık Odası’na kadar her köşe birbirinden şaşırtıcı sürprizlerle doludur. Bu eşsiz maceraya katılma şansını yakalayan çocuklar, altın biletleri sayesinde hayatları boyunca unutamayacakları bir deneyim yaşar. Ancak fabrikanın renkli ve büyüleyici atmosferinin ardında, sabır ve karakterlerini sınayacak beklenmedik olaylar da vardır. Tim Burton’ın yönetmenliğini üstlendiği, Johnny Depp ve Freddie Highmore’un başrollerinde yer aldığı film, Roald Dahl’ın sevilen eserini…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/charlienin-cikolata-fabrikasi-2005-izle.webp", backdrop = "", year = "2005", score = 6.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/charlienin-cikolata-fabrikasi/", category = "Film"),
    Movie(id = 1000078, title = "Sınırları Aşmak", overview = "1955 yılında, J. R. Cash adını kullanan genç bir müzisyen, büyük bir çıkış yapma umuduyla Memphis’teki Sun Stüdyolarının kapısını çalar. Elindeki gitarı, kendine özgü tarzı ve derin, karanlık sesiyle diğer sanatçılardan ayrılan Cash, müzik dünyasında iz bırakacak uzun bir yolculuğun ilk adımlarını atmaktadır. Şarkılarında hayatın zorluklarını, aşkı, kayıpları ve insan ruhunun derinliklerini anlatan genç müzisyen, zamanla Amerikan müziğinin en etkili isimlerinden birine dönüşecektir. Şöhrete uzanan bu yolculukta yaşadığı kişisel mücadeleler ve duygusal ilişkiler, yalnızca kariyerini değil, hayatının geri kalanını da şekillendirecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/sinirlari-asmak-2005-izle.webp", backdrop = "", year = "2005", score = 7.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sinirlari-asmak-2005-izle/", category = "Film"),
    Movie(id = 1000079, title = "İki Fıstık", overview = "FBI ajanları Kevin Copeland ve Marcus Copeland, başarısız operasyonları yüzünden kariyerlerinin en kötü dönemini yaşamaktadır. Son görevlerinde de istedikleri sonucu alamayınca, önemli bir kaçırılma vakası rakipleri Vincent Gomez ve Jake Harper’a verilir. Kevin ve Marcus’a ise sosyeteden iki şımarık kardeş olan Brittany ve Tiffany Wilson’ı havaalanından alıp Hamptons’taki otellerine götürme görevi düşer. Ancak yolda yaşanan talihsiz bir kaza, genç kadınların yüzlerinde küçük yaralanmalara neden olur. Dış görünüşlerine fazlasıyla önem veren kardeşler, katılmaları gereken davete gitmeyi reddedince ajanların aklına çılgınca bir fikir gelir. İşlerini ve itibarlarını kurtarmak isteyen Kevin ile Marcus,…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/iki-fistik-2004-izle.webp", backdrop = "", year = "2004", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/iki-fistik-2004-izle/", category = "Film"),
    Movie(id = 1000080, title = "Acemi Prenses 2: Kraliyet Nişanı", overview = "Genovia Prensesi Mia, 21 yaşına girmesinin ardından büyükannesi Kraliçe Clarice ile birlikte sarayda yaşamını sürdürmektedir. Ancak tahta çıkma zamanı geldiğinde, kraliyet ailesinin geleceğini tehdit eden beklenmedik bir engelle karşılaşır. Tahtta hak iddia eden Vikont Mabrey, evli olmayan bir kadının kraliçe olamayacağını öne süren eski bir yasayı gündeme getirerek Mia’nın taç giymesini engellemeye çalışır. Parlamentonun da desteğini arkasına alan Mabrey’ye karşı Kraliçe Clarice, torununa uygun bir eş bulabilmesi için 30 günlük süre kazandırır. Bu sırada Mia, Mabrey’nin yeğeni Nicholas ile tanışır ve aralarında karşılıklı bir çekim oluşur. Ancak genç adamın kimliğini…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/acemi-prenses-2-kraliyet-nisani-2004-izle.webp", backdrop = "", year = "2004", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/acemi-prenses-2-kraliyet-nisani/", category = "Film"),
    Movie(id = 1000081, title = "Acemi Prenses", overview = "Mia, San Francisco’da annesiyle birlikte yaşayan, sıradan bir hayat süren 15 yaşında bir genç kızdır. Okul hayatı ve günlük sorunlarıyla uğraşan Mia’nın dünyası, babasının ölümünün ardından öğrendiği şaşırtıcı bir gerçekle tamamen değişir. Genovia adlı küçük bir Avrupa ülkesinin prensesi olduğunu öğrenen genç kız, kendisini hiç alışık olmadığı bir yaşamın içinde bulur. Kraliyet ailesinin bir parçası olmak üzere Genovia’ya giden Mia’yı, ona prenses olmanın inceliklerini öğretmeye kararlı büyükannesi beklemektedir. Görgü kurallarından duruşuna kadar pek çok konuda eğitim almaya başlayan Mia, bir yandan yeni kimliğine alışmaya çalışırken diğer yandan gençliğin getirdiği zorluklarla…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/acemi-prenses-2001-izle.webp", backdrop = "", year = "2001", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/acemi-prenses-2001-izle/", category = "Film"),
    Movie(id = 1000082, title = "Gizli Gerçek", overview = "Norman Spencer, bilimsel çalışmalarına odaklanmış başarılı bir genetik uzmanıdır. Eşi Claire ise kızlarının üniversite için evden ayrılmasının ardından kendisini yalnız hissetmeye başlar. Yeni evlerinde sakin bir hayat sürdürmeye çalışırken açıklanması mümkün olmayan olaylar, çiftin huzurunu kaçırır. Kapıların sebepsiz yere açılması ve çevrelerinde yaşanan gizemli kayboluşlar, Claire’in dikkatini çeker. Banyoda karşılaştığı ürkütücü görüntüler ise olayların sıradan bir tesadüf olmadığını düşünmesine yol açar. Fakat Norman, eşinin anlattıklarını stresin ve yalnızlığın bir sonucu olarak görür. Claire, kimsenin kendisine inanmadığı bu süreçte yaşadıklarının ardındaki gerçeği tek başına araştırmaya karar verir. Her yeni ipucu onu…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/gizli-gercek-2000-izle.webp", backdrop = "", year = "2000", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/gizli-gercek-2000-izle/", category = "Film"),
    Movie(id = 1000083, title = "Demir Maskeli Adam", overview = "Yıllar önce cesaretleri ve kahramanlıklarıyla Fransa’nın en ünlü savaşçıları arasında yer alan Üç Silahşörler, artık birbirinden farklı hayatlar sürmektedir. Athos oğlunu büyütürken sakin bir yaşamı tercih etmiş, Porthos geçmişteki büyük savaşları özlemeye başlamış, Aramis ise din adamı olmuştur. Yalnızca d’Artagnan, silahşörlerin lideri olarak krala hizmet etmeye devam etmektedir. Ancak 1660 yılında Fransa, acımasız ve kibirli Kral XIV. Louis’nin yönetiminde karanlık günlerden geçmektedir. Bastille Hapishanesi’nde yaklaşık on yıldır yüzü demir bir maskeyle gizlenen gizemli bir mahkûmun varlığı ise ülkenin kaderini değiştirebilecek bir sırrı barındırır. Eski dostlar, Fransa’yı kurtarmak ve mahkûmun gerçek…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-man-in-the-iron-mask-1998-izle.webp", backdrop = "", year = "1998", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/demir-maskeli-adam/", category = "Film"),
    Movie(id = 1000084, title = "Kaya", overview = "San Francisco, tarihin en büyük tehditlerinden biriyle karşı karşıyadır. Eski bir asker olan General Hummel, devletin gizli görevlerde hayatını kaybeden askerlerini inkâr etmesine tepki olarak tehlikeli bir planı hayata geçirir. Adamlarıyla birlikte ölümcül kimyasal gaz taşıyan roketleri ele geçiren Hummel, Alcatraz Adası’nı kontrol altına alarak içerideki 81 turisti rehin tutar. Taleplerinin kabul edilmemesi durumunda roketleri şehre fırlatacağını duyurur. Hükümetin krizi çözmek için kurduğu özel ekipte, FBI’ın kimyasal silah uzmanı Dr. Stanley Goodspeed de yer alır. Fakat adaya girmek ve silahlı askerleri etkisiz hâle getirmek için alışılmışın dışında birine ihtiyaç vardır.…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kaya-1996-izle.webp", backdrop = "", year = "1996", score = 7.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kaya-1996-izle/", category = "Film"),
    Movie(id = 1000085, title = "Roket Adam", overview = "1930’lu yıllarda dünya, II. Dünya Savaşı’nın eşiğine gelirken uluslararası gerilim giderek artmakta ve casusluk faaliyetleri hız kazanmaktadır. Bu çalkantılı dönemde, sırtına takılarak uçmayı sağlayan sıra dışı bir roket düzeneği, genç pilot Cliff Secord’un eline geçer. Nazilerin de ele geçirmek istediği bu icat, Cliff’in hayatını tamamen değiştirir. Cihazı kullanarak gerçekleştirdiği cesur hareketler sayesinde halkın dikkatini çeken genç pilot, kısa sürede Rocketeer adıyla tanınan bir kahramana dönüşür. Ancak kazandığı şöhret, onu tehlikeli bir mücadelenin ortasına sürükler. Naziler peşine düşerken Cliff, yalnızca kendi hayatını değil, sevdiği kadın Jenny’nin güvenliğini de korumak zorunda kalır.…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-rocketeer-1991-izle.webp", backdrop = "", year = "1991", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/roket-adam-1991-izle/", category = "Film"),
    Movie(id = 1000086, title = "Hayalet Sürücü 2: İntikam Ateşi", overview = "Johnny Blaze, Hayalet Sürücü olarak karanlık güçlerle mücadelesini sürdürürken kendisini Doğu Avrupa’da tehlikeli bir görevin içinde bulur. Nicolas Cage’in yeniden canlandırdığı karakter, insan bedenine kavuşmaya çalışan şeytanın planlarını bozmak ve kendi lanetinden kurtulmak için zamana karşı yarışır. Ancak bu mücadele, Blaze’in yalnızca doğaüstü düşmanlarla değil, kendi içindeki karanlıkla da yüzleşmesini gerektirir. Crank ve Gamer filmleriyle tanınan Mark Neveldine ve Brian Taylor’ın yönetmen koltuğunu paylaştığı yapım, yüksek tempolu aksiyon sahnelerini fantastik unsurlarla bir araya getiriyor. Türkiye ve Romanya’nın etkileyici mekânlarında çekilen film, Hayalet Sürücü’nün karanlık dünyasını yeniden beyazperdeye taşıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hayalet-surucu-2-intikam-atesi-2011-izle.webp", backdrop = "", year = "2011", score = 4.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hayalet-surucu-2-intikam-atesi/", category = "Film"),
    Movie(id = 1000087, title = "Hayalet Sürücü", overview = "Johnny Blaze, motosikletiyle gerçekleştirdiği nefes kesici gösteriler sayesinde ün kazanan ve milyonlarca insanın hayranlığını toplayan cesur bir motosiklet sürücüsüdür. Ancak gösterişli yaşamının ardında karanlık bir geçmiş ve ağır bir bedel saklıdır. Yıllar önce sevdiği kadının hayatını kurtarmak için şeytanla anlaşma yapan Johnny, bunun karşılığında ruhunu karanlığa teslim etmiştir. Geceleri şeytanın hizmetinde çalışan doğaüstü bir varlığa dönüşen Johnny, kendi kaderiyle yüzleşmek ve içindeki karanlık güçle mücadele etmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hayalet-surucu-2007-izle.webp", backdrop = "", year = "2007", score = 5.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hayalet-surucu-2007-izle/", category = "Film"),
    Movie(id = 1000088, title = "Mumya", overview = "1932 yılında başlayan ve yıllar boyunca korku sinemasının unutulmaz hikâyeleri arasında yer alan Mumya efsanesi, antik çağlardan günümüze uzanan karanlık bir macerayla yeniden hayat buluyor. Yüzyıllardır mühürlü bir mezarda saklı kalan antik bir kraliçe, gerçekleştirilen bir askeri operasyon sırasında tesadüfen keşfedilir. Mezarı açıldığında uykusundan uyanan kraliçe, geçmişte uğradığı ihanetin intikamını almak için harekete geçer. İçinde biriken öfkeyle modern dünyaya adım atan bu kadim güç, insanlığı kendi hâkimiyeti altına almayı hedefler. Ancak onun uyanışı, dünyayı geri dönüşü olmayan bir karanlığa sürükleyebilecek korkunç olayların başlangıcı olacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/mumya-2017-izle.webp", backdrop = "", year = "2017", score = 5.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/mumya-2017-izle/", category = "Film"),
    Movie(id = 1000089, title = "Koruyucu", overview = "Denizde hayat kurtarmak için yıllarını harcayan deneyimli kurtarma yüzücüsü Ben Randall, büyük bir fırtınada yaşanan felaketin ardından hayatta kalan tek kişi olur. Bu olay, hem mesleki hayatını hem de ruhsal dünyasını derinden etkiler. Görevine ara vermek yerine genç adayları eğitmek üzere bir kurtarma yüzücülüğü okuluna gönderilen Ben, karşısında yetenekli ancak kendilerine fazlasıyla güvenen bir grup genç bulur. Onlara disiplinin, dayanıklılığın ve ekip çalışmasının önemini anlatmaya çalışırken geçmişte yaşadığı acılarla da yüzleşir. Eğitim ilerledikçe gençler, bu mesleğin gerçek anlamının tehlikeye atılmak değil, başkalarının hayatını kurtarmak için doğru kararları verebilmek olduğunu öğrenir.…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-guardian-2006-izle.webp", backdrop = "", year = "2006", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/koruyucu-2006-izle/", category = "Film"),
    Movie(id = 1000090, title = "İskoçya’nın Son Kralı", overview = "Hayallerinin peşinden giden genç doktor Nicholas Garrigan, mesleğini icra etmek ve ihtiyaç sahiplerine yardım etmek için Uganda’ya yerleşir. Ülkenin lideri Idi Amin ile yollarının kesişmesi, ona beklemediği bir fırsat sunar. Zekâsı ve zor durumlarda gösterdiği beceri sayesinde Amin’in güvenini kazanan Garrigan, kısa sürede liderin yakın çevresine dâhil olur. Başlangıçta kendisini ayrıcalıklı hisseden doktor, zaman geçtikçe Amin’in yönetimindeki korku dolu gerçeklerle karşılaşır. Şiddetin ve siyasi baskının giderek arttığı bu ortamda, içinde bulunduğu durumdan kurtulmak sandığından çok daha zor olacaktır. Forest Whitaker’ın Idi Amin rolündeki güçlü oyunculuğuyla dikkat çeken film, gerçek tarihsel…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/iskocyanin-son-krali-2006-izle.webp", backdrop = "", year = "2006", score = 7.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/iskocyanin-son-krali/", category = "Film"),
    Movie(id = 1000091, title = "Hayatımın Maçı", overview = "20. yüzyılın başlarında, yeteneğiyle golf dünyasında adından söz ettirmeye başlayan Harry Vardon, kısa sürede şampiyonluğa uzanır. Ancak başarısına rağmen, işçi sınıfından gelmesi ve alışılmış İngiliz centilmenlik anlayışına uymaması nedeniyle önyargılarla mücadele etmek zorunda kalır. Aradan on iki yıl geçtikten sonra, genç Amerikalı golfçü Francis Ouimet de benzer engellerle karşılaşır. Golfün seçkinlere ait bir spor olarak görüldüğü dönemde Ouimet, yeteneğini kanıtlamak ve kendisine duyulan kuşkuları boşa çıkarmak için büyük bir fırsat yakalar. Üstelik bu fırsat, hayranlık duyduğu Harry Vardon’a karşı Amerika Açık’ta mücadele etmesini sağlayacaktır. İki golfçünün yollarını kesiştiren bu karşılaşma,…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hayatimin-maci-2005-izle.webp", backdrop = "", year = "2005", score = 7.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hayatimin-maci/", category = "Film"),
    Movie(id = 1000092, title = "Buz Prensesi", overview = "On yedi yaşındaki Casey Carlyle, Harvard başvurusunda kullanmak üzere yaz tatilinde bir fizik projesi hazırlamakla görevlendirilir. Artistik patinaja ilgi duyan Casey, bu sporun arkasındaki fizik kurallarını araştırmaya karar verir ve eski profesyonel patenci Tina Harwood’un işlettiği paten kulübünü ziyaret eder. Araştırmasını daha iyi anlayabilmek için buz üzerinde kendisi de çalışmaya başlayan Casey, kısa sürede artistik patenin büyüleyici dünyasına kapılır. Başlangıçta yalnızca akademik bir çalışma olarak gördüğü bu uğraş, zamanla en büyük tutkusuna dönüşür. Ancak önünde önemli bir seçim vardır: Ailesinin ve öğretmenlerinin beklentilerine uygun şekilde Harvard’a hazırlanmak mı, yoksa hayallerinin…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/buz-prensesi-2005-izle.webp", backdrop = "", year = "2005", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/buz-prensesi-2005-izle/", category = "Film"),
    Movie(id = 1000093, title = "Saklambaç", overview = "Eşinin trajik ölümünün ardından psikolog David Callaway, dokuz yaşındaki kızı Emily ile yeniden yakınlaşmaya çalışır. Yaşadığı büyük kaybın etkisinden kurtulamayan Emily, babasının eski öğrencisi Dr. Katherine Carson’dan aldığı psikolojik destek sayesinde yavaş yavaş toparlanıyor gibi görünür. Kızına daha huzurlu bir yaşam sunmak isteyen David, New York’tan ayrılarak sakin bir kasabaya taşınmaya karar verir. Ancak Emily’nin Charlie adını verdiği gizemli bir hayali arkadaş edinmesiyle evdeki huzur bozulmaya başlar. Başlangıçta masum görünen bu arkadaş, zamanla ürkütücü olayların ve tehlikeli oyunların merkezine yerleşir. David, kızının hayal dünyasıyla gerçeklik arasındaki sınırları sorgulamasına neden olan…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hide-and-seek-2005-izle.webp", backdrop = "", year = "2005", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/saklambac-2005-izle/", category = "Film"),
    Movie(id = 1000094, title = "Anka’nın Uyanışı", overview = "Moğolistan’ın ıssız çöllerinde meydana gelen uçak kazası, bir grup yolcunun hayatını bir anda altüst eder. Medeniyetten uzakta, zorlu doğa koşullarıyla çevrili bir bölgede mahsur kalan kazazedeler, giderek tükenen erzaklarıyla hayatta kalmaya çalışır. Ancak tehlike yalnızca doğadan gelmez; bölgedeki yağmacıların saldırıları da grubu çaresiz bir durumla karşı karşıya bırakır. Kurtulabilmek için akıl almaz bir plan yapan yolcular, parçalanmış uçağın enkazından yeni bir uçak yapmaya karar verir. Dennis Quaid’in rol aldığı film, umudun tükenmeye başladığı anlarda bile pes etmeyen insanların zamana ve doğaya karşı verdiği nefes kesici mücadeleyi anlatıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/flight-of-the-phoenix-2004-izle.webp", backdrop = "", year = "2004", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ankanin-uyanisi/", category = "Film"),
    Movie(id = 1000095, title = "Beni Unutma", overview = "New York’un başarılı ve tanınmış modacılarından Melanie Carmichael, şehrin gözde bekârlarından biriyle evlenmeye hazırlanırken geçmişinden gelen bir sorunla yüzleşmek zorunda kalır. Henüz lise yıllarında Jake adında bir gençle evlenen Melanie, yıllar önce geride bıraktığını düşündüğü bu evliliği resmen sona erdirememiştir. Boşanmayı kabul etmeyen Jake ile son bir kez konuşmak için Alabama’ya giden Melanie, eski hayatının izleriyle yeniden karşılaşır. Ancak memleketine dönüşü, yalnızca geçmişteki meseleleri çözmekle kalmayacak, aşk ve mutluluk hakkındaki düşüncelerini de değiştirecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/beni-unutma-2002-izle.webp", backdrop = "", year = "2002", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/beni-unutma-2002-izle/", category = "Film"),
    Movie(id = 1000096, title = "Kırmızı Değirmen", overview = "1899 yılında, hayallerinin peşinden gitmek isteyen genç şair Christian, babasının isteklerine karşı çıkarak Paris’in sanat ve eğlence hayatıyla ünlü Montmartre semtine yerleşir. Burada, Moulin Rouge’un göz kamaştırıcı yıldızlarından Satin ile tanışır ve kısa sürede ona âşık olur. Satin de Christian’a karşı aynı duyguları beslemeye başlar. Ancak Satin’in zengin ve nüfuzlu erkeklerin ilgisini çeken geçmişi, bu aşkın önündeki en büyük engellerden biridir. Tutku, müzik ve ihtişamla çevrili bu ilişki, ikisini de hayatlarını değiştirecek zorlu bir sınavla karşı karşıya bırakır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kirmizi-degirmen-2001-izle.webp", backdrop = "", year = "2001", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kirmizi-degirmen/", category = "Film"),
    Movie(id = 1000097, title = "Büyülü Çift", overview = "21. yüzyılın yoğun temposunda kariyerine odaklanan Kate ile 19. yüzyılın asil ve centilmen dükü Leopold’ün hayatları, beklenmedik bir zaman yolculuğuyla birbirine bağlanır. Gizemli bir tablonun yardımıyla kendi döneminden kopup geleceğe gelen Leopold, kendisini Kate’in dünyasında bulur. Modern yaşama alışmaya çalışırken Kate ile arasında gelişen yakınlık, ikisinin de aşka ve hayata bakışını değiştirir. Ancak farklı yüzyıllarda şekillenen alışkanlıkları ve geçmişle gelecek arasındaki uçurum, bu ilişkinin önüne sıra dışı engeller çıkarır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/buyulu-cift-2001-izle.webp", backdrop = "", year = "2001", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/buyulu-cift/", category = "Film"),
    Movie(id = 1000098, title = "Düşman Hattı", overview = "Batı Avrupa üzerinde keşif görevi yapan pilot Chris Burnett ve takım arkadaşı Stackhouse, uçuş sırasında beklenmedik bir saldırıya uğrayarak uçaklarının düşürülmesiyle kendilerini büyük bir tehlikenin içinde bulur. Stackhouse düşmanların eline geçerken Burnett, yabancı bir bölgede tek başına hayatta kalmanın yollarını arar. Peşindeki askerlerden kaçmaya çalışan pilotu kurtarmak için komutanı Reigart harekete geçer. Ancak bölgede yaşananlar, basit bir kurtarma operasyonundan çok daha karmaşık bir durumun habercisidir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/dusman-hatti-2001-izle.webp", backdrop = "", year = "2001", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/dusman-hatti-2001-izle/", category = "Film"),
    Movie(id = 1000099, title = "İçimdeki Çocuk", overview = "Russ Duritz, başarılı bir imaj danışmanı olarak hayatını sürdürürken beklenmedik bir olayla karşılaşır: Bir anda sekiz yaşındaki hali Rusty ile yüz yüze gelir. Sevimli ama sosyal ilişkilerinde oldukça beceriksiz olan küçük Rusty, Russ’a geçmişte yaşadığı hayal kırıklıklarını ve çocukluğunda derin izler bırakan acıları yeniden hatırlatır. Geçmişiyle yüzleşmek zorunda kalan Russ, yıllardır geride bıraktığını düşündüğü sorunların aslında hayatını hâlâ etkilediğini fark etmeye başlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/icimdeki-cocuk-2000-izle.webp", backdrop = "", year = "2000", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/icimdeki-cocuk/", category = "Film"),
    Movie(id = 1000100, title = "60 Saniye", overview = "Bir zamanların efsanevi araba hırsızı Randall “Memphis” Raines, suç dünyasını geride bırakarak sakin bir hayat kurmayı başarmıştır. Ancak eski bir dostunun çaresizce yardım istemesi, onu yeniden direksiyon başına geçmeye zorlar. Kardeşinin hayatını kurtarmak için zamana karşı yarışan Memphis’in tek bir gece içinde 50 otomobili çalması gerekmektedir. Geçmişteki ustalığını yeniden ortaya koymak zorunda kalan deneyimli hırsız, hem tehlikeli düşmanlarla mücadele edecek hem de imkânsız görünen bu görevi tamamlamaya çalışacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/60-saniye-2000-izle.webp", backdrop = "", year = "2000", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/60-saniye-2000-izle/", category = "Film"),
    Movie(id = 1000101, title = "Erkekler Ağlamaz", overview = "Nebraska’nın küçük Falls kasabasında Brandon Teena, karizmatik kişiliği ve gizemli geçmişiyle kısa sürede herkesin dikkatini çeker. Yeni arkadaşlıklar kuran ve Lana ile tutkulu bir ilişkiye başlayan Brandon, geçmişine dair sakladığı gerçekler nedeniyle kendisini giderek daha tehlikeli bir durumun içinde bulur. Toplumun önyargıları, dışlanma ve acımasız düşmanlıklarla karşı karşıya kalan genç adamın hayatı, gizli kimliğinin ortaya çıkmasıyla trajik bir dönüm noktasına ulaşır. Gerçek olaylardan uyarlanan bu etkileyici dram, kimlik, aşk ve hoşgörüsüzlüğün yıkıcı sonuçlarını gözler önüne seriyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/boys-dont-cry-1999-izle.webp", backdrop = "", year = "1999", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/erkekler-aglamaz/", category = "Film"),
    Movie(id = 1000102, title = "Umut Dalgaları", overview = "Hayatının aşkıyla evlendiğini ve mutlu bir yuva kurduğunu düşünen Birdee’nin dünyası, eşinin ihanetiyle bir anda değişir. Üstelik bu ihanetin içinde en yakın arkadaşı da vardır. Acısını bir televizyon programında dile getirmesinin ardından memleketine dönen Birdee, küçük kasabada herkesin kendisini konuştuğunu görür. Kızıyla birlikte annesinin evine yerleşen genç kadın, ailevi sıkıntılar ve yalnızlıkla mücadele ederken hayata karşı umudunu da kaybetmeye başlar. Ancak Justin ile tanışması, kalbinin yeniden iyileşebileceğini ve en karanlık günlerin ardından bile yeni bir başlangıcın mümkün olduğunu hatırlatır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hope-floats-1998-izle.webp", backdrop = "", year = "1998", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/umut-dalgalari/", category = "Film"),
    Movie(id = 1000103, title = "Sessiz Düşman", overview = "Hayatın farklı sınavlarından geçen iki adam, kendilerini tahmin edemedikleri bir mücadelenin içinde bulur. Kaderin kendisine hazırladığı zorluklarla boğuşan bir adam ile görevini her şeyin üzerinde tutan bir diğerinin karşılaşması, ikisinin de hayatını kökten değiştirecek olayları beraberinde getirir. Bilinmeyene doğru ilerlerken inançlarını, bağlılıklarını ve uğruna savaşmaya değer gördükleri şeyleri sorgulamak zorunda kalırlar. Harrison Ford ve Brad Pitt’i bir araya getiren film, yoğun atmosferi ve karakterler arasındaki gerilimle izleyiciyi içine çekiyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-devils-own-1997-izle.webp", backdrop = "", year = "1997", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sessiz-dusman/", category = "Film"),
    Movie(id = 1000104, title = "Büyücüler Kulübü", overview = "Hayatında yeni bir sayfa açmak isteyen Sarah, ailesiyle birlikte taşındığı şehirde kendisini gizemli olayların ortasında bulur. Yeni okulunda kara büyüye ilgi duyan üç kızla tanışması, onun sıradan yaşamını tamamen değiştirir. Grubun dördüncü üyesi olarak kabul edilen Sarah, arkadaşlarıyla birlikte doğaüstü yetenekler kazanmaya başlar. Başlangıçta aşk, popülerlik ve kişisel istekleri için kullandıkları bu güçler, genç kızların giderek daha tehlikeli kararlar almasına neden olur. Büyünün karanlık yüzü ortaya çıktıkça dostluk, kıskançlık ve kontrol arzusu arasında amansız bir mücadele başlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/buyuculer-kulubu-1996-izle.webp", backdrop = "", year = "1996", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/buyuculer-kulubu/", category = "Film"),
    Movie(id = 1000105, title = "İngiliz Hasta", overview = "II. Dünya Savaşı sırasında Sahra Çölü’nde haritalama çalışmaları yapan kâşif Laszlo Almásy, geçirdiği uçak kazasının ardından ağır yanıklarla yatağa mahkûm olur. İtalya’daki eski bir manastıra yerleştirilen Almásy’nin bakımını, Hanna adındaki genç bir hemşire üstlenir. Savaşın yıkıcı atmosferinden uzakta başlayan bu sessiz yaşam, Almásy’nin geçmişine dair anıların yavaş yavaş gün yüzüne çıkmasıyla farklı bir boyut kazanır. Gizemli geçmişi, yaşadığı büyük aşk ve savaşın izleri, onun hikâyesini yeniden şekillendirir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/ingiliz-hasta-1996-izle.webp", backdrop = "", year = "1996", score = 7.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ingiliz-hasta/", category = "Film"),
    Movie(id = 1000106, title = "Sakıncalı Düşünceler", overview = "LouAnne Johnson, askerlik kariyerini geride bırakarak öğretmenlik yapmaya karar verir ve zorlu bir öğrenci grubunun bulunduğu lisede göreve başlar. Hayatın farklı zorluklarıyla mücadele eden, eğitim sistemine ve otoriteye güvenini kaybetmiş gençlerle karşılaşan Johnson, onların yalnızca derslerde değil, yaşamda da başarılı olabilmeleri için çabalar. Öğrencilerinin potansiyelini ortaya çıkarmak adına geleneksel eğitim anlayışına meydan okuyan öğretmenin hikâyesini anlatan Sakıncalı Düşünceler, gerçek olaylardan esinlenen güçlü anlatımı ve akılda kalıcı müzikleriyle dikkat çekiyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/sakincali-dusunceler-1995-izle.webp", backdrop = "", year = "1995", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sakincali-dusunceler/", category = "Film"),
    Movie(id = 1000107, title = "Bebek Firarda", overview = "Hayatı boyunca lüks içinde yaşayan küçük Bink, üç suçlunun onu kaçırıp ailesinden fidye istemesiyle kendisini beklenmedik bir maceranın ortasında bulur. Eddie, Norby ve Veeko, kolay bir iş yaptıklarına inanırken meraklı bebeğin ellerinden kaçmasıyla planları tamamen bozulur. Şehirde kendi başına dolaşmaya başlayan Bink, karşılaştığı yeni yerleri keşfederken onu yakalamaya çalışan üç adamı da peşinden sürükler. Basit bir kaçırma girişimi, art arda yaşanan kazalar ve komik olaylarla kontrolden çıkar. Bebek Firarda, küçücük bir kahramanın farkında olmadan üç yetişkinin hayatını nasıl altüst ettiğini anlatan, eğlenceli ve sıcacık bir komedi macerası.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/bebek-firarda-1994-izle.webp", backdrop = "", year = "1994", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/bebek-firarda/", category = "Film"),
    Movie(id = 1000108, title = "Birkaç İyi Adam", overview = "Daniel Kaffee, davalarını mahkemeye taşımadan sonuçlandırmasıyla ün kazanmış genç bir Donanma avukatıdır. Ancak Küba sınırındaki bir askeri birlikte yaşanan ölüm vakası, onun alışılmış çalışma yöntemlerini değiştirmek zorunda kalmasına yol açar. Olayla bağlantılı iki asker cinayetle suçlanırken savunmalarını verilen emirleri yerine getirdikleri üzerine kurar. Meslektaşı JoAnne Galloway ise olayın basit bir askeri disiplin meselesi olmadığını düşünerek kapsamlı bir yargılama için mücadele eder. Kaffee, başlangıçtaki isteksizliğine rağmen davayı üstlenir ve araştırmalarını derinleştirdikçe karşısında çok daha karmaşık bir tablo bulur. Gerçeği açığa çıkarmak için askeri hiyerarşiye meydan okuması gereken avukat, kariyerinin en önemli…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/birkac-iyi-adam-1992-izle.webp", backdrop = "", year = "1992", score = 7.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/birkac-iyi-adam/", category = "Film"),
    Movie(id = 1000109, title = "Kokteyl", overview = "Askerlik görevini tamamladıktan sonra New York’ta kendine yeni bir hayat kurmaya çalışan Brian Flanigan, üniversite diploması olmadığı için eğitimine devam etmeye karar verir. Geçimini sağlamak amacıyla bir barda çalışmaya başlayan Brian, deneyimli barmen Doug Coughlin’in rehberliğinde mesleğin inceliklerini öğrenir. Kısa sürede şehrin gözde barmenleri arasına giren ikili, daha fazla kazanmak ve farklı bir yaşam sürmek için Jamaika’ya gider. Brian burada Jordan adında genç bir kadına âşık olur. Ancak ilişkileri, Jordan’ın hayatına giren zengin ve yaşlı bir adam nedeniyle çıkmaza sürüklenir. Aşk, hırs ve hayaller arasında kalan Brian, hayatında neyin gerçekten…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/cocktail-1988-izle.webp", backdrop = "", year = "1988", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kokteyl-1988-izle/", category = "Film"),
    Movie(id = 1000110, title = "Komando", overview = "Emekli özel kuvvetler albayı John Matrix, küçük kızı Jenny ile birlikte sakin bir yaşam sürmektedir. Ancak geçmişinden gelen düşmanlar kızını kaçırınca huzurlu hayatı bir anda altüst olur. Jenny’yi kurtarmak için Matrix’ten bir Latin Amerika ülkesinin başkanına suikast düzenlemesi ve acımasız bir diktatörün yeniden iktidara gelmesine yardım etmesi istenir. Bu tehlikeli görevi kabul etmek zorunda kalan Matrix, kendisini götüren uçaktan kaçmayı başarır ve kızını kurtarmak için zamana karşı amansız bir mücadeleye girişir. Karşısına çıkan silahlı birlikleri ve ölümcül tuzakları aşarken geçmişteki savaşçı kimliğini yeniden ortaya çıkarır. Arnold Schwarzenegger’in unutulmaz performansıyla öne…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/commando-1985-izle.webp", backdrop = "", year = "1985", score = 6.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/komando-1985-izle/", category = "Film"),
    Movie(id = 1000111, title = "Deniz Kızı", overview = "Hayatını işine adayan Allen, bir gün karşısına gerçek aşkın çıkacağına inanmaz. Ancak yaşadığı deniz kazasının ardından gizemli bir kadın tarafından kurtarılması, tüm düşüncelerini değiştirir. Madison adındaki bu sıra dışı kadınla tanıştıktan sonra ikili arasında unutulmaz bir aşk başlar. Her şey yolunda görünürken Madison’ın kimliğine ilişkin ortaya çıkan ipuçları, ilişkilerini zor bir sınavla karşı karşıya bırakır. İnsanların onun hakkındaki gerçeği öğrenmesiyle Allen ve Madison, aşklarını korumak için büyük bir karar vermek zorunda kalır. Bu romantik ve fantastik öykü, farklı dünyalardan gelen iki insanın sevgi uğruna neleri göze alabileceğini anlatıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/splash-1984-izle.webp", backdrop = "", year = "1984", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/deniz-kizi-1984-izle/", category = "Film"),
    Movie(id = 1000112, title = "Addams Ailesi 2", overview = "Morticia ve Gomez’in çocukları artık büyümüştür ve aile bireyleri arasındaki yakınlık zamanla azalmaya başlamıştır. Eski günlerdeki birlikteliği yeniden kazanmak isteyen Pugsley ile Fester Amca, aileyi bir yolculuğa çıkarmaya karar verir. Perili karavanlarıyla Amerika’yı baştan başa geçmek üzere yola koyulan ekip, sıradan bir tatilden çok daha fazlasıyla karşılaşır. Birbirinden garip olayların yaşandığı bu yolculukta, tuhaf karakterler ve ikonik kuzen It ile yollarının kesişmesi, eğlenceli çatışmalara ve kahkaha dolu anlara neden olur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-addams-family-2-2021-izle.webp", backdrop = "", year = "2021", score = 5.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/addams-ailesi-2-2021-izle/", category = "Film"),
    Movie(id = 1000113, title = "Addams Ailesi", overview = "Karanlık mizahı ve kendilerine özgü yaşam tarzlarıyla alışılmış aile anlayışının çok dışında bir hayat sürmektedir. Ailenin merkezinde, sevdiklerini bir arada tutan Morticia ve karısına tutkuyla bağlı, enerjik Gomez yer alır. Zeki ve sivri dilli Wednesday ile tehlikeli maceralara bayılan küçük Pugsley de bu sıra dışı ailenin vazgeçilmez üyeleridir. Çılgın Fester ve tuhaf lezzetler hazırlayan Büyükanne de evdeki eğlenceli karmaşayı tamamlar. Ancak aile, yaklaşan kutlamalarına hazırlanırken kusursuz banliyö yaşamına hayran olan televizyon yıldızı Margaux Needler ile karşı karşıya gelir. Birbirinden tamamen farklı iki dünyanın çatışması, Addams Ailesi için beklenmedik olayların başlangıcı…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/addams-ailesi-2019-izle.webp", backdrop = "", year = "2019", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/addams-ailesi-2019-izle/", category = "Film"),
    Movie(id = 1000114, title = "The Flash", overview = "Barry Allen, laboratuvarda sürdürdüğü bilimsel çalışmalar sırasında hayatını sonsuza dek değiştirecek bir olay yaşar. Şiddetli bir fırtına sırasında düşen yıldırım, laboratuvardaki kimyasallarla birleşerek Barry’nin olağanüstü güçler kazanmasına yol açar. Kısa süre sonra en dikkat çekici yeteneğinin akıl almaz bir hızla hareket etmek olduğunu fark eder. Sahip olduğu bu gücü insanlara yardım etmek için kullanmaya karar veren Barry, Central City sokaklarında suçlulara karşı savaşan bir kahramana dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-flash-2023-izle.webp", backdrop = "", year = "2023", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/the-flash-2023-izle/", category = "Film"),
    Movie(id = 1000115, title = "İyi ki Aldatılmışım!", overview = "Babi, düğününe yalnızca bir gün kala uzun süredir birlikte olduğu Caio’nun kendisini aldattığını öğrenir. Hayallerinin yıkılmasıyla ilişkisini bitiren genç aktris, geçmişini geride bırakıp hayatında yeni bir sayfa açmaya karar verir. Bu süreçte karşısına çıkan gizemli yargıç Marco, kısa sürede ilgisini çekmeyi başarır. Marco’nun çekici tavırları ve sakladığı sırlar Babi’yi kendine doğru çekerken, bu yeni ilişkinin düşündüğünden çok daha karmaşık ve tehlikeli olabileceği ortaya çıkar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/iyi-ki-aldatilmisim-2023-izle.webp", backdrop = "", year = "2023", score = 4.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/iyi-ki-aldatilmisim/", category = "Film"),
    Movie(id = 1000116, title = "Dert Etme Sevgilim", overview = "Alice ve Jack, her şeyin kusursuz göründüğü Victory adlı deneysel bir yerleşim bölgesinde ayrıcalıklı bir hayat sürmektedir. Şirketin CEO’su Frank tarafından şekillendirilen bu toplulukta erkekler gizemli bir proje üzerinde çalışırken kadınlar konforlu evlerinin ve sorunsuz görünen yaşamlarının tadını çıkarır. Victory, sakinlerine ihtiyaç duydukları her şeyi sunmakta, karşılığında ise mutlak gizlilik ve şirkete koşulsuz bağlılık beklemektedir. Başlangıçta bu düzenin içinde mutlu olan Alice, zamanla çevresinde yaşanan tuhaf olaylardan şüphelenmeye başlar. Kusursuz görünen hayatının ardında açıklanamayan gerçeklerin saklandığını fark ettikçe yaşadığı dünyayı sorgular. Gerçeği öğrenmeye kararlı olan Alice, hem kendi hayatını hem…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/dert-etme-sevgilim-2022-izle.webp", backdrop = "", year = "2022", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/dert-etme-sevgilim/", category = "Film"),
    Movie(id = 1000117, title = "Babil", overview = "1920’li yıllarda Hollywood, sessiz sinemadan sesli filmlere geçişle birlikte köklü bir değişim yaşamaktadır. Sinema dünyasının yeniden şekillendiği bu dönem, bir yandan yıldızların parladığı ve yeni fırsatların doğduğu bir çağı temsil ederken diğer yandan aşırılıklar, skandallar ve kaçınılmaz çöküşlerle anılır. Babylon, şöhretin cazibesine kapılan oyuncuların, sinema sektöründe yükselmeye çalışan isimlerin ve hayallerinin peşinden giden insanların iç içe geçmiş hikâyelerini anlatıyor. Hırsın, ihtişamın ve kontrolsüz yaşamın ön plana çıktığı bu dönemde karakterler, başarıya ulaşmak uğruna büyük bedeller ödemek zorunda kalır. Hollywood’un görkemli yükselişini ve karanlık yüzünü gözler önüne seren film, şöhretin hem…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/babil-2022-izle.webp", backdrop = "", year = "2022", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/babil-2022-izle-1/", category = "Film"),
    Movie(id = 1000118, title = "Himaye", overview = "Dünyanın en başarılı suikastçıları arasında yer alan Anna ve Rembrandt, yıllardır tehlikeli görevlerde karşı karşıya gelen iki amansız rakiptir. Geçmişleri sırlarla dolu olan ikili, yüksek profilli hedefleri ortadan kaldırmak için sürekli birbirleriyle rekabet etmektedir. Ancak Anna’nın hem akıl hocası hem de en güvendiği insanlardan biri olan Moody’nin öldürülmesi, her şeyi değiştirir. Bu cinayetin ardındaki gerçeği ortaya çıkarmaya kararlı olan Anna, beklenmedik bir şekilde eski rakibi Rembrandt ile iş birliği yapmak zorunda kalır. İkili, Moody’nin katilini bulmak ve intikamını almak için tehlikeli bir yolculuğa çıkarken kendilerini ihanetlerin, gizli bağlantıların ve ölümcül…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-protege-2021-izle.webp", backdrop = "", year = "2021", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/himaye-2021-izle/", category = "Film"),
    Movie(id = 1000119, title = "Canavar Avcısı", overview = "Artemis, Birleşmiş Milletler’e bağlı seçkin bir askeri birliğin lideri olarak tehlikeli görevlerde ekibine öncülük etmektedir. Ancak gizemli bir doğa olayı, onu ve askerlerini hiç bilmedikleri bir evrene sürükler. Bu yabancı dünyada devasa canavarlar hüküm sürmekte ve hayatta kalmak neredeyse imkânsız hâle gelmektedir. Çevresini saran tehlikelerle baş etmeye çalışan Artemis, bu yaratıkları avlama konusunda uzmanlaşmış gizemli bir savaşçıyla tanışır. İkili, farklı yöntemlerine rağmen ortak bir amaç uğruna güçlerini birleştirir. Çünkü bu korkunç varlıkların Dünya’ya ulaşmasını sağlayabilecek portal, yalnızca onların bulunduğu gezegeni değil, bütün insanlığı da tehdit etmektedir. Artemis ve Hunter, her…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/canavar-avcisi-2020-izle.webp", backdrop = "", year = "2020", score = 5.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/canavar-avcisi/", category = "Film"),
    Movie(id = 1000120, title = "Doktor Uyku", overview = "Çocukluğunda yaşadığı korkunç olayların izlerini hâlâ taşıyan Danny, geçmişinin yarattığı acılarla başa çıkmaya çalışırken kendini alkolün pençesinde bulur. Babasından miras kalan şiddet ve umutsuzluk döngüsünü kırmak isteyen Danny, New Hampshire’da yeni bir hayat kurarak destek grubuna katılır. Sahip olduğu özel yetenek sayesinde hayatının sonuna yaklaşan insanlara huzur veren Danny, bir bakım evinde çalışmaya başlar. Ancak ülkenin dört bir yanını dolaşan ve True Knot adıyla bilinen gizemli bir topluluk, onun hayatını yeniden karanlığa sürükleyecektir. Dışarıdan sıradan ve zararsız görünen bu grubun üyeleri, psişik güçlere sahip çocukları hedef alarak onların enerjisiyle yaşamlarını…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/doktor-uyku-2019-izle.webp", backdrop = "", year = "2019", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/doktor-uyku-2019-izle/", category = "Film"),
    Movie(id = 1000121, title = "İfşa Günü", overview = "Kansas City’de bir televizyon kanalında hava durumu sunuculuğu yapan Margaret Fairchild, kariyerinde daha önemli gazetecilik görevleri üstlenmenin hayalini kurar. Canlı yayın sırasında açıklanamayan bir olayla karşılaşması, hayatını ve mesleki geleceğini tamamen değiştirir. Olayın dünya dışı varlıklarla bağlantılı olabileceği ihtimali gündeme gelirken yetkililer gerçeğin ortaya çıkmasını engellemeye çalışır. Bu sırada UFO’lar ve uzaylı yaşamına ilişkin gizli bilgileri arşivleyen WARDEX adına çalışan siber güvenlik uzmanı Dr. Daniel Kellner, kamuoyunu bilgilendirmek için harekete geçer. Ancak örgütün yöneticisi Noah Scanlon, siyasi çıkarlarını korumak uğruna bu sırların açığa çıkmasını önlemeye kararlıdır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/ifsa-gunu-2026-izle.webp", backdrop = "", year = "2026", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ifsa-gunu-2026-izle/", category = "Film"),
    Movie(id = 1000122, title = "Pokemon: Dedektif Pikachu", overview = "Başarılı dedektif Harry Goodman’ın gizemli bir şekilde ortadan kaybolması, 21 yaşındaki oğlu Tim’i gerçeği ortaya çıkarmak için harekete geçirir. Araştırması sırasında babasının eski ortağı olan Dedektif Pikachu ile yolları kesişir. Hafızasını kaybetmiş olmasına rağmen keskin zekâsı ve esprili kişiliğiyle dikkat çeken Pikachu, Tim’in en büyük yardımcısı olur. Birbirlerini anlayabildiklerini keşfeden ikili, insanların ve Pokémonların bir arada yaşadığı Ryme Şehri’nde ipuçlarının peşine düşer. Ancak sıradan bir kayıp vakası gibi görünen olay, tüm Pokémon dünyasını tehlikeye atabilecek büyük bir komplonun ortaya çıkmasıyla çok daha karmaşık bir hâl alır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/pokemon-dedektif-pikachu-2019-izle.webp", backdrop = "", year = "2019", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/pokemon-dedektif-pikachu/", category = "Film"),
    Movie(id = 1000123, title = "Deniz Feneri", overview = "20. yüzyılın başlarında, Maine kıyılarından uzakta bulunan ıssız bir adaya gönderilen genç Ephraim Winslow, deneyimli deniz feneri bekçisi Thomas Wake’in yanında çalışmaya başlar. Başlangıçta sıradan bir iş gibi görünen bu görev, iki adamın arasındaki gerilim giderek arttıkça karanlık bir mücadeleye dönüşür. Thomas’ın otoriter tavırları ve Ephraim üzerindeki baskısı, adadaki yaşamı dayanılmaz hâle getirir. Fırtınalar ve yalnızlık içinde birbirlerinden başka kimseleri olmayan iki adam, zamanla gerçeklikle hayal arasındaki sınırı kaybetmeye başlar ve kendi korkularıyla yüzleşmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/deniz-feneri-2019-izle.webp", backdrop = "", year = "2019", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/deniz-feneri-2019-izle/", category = "Film"),
    Movie(id = 1000124, title = "Sarışın Bomba", overview = "MI6’in en yetenekli ve tehlikeli ajanlarından Lorraine Broughton, Soğuk Savaş’ın gölgesindeki Berlin’e gizli bir görev için gönderilir. Bir ajanın öldürülmesini araştırması ve kayıp ajanların listesini ele geçirmesi gereken Lorraine, operasyon boyunca Berlin istasyon şefi David Percival ile birlikte çalışır. Ancak şehirdeki entrikalar ve art arda yaşanan ihanetler, görevini giderek daha tehlikeli hâle getirir. Kısa süre içinde kendi teşkilatından birilerinin kendisine tuzak kurduğunu anlayan Lorraine, gerçeği ortaya çıkarmak ve hayatta kalmak için tüm yeteneklerini kullanmak zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/sarisin-bomba-2017-izle.webp", backdrop = "", year = "2017", score = 6.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sarisin-bomba/", category = "Film"),
    Movie(id = 1000125, title = "Hayat", overview = "Mars’ta yaşamın izlerine rastlanması, insanlık tarihinin en önemli keşiflerinden birinin kapısını aralar. Uluslararası bir uzay istasyonunda görev yapan altı astronot, Kızıl Gezegen’den elde ettikleri örnekleri incelemeye başladığında dünya dışı bir yaşam formunun varlığını doğrulayabilecek bulgulara ulaşır. Ancak araştırmalar derinleştikçe keşfettikleri canlının tahmin ettiklerinden çok daha zeki ve tehlikeli olduğunu fark ederler. Uzaydaki bu heyecan verici görev, kısa sürede hayatta kalmak için verilen amansız bir mücadeleye dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/hayat-2017-izle.webp", backdrop = "", year = "2017", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hayat-2017-izle/", category = "Film"),
    Movie(id = 1000126, title = "Everest", overview = "Dünyanın en yüksek dağı Everest’e tırmanmak için yola çıkan iki farklı dağcı ekibi, beklenmedik bir kar fırtınasının ortasında kalır. Başlangıçta zorlu bir tırmanış olarak görülen yolculuk, hava koşullarının hızla kötüleşmesiyle ölüm kalım mücadelesine dönüşür. Dondurucu soğuk, azalan oksijen ve şiddetli fırtına, dağcıların hayatta kalma şansını giderek azaltırken ekip üyeleri hem doğanın acımasız gücüyle hem de kendi sınırlarıyla yüzleşmek zorunda kalır. Baltasar Kormákur’un yönettiği film, 1996 yılında Everest’te yaşanan gerçek bir felaketten esinleniyor. Jake Gyllenhaal, Josh Brolin, Jason Clarke ve John Hawkes’ın rol aldığı yapım, insanın doğa karşısındaki çaresizliğini ve hayatta…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/everest-2015-izle.webp", backdrop = "", year = "2015", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/everest-2015-izle/", category = "Film"),
    Movie(id = 1000127, title = "Operasyon Valkyrie", overview = "İkinci Dünya Savaşı’nın en çalkantılı döneminde, Nazi Almanyası’nın gidişatını değiştirmek isteyen bir grup Alman subayı, Adolf Hitler’i ortadan kaldırmak için gizli bir plan hazırlar. Savaşın sona ermesini ve ülkenin daha büyük bir yıkıma sürüklenmesini engellemeyi amaçlayan bu grup, rejime karşı harekete geçmek için kapsamlı bir operasyon düzenler. Planın merkezinde yer alan Albay Claus von Stauffenberg, Hitler’e yönelik suikast girişiminin ardından Valkyrie Operasyonu’nu kullanarak Nazi yönetimini devirmeyi hedefler. Ancak başarıya ulaşmak için attıkları her adım, onları daha büyük bir tehlikeyle karşı karşıya bırakır. Bryan Singer’ın yönettiği filmde Stauffenberg’i Tom Cruise canlandırıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/operasyon-valkyrie-2008-izle.webp", backdrop = "", year = "2008", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/operasyon-valkyrie/", category = "Film"),
    Movie(id = 1000128, title = "Ben Efsaneyim", overview = "Dünya genelinde yayılan ölümcül bir virüs, insanlığın büyük bölümünü yok ederken geride kalanları da korkunç bir felaketin içine sürükler. Bu kıyamet sonrası dünyada New York’ta yaşamını sürdüren bilim insanı Robert Neville, virüse karşı doğal bağışıklık geliştirmiş nadir kişilerden biridir. Yıllardır tek başına hayatta kalmaya çalışan Neville, bir yandan salgının nedenlerini araştırırken diğer yandan kendisi gibi kurtulan insanlara ulaşmaya çalışır. Elindeki en büyük umut ise kendi kanını kullanarak virüsün etkilerini tersine çevirecek bir tedavi geliştirmektir. Ancak tehlikelerle dolu bu dünyada zaman giderek daralırken Neville, insanlığın geleceği için son bir mücadele vermek…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/ben-efsaneyim-2007-izle.webp", backdrop = "", year = "2007", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ben-efsaneyim/", category = "Film"),
    Movie(id = 1000129, title = "Charlie Wilson’ın Savaşı", overview = "Amerikan siyasetinin perde arkasında gelişen gerçek bir hikâyeden uyarlanan film, Kongre üyesi Charlie Wilson’ın Afganistan’daki Sovyet işgaline karşı yürütülen mücadelede üstlendiği sıra dışı rolü anlatıyor. Komünizme karşı çıkan Wilson, zengin sosyetik Joanne Herring’in desteğiyle Afgan direnişçilere gizlice silah ve finansman sağlanması için girişimlerde bulunur. CIA ajanı Gust Avrakotos’un da sürece dâhil olmasıyla bu çabalar giderek büyüyen bir operasyona dönüşür. Siyasi zekâ, kişisel ilişkiler ve uluslararası çıkarların iç içe geçtiği bu süreç, Sovyetler Birliği’nin Afganistan’daki varlığına karşı verilen mücadelenin önemli bir parçası hâline gelir. Film, gerçek olayları mizah ve politik dram…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/charlie-wilsonin-savasi-2007-izle.webp", backdrop = "", year = "2007", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/charlie-wilsonin-savasi/", category = "Film"),
    Movie(id = 1000130, title = "Çevirmen", overview = "Birleşmiş Milletler’de çevirmen olarak çalışan Silvia Broome, sıradan görünen hayatının bir anda tehlikeli bir olayın merkezine dönüşeceğinden habersizdir. Afrika’da doğup büyüyen Silvia, bir devlet başkanına yönelik suikast planına kulak misafiri olduğunda kendisini uluslararası bir komplonun içinde bulur. Olayın ardından genç kadını korumakla görevlendirilen FBI ajanı Tobin Keller ise başlangıçta onun anlattıklarına şüpheyle yaklaşır. Ancak birlikte araştırma yaptıkça karşılarına çıkan gerçekler, ikisinin de hayatını tehlikeye atar. Suikastı engellemeye çalışan Silvia ve Tobin, kendilerini giderek daralan bir çemberin içinde bulurken kime güvenebileceklerini de sorgulamak zorunda kalır. Sydney Pollack’ın yönettiği film, siyasi entrikaları…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/cevirmen-2005-izle.webp", backdrop = "", year = "2005", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cevirmen-2005-izle/", category = "Film"),
    Movie(id = 1000131, title = "Soğuk Dağ", overview = "Amerikan İç Savaşı’nın sona ermesiyle geride yıkım, acı ve kayıplarla dolu bir ülke kalır. Savaşın izlerini hem bedeninde hem de ruhunda taşıyan genç asker Inman’ın hayata tutunmasını sağlayan tek şey, büyük bir aşkla bağlı olduğu Ada’ya yeniden kavuşma umududur. Ada da Inman gibi, birlikte özgürce yaşayabilecekleri huzurlu bir geleceğin hayalini kurmaktadır. Ancak savaşın yarattığı toplumsal çalkantılar ve ülkenin derinlere kök salmış sorunları, iki âşığın kavuşmasını zorlaştırır. Inman, sevdiği kadına ulaşabilmek için tehlikelerle dolu bir yolculuğa çıkarken aşkın, umudun ve bağlılığın gücüyle ayakta kalmaya çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/soguk-dag-2003-izle.webp", backdrop = "", year = "2003", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/soguk-dag-2003-izle/", category = "Film"),
    Movie(id = 1000132, title = "Masumiyetin İntiharı", overview = "Banliyöde yaşayan bir grup genç, çevrelerindeki en gizemli ailelerden biri olan Lisbon ailesinin beş kızına büyük bir merak duyar. Kız kardeşlere duydukları ilgi, zamanla gençlerin aşkı, cinselliği ve kadınların dünyasını keşfetme çabalarına dönüşür. Ancak kız kardeşlerden birinin intihar etmesi, ailenin kapalı kapılar ardında sakladığı sırları gündeme getirir. Katı Katolik değerlerle yetiştirilen Lisbon ailesi, yaşanan trajedi hakkında konuşmaktan kaçınırken çevredeki gençler olayın ardındaki gerçekleri öğrenmeye çalışır. Kız kardeşlerin gizemini çözmeye uğraşan bu gençler, zamanla aileyi çevreleyen sessizliğin ve baskının ardındaki karanlık dünyayla yüzleşir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-virgin-suicides-1999-izle.webp", backdrop = "", year = "1999", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/masumiyetin-intihari/", category = "Film"),
    Movie(id = 1000133, title = "Aklım Karıştı", overview = "Genç bir yazar adayı olan Susanna Kaysen, yaşadığı ruhsal sorunların ardından Claymoore adlı psikiyatri kliniğine yatırılır. Ailesinden ve alışık olduğu yaşamdan uzak kalan Susanna, burada hem hastalarla hem de klinik çalışanlarıyla kurduğu ilişkiler sayesinde kendisini ve dünyayı yeniden anlamlandırmaya başlar. Birbirinden farklı hayat hikâyelerine sahip kadınlarla tanışması, onun için zaman zaman sarsıcı, zaman zaman da umut verici bir deneyime dönüşür. James Mangold’un yönettiği film, Susanna Kaysen’in aynı adlı otobiyografik eserinden uyarlanıyor. Angelina Jolie’nin ödüllü performansıyla öne çıkan yapım, özgürlük, kimlik arayışı ve ruhsal mücadeleler üzerine dokunaklı bir hikâye sunuyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/aklim-karisti-1999-izle.webp", backdrop = "", year = "1999", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/aklim-karisti-1999-izle/", category = "Film"),
    Movie(id = 1000134, title = "Vampirle Görüşme", overview = "Vampirlerin dünyasına farklı bir pencereden bakan film, Anne Rice’ın romanından uyarlanarak izleyiciyi ölümsüzlüğün hem cazibesi hem de ağır bedeliyle yüzleştiriyor. Yüzyıllardır vampir olarak yaşayan Lestat, soylu Louis’i de kendi türüne dönüştürür. Ancak Louis, yeni yaşamının gerektirdiği vahşeti kabullenemez ve hayatta kalmak için insanları öldürmekten kaçınır. Onun bu çıkmazını çözmeye çalışan Lestat’ın küçük bir kızı vampirliğe dönüştürmesi ise aralarındaki bağları karmaşıklaştırır. Neil Jordan’ın yönettiği filmde Tom Cruise ve Brad Pitt başta olmak üzere Antonio Banderas, Christian Slater ve Kirsten Dunst etkileyici bir oyuncu kadrosuyla hikâyeye hayat veriyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/vampirle-gorusme-1994-izle.webp", backdrop = "", year = "1994", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/vampirle-gorusme-1994-izle/", category = "Film"),
    Movie(id = 1000135, title = "Maske", overview = "Stanley Ipkiss, sıradan bir hayat süren, iyi kalpli ve çekingen bir banka memurudur. Bir gün tesadüfen bulduğu gizemli bir maskeyi taktığında hayatı tamamen değişir. Maske sayesinde olağanüstü güçler kazanan Stanley, çılgın hareketleri ve sıra dışı yetenekleriyle kısa sürede dikkatleri üzerine çeker. Ancak bu yeni kimliği, onu tehlikeli bir dünyanın içine sürükler. Mafya lideri Dorian Tyrel ile karşı karşıya gelen Stanley, hem güçlerini kontrol etmeyi öğrenmek hem de peşine düşen düşmanlarından kurtulmak zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/maske-1994-izle.webp", backdrop = "", year = "1994", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/maske-1994-izle/", category = "Film"),
    Movie(id = 1000136, title = "Beterböcek", overview = "Barbara ve Adam, birbirlerine büyük bir aşkla bağlı genç bir çifttir. Ancak geçirdikleri talihsiz bir kaza, hayatlarını aniden sona erdirir. Kısa süre sonra kendilerini New England’daki evlerinde hayalet olarak bulan ikili, evlerinin başka bir aileye satılmasıyla huzurlarını kaybeder. Yeni ev sahiplerinin tuhaf davranışları ve özellikle içine kapanık kızları Lydia, ölü çiftin sabrını taşırır. İstenmeyen misafirleri evden uzaklaştırmak isteyen Barbara ve Adam, insanları korkutma konusunda pek başarılı olamayınca sıra dışı bir hayalet olan Beetlejuice’tan yardım ister. Ne var ki bu karar, beklediklerinden çok daha çılgın ve kontrol edilemez olayların başlamasına neden…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/beterbocek-1988-izle.webp", backdrop = "", year = "1988", score = 7.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/beterbocek-1988-izle/", category = "Film"),
    Movie(id = 1000137, title = "Matchbox the Movie", overview = "Çocukluk yıllarından beri birbirine sıkı sıkıya bağlı olan bir grup arkadaşın hayatı, uzun süredir kendisinden haber alınamayan eski liderleri Sean’ın aniden kasabaya dönmesiyle değişir. Sean’ın aslında gizli bir CIA ajanı olduğunun ortaya çıkması, arkadaşları tehlikeli bir maceranın içine sürükler. Kendilerini uluslararası bir kovalamacanın ortasında bulan ekip, geçmişin sırlarıyla yüzleşirken hem birbirlerine olan bağlılıklarını korumak hem de giderek büyüyen tehdidin önüne geçmek zorundadır. Matchbox The Movie, dostluğun ve sadakatin sınandığı, aksiyon ve heyecan dolu bir serüven sunuyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/matchbox-the-movie-2026-izle.webp", backdrop = "", year = "2026", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/matchbox-the-movie/", category = "Film"),
    Movie(id = 1000138, title = "Küçük Kadınlar", overview = "Amerikan İç Savaşı’nın gölgesinde büyüyen Meg, Jo, Beth ve Amy, birbirlerinden oldukça farklı karakterlere sahip dört kız kardeştir. Babalarının savaşa gitmesiyle anneleriyle birlikte hayatın zorluklarına karşı koymak zorunda kalan kardeşler, çocukluktan yetişkinliğe uzanan bu süreçte pek çok sınavdan geçer. Her biri kendi hayallerinin ve hayatının peşinden giderken aralarındaki güçlü bağ, karşılaştıkları sorunların üstesinden gelmelerine yardımcı olur. Zamanla hayatın sunduğu en değerli şeyin sahip oldukları sevgi ve aile bağları olduğunu keşfederler.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kucuk-kadinlar-2019-izle.webp", backdrop = "", year = "2019", score = 7.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kucuk-kadinlar-2019-izle/", category = "Film"),
    Movie(id = 1000139, title = "Ayin", overview = "Graham ailesinin yaşlı büyüğü Ellen’ın ölümü, geride yalnızca bir yas değil, aile geçmişine dair cevaplanmamış sorular da bırakır. Kızı Annie ve ailesi, zamanla geçmişte saklanan bazı sırların ortaya çıkmasıyla kendilerini açıklanması güç ve ürkütücü olayların içinde bulur. Ailenin geçmişini araştırdıkça karşılarına çıkan gerçekler, yaşanan trajedinin sıradan bir kayıp olmadığını düşündürmeye başlar. Annie ve ailesi, giderek üzerlerine çöken karanlığın kaynağını bulmaya ve kendilerini nesiller boyunca süren korkunç bir mirastan kurtarmaya çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/ayin-2018-izle.webp", backdrop = "", year = "2018", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ayin-2018-izle/", category = "Film"),
    Movie(id = 1000140, title = "Tam Gaz", overview = "Genç yaşına rağmen direksiyon başında büyük bir ustalığa sahip olan Baby, soyguncuların kaçışını sağlayan profesyonel bir sürücüdür. Yaşadığı bir olayın ardından kulaklarında sürekli müzik taşıyan Baby, sürüşlerini kendi seçtiği şarkıların ritmine göre gerçekleştirir. Ancak aşk hayatına giren Debora, ona suçtan uzak yepyeni bir yaşamın mümkün olduğunu gösterir. Bu hayatı elde etmek isteyen Baby, kendisini suç dünyasına bağlayan patronundan kurtulmaya çalışır. Fakat özgürlük yolunda attığı her adım, onu daha tehlikeli işlerin ve geri dönüşü olmayan kararların içine sürükler.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/tam-gaz-2017-izle.webp", backdrop = "", year = "2017", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/tam-gaz-2017-izle/", category = "Film"),
    Movie(id = 1000141, title = "Oyun", overview = "Jessie ve eşi Gerald, şehirden uzaklaşmak için ıssız bir göl evine gider. Gerald’ın başlattığı sıra dışı bir çift oyunuyla geceyi farklı bir şekilde geçirmek isterler. Ancak Gerald’ın aniden hayatını kaybetmesi, Jessie’yi korkunç bir durumun içinde bırakır. Yatağa kelepçelenmiş olan Jessie’nin anahtarlara ulaşması mümkün değildir ve çevresinde yardım isteyebileceği hiç kimse yoktur. Kurtulmanın yollarını ararken yalnızca fiziksel bir mücadeleyle değil, yıllardır zihninin derinliklerine gömdüğü acı dolu çocukluk anılarıyla da yüzleşmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/oyun-2017-izle.webp", backdrop = "", year = "2017", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/oyun-2017-izle/", category = "Film"),
    Movie(id = 1000142, title = "Scott Pilgrim Dünyaya Karşı", overview = "22 yaşına gelmesine rağmen aşk hayatında bir türlü aradığı mutluluğu bulamamıştır. Vaktinin büyük bölümünü bas gitar çalarak ve garaj grubu Sex Bob-omb ile müzik yaparak geçiren Scott’ın hayatı, Ramona V. Flowers ile tanışmasıyla tamamen değişir. Hayallerindeki kıza kavuşmaya kararlı olan Scott, kısa süre sonra Ramona’nın geçmişinden gelen yedi güçlü eski sevgilisi olduğunu öğrenir. Üstelik bu rakiplerin her biri, Scott’ı zorlu ve sıra dışı bir mücadeleye sürükleyecek özel yeteneklere sahiptir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/scott-pilgrim-dunyaya-karsi-2010-izle.webp", backdrop = "", year = "2010", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/scott-pilgrim-dunyaya-karsi/", category = "Film"),
    Movie(id = 1000143, title = "Bir Erkek 10 Günde Nasıl Kaybedilir", overview = "Benjamin, ilişkileri birkaç günden fazla sürmeyen, hayatını kadınlar ve kısa süreli aşk maceraları üzerine kurmuş tam bir çapkındır. Ancak patronuyla girdiği bir iddia, onun alıştığı hayatı tamamen değiştirecektir. Benjamin, yeni sevgilisiyle en az on gün birlikte kalabileceğini öne sürer ve bu süreyi tamamlamaya kararlıdır. Fakat bu kez karşısında sıradan bir ilişki değil, kendi kurallarını altüst edecek zorlu bir sınav vardır. Eğlenceli bir maceraya dönüşen bu iddia, Benjamin’in sandığından çok daha fazlasıyla yüzleşmesine neden olacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/bir-erkek-10-gunde-nasil-kaybedilir-2003-izle.webp", backdrop = "", year = "2003", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/bir-erkek-10-gunde-nasil-kaybedilir/", category = "Film"),
    Movie(id = 1000144, title = "Renfield", overview = "Yüzyıllardır Kont Dracula’nın sadık hizmetkârlığını yapan Renfield, efendisinin bitmek bilmeyen emirleri ve baskısı altında yaşamını sürdürür. Ancak yıllar geçtikçe bu karanlık ilişkinin içinde daha fazla kalmak istemediğini fark eder. Renfield artık kendi hayatını kurmanın ve Dracula’nın gölgesinden çıkmanın yollarını aramaya başlar. Özgürlüğüne kavuşabilmesi için öncelikle efendisiyle arasındaki hastalıklı bağı kırması gereken Renfield, hayatında yepyeni bir sayfa açmaya çalışır. Fakat yüzyıllardır süren bu esaretten kurtulmak, sandığı kadar kolay olmayacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/renfield-2023-izle.webp", backdrop = "", year = "2023", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/renfield-2023-izle/", category = "Film"),
    Movie(id = 1000145, title = "Vahşi Gece", overview = "Noel akşamında zengin bir aile, evlerinde huzurlu ve keyifli bir gece geçirmeyi planlar. Ancak bir grup silahlı paralı askerin eve baskın yaparak aileyi rehin almasıyla tüm planlar altüst olur. Kendilerini büyük bir soygunun içinde bulan saldırganlar, evde hiç beklemedikleri birinin bulunduğundan habersizdir. Noel Baba kılığıyla gelen gizemli yabancı, sıradan bir ihtiyar olmaktan çok uzaktır. Ailesini kurtarmak için harekete geçen Noel Baba, paralı askerlere karşı amansız bir mücadele başlatır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/vahsi-gece-2022-izle.webp", backdrop = "", year = "2022", score = 6.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/vahsi-gece-2022-izle/", category = "Film"),
    Movie(id = 1000146, title = "Vahşi Gece 2", overview = "Noel Baba, bu kez kendisini Kuzey Kutbu’nun sıcak ve güvenli ortamından çok uzakta, New Jersey’nin ıssız bir bölgesindeki terk edilmiş bir alışveriş merkezinde bulur. Üstelik Kuzey Kutbu’yla bağlantısı tamamen kesilmiştir ve bulunduğu bina acımasız bir çete lideri ile silahlı adamlarının kontrolündedir. Yardım bekleme şansı olmayan Noel Baba, hayatta kalmak ve binayı suçlulardan temizlemek için kendi yöntemlerine başvurur. Çok geçmeden terk edilmiş alışveriş merkezi, Noel Baba ile çete üyeleri arasında kanlı ve amansız bir hesaplaşmanın sahnesine dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/vahsi-gece-2-2026-izle.webp", backdrop = "", year = "2026", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/vahsi-gece-2-2026-izle/", category = "Film"),
    Movie(id = 1000147, title = "Uncharted", overview = "Genç hazine avcısı Nathan Drake, efsanevi El Dorado’nun izini sürerek hayatının en büyük macerasına atılır. Güney Amerika’da saklı olduğu söylenen altın şehri bulmak için deneyimli ortağı Victor Sullivan ile birlikte yola çıkan Nathan, kısa süre sonra yalnız olmadıklarını fark eder. Peşlerindeki hırslı rakip, El Dorado’nun sırrına ulaşmak için her şeyi göze alırken, hazine avı tehlikeli bir yarışa dönüşür. Nathan, hem rakiplerinin planlarını bozmak hem de efsanevi şehre herkesten önce ulaşmak için zekâsını, cesaretini ve becerilerini kullanmak zorunda kalacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/uncharted-2022-izle.webp", backdrop = "", year = "2022", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/uncharted-2022-izle-1/", category = "Film"),
    Movie(id = 1000148, title = "Pearl", overview = "1998 yılında yaşayan Pearl, sıradan bir hayat sürmek istemeyen ve şöhretin peşinden koşan genç bir kadındır. Göz kamaştırıcı bir yaşamın ve herkes tarafından tanınmanın hayalini kuran Pearl, istediği fırsatı elde edemeyince büyük bir hayal kırıklığı yaşar. Ancak bu hayal kırıklığı kısa sürede öfkeye dönüşür. Yaşadığı reddedilmenin ardından kontrolünü kaybeden Pearl, kendisini giderek daha karanlık bir yolun içinde bulur ve ardı ardına cinayetler işlemeye başlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/pearl-2022-izle.webp", backdrop = "", year = "2022", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/pearl-2022-izle/", category = "Film"),
    Movie(id = 1000149, title = "Aşk ve Canavarlar", overview = "Dünya, canavarların istilasından yedi yıl sonra artık insanların tanıdığı eski dünya olmaktan çok uzaktır. Hayatta kalan az sayıdaki insan yeraltındaki sığınaklarda yaşam mücadelesi verirken Joel Dawson da yıllardır bu tehlikeli ortamdan uzak durmaktadır. Ancak bir gün radyodan gelen bir ses, geçmişini yeniden karşısına çıkarır. Lise aşkı Aimee’nin hayatta olduğunu öğrenen Joel, onun 80 mil uzaklıktaki bir kolonide yaşadığını keşfeder. Aimee’ye duyduğu hislerin hâlâ devam ettiğini anlayan genç adam, tüm korkularını geride bırakıp canavarlarla dolu dünyada sevdiği kadına ulaşmak için yola çıkar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/love-and-monsters-2020-izle.webp", backdrop = "", year = "2020", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ask-ve-canavarlar/", category = "Film"),
    Movie(id = 1000150, title = "Ma", overview = "Maggie ve arkadaşları, gençliklerinin tadını çıkarmak isterken kendilerini beklenmedik bir arkadaşlığın içinde bulur. Kasabada yalnız başına yaşayan Sue Ann, gençlerle tanıştıktan sonra onları evinde düzenleyeceği partiye davet eder. Ailelerinden uzaklaşmak için iyi bir fırsat yakalayan gençler, bu daveti düşünmeden kabul eder ve Sue’nun evinde unutulmaz bir gece geçirir. Fakat başlangıçta oldukça eğlenceli görünen bu yakınlık, Sue’nun davranışlarının değişmesiyle bambaşka bir boyuta taşınır. Gençler, kendilerine gösterilen ilginin masum bir arkadaşlıktan çok daha fazlası olduğunu fark ettiklerinde artık iş işten geçmiştir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/ma-2019-izle.webp", backdrop = "", year = "2019", score = 5.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ma-2019-izle/", category = "Film"),
    Movie(id = 1000151, title = "Cloverfield Paradoksu", overview = "Uzayda görev yapan bir grup bilim insanı, insanlığın enerji sorununa çözüm olabilecek yeni bir kaynak keşfetmek için çalışmalarını sürdürür. Araştırmalarının merkezinde ise halk arasında “tanrı parçacığı” olarak bilinen Higgs bozonu vardır. Ancak deney sırasında işler beklenmedik bir şekilde ters gider ve bilim insanları, uzay istasyonunda kontrol edilemez bir tehdidin ortaya çıkmasına neden olur. Mürettebatın hayatı büyük bir tehlikeye girerken yaşanan olayların, çok daha büyük ve korkutucu bir felaketin başlangıcı olduğu anlaşılır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/the-cloverfield-paradox-2018-izle.webp", backdrop = "", year = "2018", score = 5.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cloverfield-paradoksu/", category = "Film"),
    Movie(id = 1000152, title = "Cloverfield", overview = "New York’ta sıradan bir gece, şehirde yankılanan korkunç bir gürültüyle bir anda kâbusa dönüşür. Bir barda bulunan insanlar ne olduğunu anlamaya çalışırken yaşanan panik kısa sürede tüm şehre yayılır. Manhattan’da meydana gelen büyük patlamanın ardından caddeler yıkıntılar ve alevlerle kaplanır. Olayların boyutu, Özgürlük Heykeli’nin kopan başının bir top mermisi gibi sokağa düşmesiyle daha da dehşet verici hale gelir. New York’u hedef alan gizemli ve devasa bir yaratığın saldırısına tanık olan bir grup insan, hayatta kalabilmek için yaşanan kaosun ortasında mücadele etmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/cloverfield-2008-izle.webp", backdrop = "", year = "2008", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cloverfield-2008-izle/", category = "Film"),
    Movie(id = 1000153, title = "Turbo", overview = "Hayallerinin peşinden gitmek isteyen küçük bir sümüklü böcek, türünün en hızlısı olmayı kafasına koyar. Ancak yavaşlığı nedeniyle çevresindekiler tarafından küçümsenen Turbo, beklenmedik bir kaza sonucu hayatını tamamen değiştirecek bir güç kazanır. Artık hız konusunda kendisine engel olan hiçbir şey yoktur. Büyük hayalinin peşinden gitmeye karar veren Turbo, arkadaşlarını da yanına alarak dünyanın en prestijli yarışlarından Indy 500’e katılmayı hedefler. Fakat bu yarışta başarılı olmak yalnızca hız değil, cesaret, azim ve kendine inanmayı da gerektirecektir. Ryan Reynolds, Paul Giamatti, Snoop Dogg ve Luis Guzmán’ın sesleriyle renk kattığı animasyonun yönetmen koltuğunda David…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/turbo-2013-izle.webp", backdrop = "", year = "2013", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/turbo-2013-izle/", category = "Film"),
    Movie(id = 1000154, title = "Çizmeli Kedi: Son Dilek", overview = "Çizmeli Kedi, yıllar boyunca atıldığı tehlikeli maceraların bedelini ağır bir şekilde ödemiştir. Dokuz canından sekizini kaybeden cesur kedi, artık yalnızca tek bir yaşam hakkına sahiptir. Bu durum onu ilk kez kendi ölümlülüğüyle yüzleşmeye zorlar. Kaybettiği canlarını geri kazanmanın tek yolunun efsanevi Son Dilek’i bulmak olduğunu öğrenen Çizmeli Kedi, son bir maceraya atılır. Kara Orman’a doğru başlayan bu zorlu yolculukta hem tehlikeli rakiplerle karşılaşacak hem de hayatının en önemli kararlarıyla yüzleşecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/cizmeli-kedi-son-dilek-2022-izle.webp", backdrop = "", year = "2022", score = 7.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cizmeli-kedi-son-dilek/", category = "Film"),
    Movie(id = 1000155, title = "Çizmeli Kedi", overview = "Sarı çizmeleriyle masallar dünyasının en tanınmış kedilerinden biri olan Çizmeli Kedi, şöhret ve zenginlik uğruna yeni bir maceraya atılır. Hedefinde ise herkesin efsane olarak bildiği Altın Yumurtlayan Kaz vardır. Bu büyük soygun için çocukluk arkadaşı Humpty Dumpty ve becerikli hırsız Kitty Softpaws ile güçlerini birleştirir. Birbirinden oldukça farklı üç karakter, kusursuz olduğunu düşündükleri planı uygulamaya koyar. Fakat tehlikeler, yanlış anlaşılmalar ve beklenmedik sürprizler peşlerini bırakmaz. Çizmeli Kedi ve arkadaşlarının bu macerası, masal dünyasını eğlenceli bir soygun hikâyesiyle buluşturuyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/cizmeli-kedi-2011-izle.webp", backdrop = "", year = "2011", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cizmeli-kedi-2011-izle/", category = "Film"),
    Movie(id = 1000156, title = "Kadın Aklı Erkek Aklı", overview = "Abby Richter, romantizme ve gerçek aşka inanan, sabah programının arkasındaki başarılı yapımcıdır. Ancak programa yeni katılan Mike Chadway, kadın-erkek ilişkileri konusunda Abby’nin düşüncelerinin tam tersini savunan, dobra ve kural tanımayan bir adamdır. İkilinin anlaşmazlıkları, Abby’nin yeni tanıştığı bir erkeği etkilemek için Mike’ın yardımını istemesiyle farklı bir boyuta taşınır. Mike, kendi yöntemleriyle Abby’ye ilişkilerin romantik hayallerden çok daha karmaşık olduğunu kanıtlamaya çalışır. Fakat bu oyun, ikisinin de hesaba katmadığı duyguların ortaya çıkmasına neden olur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kadin-akli-erkek-akli-2009-izle.webp", backdrop = "", year = "2009", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kadin-akli-erkek-akli/", category = "Film"),
    Movie(id = 1000157, title = "Kana Susadım", overview = "Jennifer, okulun gözde öğrencilerinden biri ve başarılı bir amigo takımının kaptanıdır. Ancak genç kızın hayatı, gizemli bir olayın ardından tamamen değişir. İçine musallat olan şeytani varlık, Jennifer’ı okulundaki erkek öğrencileri hedef alan tehlikeli birine dönüştürür. En yakın arkadaşı Needy, Jennifer’ın başına gelenlerin ardındaki gerçeği öğrendiğinde hem arkadaşını durdurmaya hem de çevresindeki insanları korumaya çalışır. Fakat olayları araştırdıkça Jennifer’ın kurbanlarının gerçekten yalnızca erkeklerden ibaret olup olmadığını sorgulamaya başlar. Gençlik filmi, korku ve kara mizahı bir araya getirerek alışılmış lise hikâyelerine sıra dışı bir yorum getiriyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kana-susadim-2009-izle.webp", backdrop = "", year = "2009", score = 5.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kana-susadim/", category = "Film"),
    Movie(id = 1000158, title = "Dünyalar Savaşı", overview = "Ray Ferrier, hayatının pek çok alanında sorun yaşayan ve ailesiyle arasındaki bağları yeniden kurmaya çalışan sıradan bir adamdır. New Jersey’de yaşayan Ray, maddi sıkıntılarına rağmen çocuklarının sorumluluğunu üstlenmeye çalışırken dünya beklenmedik bir tehditle karşı karşıya kalır. Gökyüzünden gelen devasa üç ayaklı savaş makineleri, insanlığın karşı koyamayacağı bir güçle dünyayı işgal etmeye başlar. Ray, kaosun ortasında çocuklarını, özellikle de kızını koruyarak güvenli bir yere ulaşmak için zorlu bir mücadeleye girişir. H.G. Wells’in klasik bilim kurgu romanından uyarlanan yapım, uzaylı istilasını bir babanın ailesini hayatta tutma mücadelesi üzerinden anlatıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/dunyalar-savasi-2005-izle.webp", backdrop = "", year = "2005", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/dunyalar-savasi/", category = "Film"),
    Movie(id = 1000159, title = "İhtiras Rüzgarları", overview = "19. yüzyılın sonlarında Montana’nın uçsuz bucaksız topraklarında yaşayan Albay William Ludlow, üç oğlunu kendi değerleri doğrultusunda büyütür. Savaşın izlerini taşımasına rağmen hayata karşı insancıl ve özgür ruhlu bir yaklaşımı olan Ludlow, çocuklarına doğayla iç içe, maceralarla dolu bir yaşam sunar. Ailenin sakin düzeni, oğullarından birinin nişanlısı Susannah’ın çiftliğe gelmesiyle değişmeye başlar. Genç kadının gelişi, üç kardeş arasındaki ilişkileri derinden etkilerken dünyanın farklı bir köşesinde yaklaşan Birinci Dünya Savaşı, onların hayatını da geri dönüşü zor bir şekilde değiştirecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/legends-of-the-fall-1994-izle.webp", backdrop = "", year = "1994", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ihtiras-ruzgarlari/", category = "Film"),
    Movie(id = 1000160, title = "Harakiri", overview = "17. yüzyıl Japonya’sında savaşların sona ermesi, samurayların hayatını da kökten değiştirir. Barış döneminde savaşçılarına ihtiyaç kalmayan derebeylik düzeni, özellikle efendisiz kalan Roninleri zor durumda bırakır. Geçim sıkıntısı ve toplumdaki itibarlarını kaybetmeleri nedeniyle birçok Ronin, çaresizlik içinde hayatlarına son vermeyi düşünmektedir. Bu dönemde eski bir samuray olan Hanshiro da yerel bir lordun kapısına gelir. Amacı, huzurunda seppuku yapabilmek için izin istemektir. Ancak Hanshiro’nun gelişi, geçmişte yaşanan acıların ve saklanan gerçeklerin ortaya çıkmasına neden olacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/harakiri-1962-izle.webp", backdrop = "", year = "1962", score = 8.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/harakiri-1962-izle/", category = "Film"),
    Movie(id = 1000161, title = "Soulm8te", overview = "Karısının ölümünün ardından büyük bir boşluğa düşen bir adam, yaşadığı acıyla başa çıkabilmek için yapay zekâ destekli bir android satın alır. Başlangıçta yalnızca hayatına eşlik etmesini istediği bu yapay varlıkla arasında özel bir bağ kurmaya çalışırken, işler beklenmedik bir şekilde değişir. Masum bir aşk robotu yaratma düşüncesi, kısa sürede tehlikeli ve ölümcül bir ilişkiye dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/soulm8te-2026-izle.webp", backdrop = "", year = "2026", score = 5.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/soulm8te-2026-izle/", category = "Film"),
    Movie(id = 1000162, title = "Kulübeye Tıklat", overview = "Eric ve Andrew, evlatlık kızları Wen ile birlikte sakin bir tatil geçirmek için New Hampshire kırsalındaki ıssız bir kulübeye gider. Aile, şehir hayatından uzak birkaç gün geçirmenin keyfini çıkarırken kapılarında dört yabancının belirmesiyle her şey bir anda değişir. Silahlı yabancılar tarafından rehin alınan aile, dış dünyayla bağlantısı olmayan bu yerde korkunç bir seçim yapmak zorunda bırakılır. Yabancılar, yaklaşan kıyameti engellemenin tek yolunun ailenin üyelerinden birinin büyük bir fedakârlık yapması olduğunu söyler. Eric ve Andrew, kızlarını korumakla insanlığın kaderi arasında imkânsız bir seçimle karşı karşıya kalırken, anlatılanların gerçek olup olmadığını da…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/kulubeye-tiklat-2023-izle.webp", backdrop = "", year = "2023", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kulubeye-tiklat/", category = "Film"),
    Movie(id = 1000163, title = "Çıldırmış Ayı", overview = "Georgia ormanlarında sıradan başlayan bir gün, kokain yüklü bir uçağın düşmesiyle tamamen değişir. Uçaktaki uyuşturucuların ortadan kaybolmasıyla birlikte bölgede tuhaf bir hareketlilik başlar. Ancak kimsenin hesaba katmadığı asıl tehlike, kayıp kokaini bulan 230 kiloluk devasa bir ayıdır. Uyuşturucunun etkisiyle saldırganlaşan ayı, ormanda karşısına çıkan herkese saldırmaya başlar. Bir polis, bir suçlu, bir turist ve genç bir adamdan oluşan birbirinden farklı dört kişi kendilerini aynı tehlikenin içinde bulur. Hayatta kalabilmek için bir araya gelmek zorunda kalan grup, öfkeli ve durdurulması neredeyse imkânsız ayının saldırılarından kaçmaya çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/cildirmis-ayi-2023-izle.webp", backdrop = "", year = "2023", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cildirmis-ayi/", category = "Film"),
    Movie(id = 1000164, title = "Asteroit Şehir", overview = "Genç bilim insanı adaylarını ve ailelerini çölün ortasındaki küçük bir kasabada buluşturan önemli bir akademik etkinliğe hazırlanmaktadır. Yıldız gözlemcileri ve askeri uzay öğrencilerinin katıldığı kongrede öğrenciler, bilimsel çalışmalarını paylaşmak ve birbirleriyle rekabet etmek için bir araya gelir. Fakat beklenmedik bir gelişme, programın tüm seyrini değiştirir. Gizemli bir uzaylının ortaya çıkmasıyla birlikte kasabada büyük bir şaşkınlık ve kaos yaşanır. Olayların kontrol altına alınması için ordu Asteroid City’yi yasak bölge ilan eder ve kimsenin kasabaya girip çıkmasına izin verilmez. Böylece bilimsel bir buluşma olarak başlayan etkinlik, katılımcıları hiç beklemedikleri bir maceranın içine…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/asteroit-sehir-2023-izle.webp", backdrop = "", year = "2023", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/asteroit-sehir/", category = "Film"),
    Movie(id = 1000165, title = "Suikast Treni", overview = "Uğur Böceği, her görevi mümkün olduğunca sakin ve sorunsuz şekilde tamamlamaya çalışan bir suikastçıdır. Ancak Tokyo’dan hareket eden hızlı trende üstlendiği son görev, hiç beklemediği bir kabusa dönüşür. Çünkü trende farklı amaçlarla birbirlerinin peşine düşen çok sayıda suikastçı bulunmaktadır. Kısa süre içinde herkesin birbirine bağlı sırları ve hesapları olduğunu fark eden Uğur Böceği, kendisini ölümcül bir çatışmanın ortasında bulur. Tren durmadan ilerlerken karşısındaki tehlikeli düşmanlarla mücadele etmek ve hayatta kalmak için bir çıkış yolu bulmak zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/suikast-treni-2022-izle.webp", backdrop = "", year = "2022", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/suikast-treni-izle/", category = "Film"),
    Movie(id = 1000166, title = "Emma.", overview = "Emma Woodhouse, güzelliği, zekâsı ve sahip olduğu servet sayesinde hayatını istediği gibi yaşayan genç bir kadındır. Evlilik düşüncesine sıcak bakmayan Emma’nın en büyük tutkusu ise çevresindeki insanların romantik ilişkilerini yönlendirmektir. Harriet Smith’in hayatına girmesiyle bu merakı daha da ileri bir noktaya taşınır. Harriet’e uygun bir eş bulmaya karar veren Emma, Bay Knightley’nin tüm itirazlarına rağmen kendi planını uygulamaya koyar. Ancak aşk söz konusu olduğunda yaptığı hesaplar hiç de beklediği gibi gitmeyecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/emma-2020-izle.webp", backdrop = "", year = "2020", score = 6.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/emma-2020-izle/", category = "Film"),
    Movie(id = 1000167, title = "Tomb Raider", overview = "Lara Croft, yedi yıl önce gizemli bir şekilde ortadan kaybolan ünlü arkeolog Lord Richard Croft’un kızıdır. Henüz 21 yaşına bile gelmemiş olan Lara, babasının mirasını devralmak yerine kendi hayatını kurmayı tercih eder. Doğu Londra’nın hareketli sokaklarında bisikletli kurye olarak çalışan genç kadın, bir yandan da üniversitedeki eğitimine devam etmeye çalışır. Ancak babasının ölümünü kabullenemeyen Lara, yıllardır çözülemeyen gizemin peşine düşmeye karar verir. Babasının ardında bıraktığı ipuçları onu dünyanın diğer ucuna kadar uzanabilecek tehlikeli bir maceraya sürükler. Lara, gerçeği ortaya çıkarmaya çalışırken hem babasının geçmişiyle hem de kendi kaderiyle yüzleşmek zorunda…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/tomb-raider-2018-izle.webp", backdrop = "", year = "2018", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/tomb-raider-2018-izle/", category = "Film"),
    Movie(id = 1000168, title = "Şipşak Aile", overview = "Pete ve Ellie, birbirlerini seven ve mutlu bir hayat süren bir çifttir. Hayatlarındaki en büyük eksikliğin bir çocuk olduğunu düşünen ikili, aile kurmaya karar verir ve evlat edinme sürecine girer. Başlangıçta tek bir çocuk sahiplenmeyi planlasalar da karşılarına üç kardeş çıkınca hepsine birden yuva olmaya karar verirler. Ailenin en büyük çocuğu olan 15 yaşındaki Lizzy, asi tavırlarıyla Pete ve Ellie için işleri hiç de kolaylaştırmaz. Bir anda üç çocuklu bir aileye dönüşen çift, ebeveynliğin hiç bilmedikleri yönleriyle karşılaşırken çocukların da yeni hayatlarına alışması gerekir. Evlat edinme sürecinin getirdiği zorluklar, aile…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/sipsak-aile-2018-izle.webp", backdrop = "", year = "2018", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sipsak-aile/", category = "Film"),
    Movie(id = 1000169, title = "Barry Seal: Kaçakçı", overview = "Barry Seal, pilotluk yapan ancak aynı zamanda yasa dışı işlere bulaşmış, hayatı boyunca risk almaktan çekinmeyen bir adamdır. Onun sıra dışı yetenekleri kısa süre sonra CIA’in dikkatini çeker ve Seal, Amerika’nın gerçekleştirdiği en kapsamlı gizli operasyonlardan birinde görev alması için teşkilata dahil edilir. Fakat aldığı bu görev, Barry’nin hayatını tamamen değiştirecek olayların başlangıcı olur. Tom Cruise’un Barry Seal’e hayat verdiği filmde yönetmen koltuğunda Doug Liman bulunuyor. Yarının Sınırında filminden sonra yeniden birlikte çalışan ikili, gerçek bir hikâyeden yola çıkan bu yapımda macera, suç ve aksiyonu bir araya getiriyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/barry-seal-kacakci-2017-izle.webp", backdrop = "", year = "2017", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/barry-seal-kacakci/", category = "Film"),
    Movie(id = 1000170, title = "Cloverfield Yolu No:10", overview = "Michelle, geçirdiği korkunç bir trafik kazasının ardından kendisini yerin altında bulunan gizemli bir sığınakta bulur. Ancak burada yalnız değildir. Howard ve Emmett adındaki iki adam, dışarıda kimyasal bir saldırı gerçekleştiğini ve hayatta kalabilmek için sığınaktan kesinlikle çıkmamaları gerektiğini söyler. Michelle kısa sürede anlatılanların ne kadarının gerçek olduğunu sorgulamaya başlar. Dan Trachtenberg’in yönettiği filmde Mary Elizabeth Winstead, John Goodman ve John Gallagher Jr. başrolleri paylaşıyor. Yapımcılığını J.J. Abrams’ın üstlendiği yapım, genç bir kadının kapalı bir ortamda hayatta kalmaya çalışırken karşılaştığı gizemleri ve giderek artan gerilimi konu alıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/cloverfield-yolu-no-10-2016-izle.webp", backdrop = "", year = "2016", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cloverfield-yolu-no-10/", category = "Film"),
    Movie(id = 1000171, title = "Assassin’s Creed", overview = "Ölüme mahkûm edilen Callum Lynch, hayatının sonuna geldiğini düşünürken Abstergo Industries tarafından gizli bir proje için seçilir. Şirketin geliştirdiği Animus teknolojisi sayesinde insanların atalarından miras kalan anılara ve yeteneklere ulaşılabilmektedir. Callum da bu deneyin bir parçası olarak geçmişine doğru sıra dışı bir yolculuğa çıkar. Lynch, 15. yüzyıl İspanya’sında yaşayan ve Suikastçiler olarak bilinen gizli örgütün önemli üyelerinden Aguilar de Nerha ile arasında bir bağ olduğunu öğrenir. Aguilar’ın anılarını deneyimledikçe hem kendi soyunun sırlarını keşfeder hem de geçmişten gelen yeteneklerini ortaya çıkarır. Çok geçmeden kendisini, yüzyıllardır Suikastçiler ile mücadele eden Tapınakçılar’ın…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/assassins-creed-2016-izle.webp", backdrop = "", year = "2016", score = 5.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/assassins-creed-2016-izle/", category = "Film"),
    Movie(id = 1000172, title = "Dünya Savaşı Z", overview = "Gerry Lane, eşi ve iki kızıyla birlikte sakin bir hayat süren eski Birleşmiş Milletler çalışanıdır. Ancak bir gün trafikte sıkışıp kaldıkları sırada çevrede yaşanan tuhaf olaylar, dünyanın büyük bir tehlikeyle karşı karşıya olduğunu gösterir. Çok geçmeden insanların kontrolünü kaybederek saldırgan yaratıklara dönüştüğü korkunç bir salgının hızla yayıldığı ortaya çıkar. Gerry, ailesini güvenli bir yere ulaştırmayı başardıktan sonra salgının kaynağını ve insanlığı kurtarmanın yolunu bulmak için yeniden göreve dönmek zorunda kalır. Dünyanın farklı bölgelerine uzanan tehlikeli yolculuğunda hem zamana hem de giderek büyüyen zombi tehdidine karşı mücadele eder. Brad Pitt’in başrolünü…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/dunya-savasi-z-2013-izle.webp", backdrop = "", year = "2013", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/dunya-savasi-z-2013-izle/", category = "Film"),
    Movie(id = 1000173, title = "Şansa Bak", overview = "Adam’ın hayatı, genç yaşta kansere yakalandığını öğrenmesiyle bir anda altüst olur. Henüz böyle bir ihtimali düşünmeye bile hazır değilken kendisini tedavi süreçleri, doktor kontrolleri ve belirsizliklerle dolu yeni bir hayatın içinde bulur. Üstelik doktorların iyileşme ihtimalini yüzde 50 olarak açıklaması, onun geleceğe dair tüm düşüncelerini yeniden değerlendirmesine yol açar. Adam önce yaşadığı gerçeği kabullenmekte zorlanır, ardından hastalığına karşı mücadele etmeye karar verir. Bu süreçte en yakın arkadaşı Kyle’ın desteği önemli bir yer tutar. İkili, hayatın en zor dönemlerinden birini zaman zaman hüzünlü, zaman zaman da oldukça komik anlarla atlatmaya çalışır.…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/sansa-bak-2011-izle.webp", backdrop = "", year = "2011", score = 7.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sansa-bak-2011-izle/", category = "Film"),
    Movie(id = 1000174, title = "Chicago", overview = "1920’lerin hareketli Chicago’sunda sahne dünyası, işlenen cinayetlerle birlikte büyük bir skandalın merkezine dönüşür. Kocasını ve kız kardeşini öldüren ünlü sanatçı Vilma’nın ardından, şöhret olma hayalleri kuran genç şarkıcı Roxie de sevgilisi Fred’i öldürerek aynı hapishaneye düşer. Roxie için bu durum aslında beklenmedik bir fırsattır; çünkü hayranlık duyduğu Vilma ile aynı hücreyi paylaşmaktadır. Hapishanenin müdürü, Roxie’nin davasını üstlenmesi için ünlü avukat Billy’yi görevlendirir. Billy, hukuki becerilerinden çok medyayı kullanma konusunda ustadır ve kısa sürede Roxie’yi gazetelerin manşetlerine taşıyarak onu bir anda şöhrete kavuşturur. Roxie gündemin merkezine yerleşirken Vilma’nın yıldızı sönmeye başlar.…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/10/chicago-2002-izle.webp", backdrop = "", year = "2002", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/chicago-2002-izle/", category = "Film"),
    Movie(id = 1000175, title = "Fırlama Kızlar", overview = "Beverly Hills’in göz alıcı dünyasında yaşayan Cher Horowitz, lisesinin en popüler öğrencilerinden biridir. Moda konusundaki özgüveni ve çevresindeki insanlar üzerindeki etkisiyle dikkat çeken Cher, boş zamanlarında içine kapanık ve sosyal çevresi olmayan öğrencileri adeta birer dönüşüm projesine çevirmeyi sever. Yeni hedefi ise okula kısa süre önce gelen, çekingen yapısıyla dikkat çeken Tai’dir. Cher, Tai’nin görünüşünü ve sosyal hayatını değiştirmeye çalışırken kendisini hiç beklemediği duygusal karmaşaların içinde bulur. Jane Austen’in Emma romanından esinlenen bu gençlik hikâyesi, lise hayatını dostluk, aşk ve bolca mizahla ele alıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/firlama-kizlar-1995-izle.webp", backdrop = "", year = "1995", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/firlama-kizlar/", category = "Film"),
    Movie(id = 1000176, title = "The Boogeyman", overview = "Annesinin trajik ölümünün ardından 16 yaşındaki Sadie ve küçük kız kardeşi Sawyer, yaşadıkları büyük kayıpla baş etmeye çalışır. Babaları Will, kızlarının yanında olmak istese de bir terapist olmasına rağmen onlarla sağlıklı bir iletişim kurmakta zorlanır. Ailenin yaşadığı sorunlar, Will’in gizemli hastası Lester’ın evlerine gelmesiyle daha da karmaşık bir hal alır. Çocuklarını kaybetmenin acısıyla mücadele eden bu adam, beraberinde karanlık ve doğaüstü bir varlık getirir. Sadie ve Sawyer korkunç olaylarla karşı karşıya kalırken, babalarının anlattıklarına inanmaması onları giderek daha büyük bir tehlikenin içine sürükler.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-boogeyman-2023-izle.webp", backdrop = "", year = "2023", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/the-boogeyman/", category = "Film"),
    Movie(id = 1000177, title = "The Banshees of Inisherin", overview = "1920’li yılların İrlanda’sında, sakin ve herkesten uzak bir adada yaşayan Padraic ile Colm, uzun yıllardır birbirlerinin en yakın dostudur. Ancak Colm’un bir gün hiçbir açıklama yapmadan bu arkadaşlığı sona erdirmeye karar vermesi, Padraic’in hayatını altüst eder. Padraic, eski dostunun kararının nedenini anlamaya ve ilişkilerini yeniden düzeltmeye çalışırken, yaşananlar küçük ada topluluğunda da giderek büyüyen bir huzursuzluğa yol açar. İki arkadaş arasındaki beklenmedik kopuş, yalnızlık, dostluk ve insan ilişkileri üzerine sıra dışı bir hikâyeye dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-banshees-of-inisherin-2022-izle.webp", backdrop = "", year = "2022", score = 7.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/the-banshees-of-inisherin/", category = "Film"),
    Movie(id = 1000178, title = "See How They Run", overview = "1953 Londra’sında sahnelerin en popüler yapımlarından biri olan The Mousetrap, kısa sürede büyük bir başarıya ulaşır. Ancak oyunun sinema uyarlaması üzerinde çalışan Hollywood yönetmeni Leo Köpernick’in gizemli ve vahşi bir şekilde öldürülmesiyle işler tamamen değişir. Davayı, yılların yorgunluğunu taşıyan Komiser Stoppard ile heyecanını gizleyemeyen genç Memur Stalker üstlenir. İkili, tiyatro dünyasının perde arkasındaki sırları araştırırken oyunculardan senaristlere, yapım ekibinden tiyatro çalışanlarına kadar herkes şüpheli konumuna gelir. Katilin kim olduğunu bulmaya çalışırken karşılarına çıkan ipuçları, soruşturmayı giderek daha karmaşık ve eğlenceli bir hale getirir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/see-how-they-run-2022-izle.webp", backdrop = "", year = "2022", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/see-how-they-run/", category = "Film"),
    Movie(id = 1000179, title = "Kabus Sokağı", overview = "Stanton Carlisle, hayatında istediği noktaya bir türlü ulaşamamış, ancak insanları etkileme konusunda doğal bir yeteneğe sahip genç bir adamdır. Bir karnavalda tanıştığı Zeena ve Pete sayesinde zihinsel gösteriler ve falcılık konusunda kendisini geliştirir. Öğrendiklerini kullanarak New York’un zengin çevrelerine giren Stanton, kısa sürede insanları kandırarak büyük paralar kazanmaya başlar. Molly’nin yanında olmasıyla daha da cesaretlenen Stanton, sonunda tehlikeli bir iş adamını dolandırmak için gizemli bir psikiyatristle iş birliği yapar. Ancak bu kez kurduğu oyunun bedeli çok ağır olabilir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/kabus-sokagi-2021-izle.webp", backdrop = "", year = "2021", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kabus-sokagi/", category = "Film"),
    Movie(id = 1000180, title = "Fransız Postası", overview = "Fransa’nın kurgusal bir şehrinde faaliyet gösteren Amerikalı gazetecilerin dünyasına konuk olan The French Dispatch, yıllar boyunca dergide yayımlanan birbirinden farklı hikâyeleri beyazperdeye taşıyor. 20. yüzyılın farklı dönemlerine uzanan yapımın anlatısı, derginin başındaki editörün ölümüyle şekilleniyor. Gazete ekibi, onun ardından çıkarılacak son sayıyı hazırlarken üç önemli yazıyı ön plana çıkarıyor. Bu yazılar; sıra dışı bir sanatçının işlediği çifte cinayetin ardından yaşadıkları, 1968’de Fransa’yı etkisi altına alan öğrenci protestoları ve bir şefin dahil olduğu gizemli kayıp olayının izini sürüyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/fransiz-postasi-2021-izle.webp", backdrop = "", year = "2021", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/fransiz-postasi/", category = "Film"),
    Movie(id = 1000181, title = "Yeni Mutantlar", overview = "Rahne Sinclair, Illyana Rasputin, Sam Guthrie ve Roberto da Costa, güçlerini kontrol etmeyi öğrenmeleri için izole bir hastanede gözetim altında tutulan dört genç mutanttır. Onları hem kendileri hem de çevreleri açısından tehlikeli gören Dr. Cecilia Reyes, gençleri yakından takip ederek yeteneklerini anlamalarına ve kontrol etmelerine yardımcı olmaya çalışır. Ancak Danielle Moonstar’ın tesise getirilmesiyle birlikte hastanede açıklanamayan ve giderek daha ürkütücü hale gelen olaylar yaşanmaya başlar. Başlangıçta burada yalnızca tedavi ve rehabilitasyon amacıyla tutulduklarını düşünen gençler, kısa süre içinde bulundukları yerin gerçek amacının çok daha karanlık olduğunu fark eder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/yeni-mutantlar-2020-izle.webp", backdrop = "", year = "2020", score = 5.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yeni-mutantlar/", category = "Film"),
    Movie(id = 1000182, title = "Derin Sular", overview = "Okyanusun binlerce metre derinliğinde faaliyet gösteren bir araştırma ekibi, deniz tabanındaki laboratuvarlarında çalışmalarını sürdürmektedir. Ancak güçlü bir deprem meydana geldiğinde her şey bir anda değişir. Laboratuvar ağır hasar alırken ekip, yüzlerce metre suyun altında mahsur kalır ve hayatta kalabilmek için zamana karşı yarışmaya başlar. İletişim ve kaçış yollarının büyük ölçüde zarar görmesi, araştırmacıları son derece tehlikeli bir durumla karşı karşıya bırakır. Ekip üyeleri hem fiziksel engelleri aşmak hem de derin denizin bilinmezlikleriyle mücadele etmek zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/derin-sular-2020-izle.webp", backdrop = "", year = "2020", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/derin-sular-2020-izle/", category = "Film"),
    Movie(id = 1000183, title = "Boş Adam", overview = "Eşini ve oğlunu kaybettikten sonra hayattan uzaklaşan eski polis James Lasombra, sakin bir kasabada yaşanan gizemli kaybolma vakaları nedeniyle yeniden harekete geçmek zorunda kalır. Özellikle gençlerin birbiri ardına ortadan kaybolması, kasaba halkını yıllardır anlatılan ürkütücü bir efsaneye yönlendirir. James araştırmasını derinleştirdikçe olayların sıradan kayıplardan çok daha fazlası olduğunu fark eder. Karanlık bir tarikatın korkunç bir varlığı dünyaya çağırmaya çalıştığını keşfeden eski polis, gerçeği ortaya çıkarmaya çalışırken kendisini giderek büyüyen doğaüstü bir tehdidin ortasında bulur. Ancak öğrendiği her yeni bilgi, onu kurtuluştan çok daha büyük bir kabusun içine sürüklemektedir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/bos-adam-2020-izle.webp", backdrop = "", year = "2020", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/bos-adam-2020-izle/", category = "Film"),
    Movie(id = 1000184, title = "Nomadland", overview = "Nevada’nın kırsalında yaşayan Fern, ekonomik kriz nedeniyle hayatının büyük bölümünü kaybeder. Alıştığı düzenin tamamen değişmesiyle birlikte kendisine yeni bir yaşam kurmaya karar veren Fern, sahip olduğu minibüsü küçük bir karavana dönüştürür. Bundan sonra belirli bir eve bağlı kalmadan yollara düşen kadın, farklı şehirleri ve insanları tanıyarak modern göçebe hayatını benimser. Yol boyunca karşılaştığı zorluklar ve yeni dostluklar, Fern’in geçmişini geride bırakıp hayatına farklı bir yön vermesine yardımcı olur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/nomadland-2020-izle.webp", backdrop = "", year = "2020", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/nomadland/", category = "Film"),
    Movie(id = 1000185, title = "Yıldızlara Doğru", overview = "Astronot Roy McBride, yıllar önce uzayda kaybolan babasının izini sürmek için tehlikeli bir göreve çıkar. Roy’un babası, Dünya dışında yaşam ihtimalini araştırmak amacıyla çıktığı görev sırasında ortadan kaybolmuş ve kendisinden bir daha haber alınamamıştır. Aradan geçen yirmi yılın ardından Güneş Sistemi’ni tehdit eden gizemli olayların ortaya çıkması, Roy’u babasının görevine yeniden yönlendirir. İnsanlığın geleceğini etkileyebilecek sırların peşine düşen Roy, uzayın derinliklerine doğru ilerledikçe yalnızca kayıp babasına dair gerçeklerle değil, kendi geçmişi ve insanlığın evrendeki yeriyle ilgili sorularla da yüzleşmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/yildizlara-dogru-2019-izle.webp", backdrop = "", year = "2019", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yildizlara-dogru/", category = "Film"),
    Movie(id = 1000186, title = "Sarayın Gözdesi", overview = "18. yüzyıl İngiltere’sinde savaşın gölgesinde saray hayatı tüm entrikalarıyla devam etmektedir. Sağlığı giderek bozulan Kraliçe Anne, ülkenin başında görünse de devlet işlerinin büyük bölümünü sırdaşı ve danışmanı Marlborough Düşesi Sarah Churchill yürütmektedir. Saraya hizmetçi olarak gelen Abigail ise kısa sürede Sarah’ın dikkatini çekmeyi başarır. Sarah’ın himayesine giren genç kadın, aristokrat ailesinden gelen geçmişine yeniden kavuşma fırsatı yakalar. Ancak sarayda güç dengeleri değiştikçe Abigail’in kraliçeyle kurduğu yakınlık, iki kadın arasında sessiz bir rekabetin başlamasına neden olur. Abigail, hedeflerine ulaşmak için önüne çıkan hiçbir engelin kendisini durdurmasına izin vermemeye kararlıdır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/sarayin-gozdesi-2018-izle.webp", backdrop = "", year = "2018", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sarayin-gozdesi/", category = "Film"),
    Movie(id = 1000187, title = "Kurtuluş Günü 2: Yeni Tehdit", overview = "Dünya, ilk büyük uzaylı saldırısından sonra geçen 20 yıl boyunca kendisini yeni bir istilaya hazırlamıştır. İnsanlık, geçmişte yaşanan savaşın ardından uzaylı teknolojilerinden yararlanarak güçlü bir savunma sistemi oluşturur. Fakat beklenen tehdit tahmin edilenden çok daha büyük bir güçle geri döner. Gökyüzünü kaplayan devasa uzay gemileri, dünyanın önemli noktalarını hedef almaya başladığında insanlığın tüm hazırlıkları sınanır. Bu kez geçmişten gelen kahramanlar, yeni neslin cesur isimleriyle birlikte hareket ederek gezegeni kurtarmanın bir yolunu bulmak zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/independence-day-resurgence-2016-izle.webp", backdrop = "", year = "2016", score = 5.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kurtulus-gunu-2-yeni-tehdit/", category = "Film"),
    Movie(id = 1000188, title = "Kurtuluş Günü", overview = "Dünya, 2 Temmuz günü beklenmedik bir olayla sarsılır. Küresel iletişim sistemleri gizemli bir atmosferik olay nedeniyle devre dışı kalırken, kısa süre sonra gökyüzünde devasa cisimlerin belirdiği fark edilir. Başlangıçta meteor sanılan bu cisimlerin, dünyayı istila etmek üzere gelen uzaylılara ait devasa gemiler olduğu anlaşılır. Onlarla iletişim kurma çabaları sonuçsuz kalınca eski bilim insanı David Levinson, istilanın asıl amacını çözmeye çalışır ve insanlığın çok az zamanı kaldığını fark eder. Ertesi gün başlayan saldırılar New York, Los Angeles ve Washington’ı hedef alırken milyonlarca insan hayatta kalmak için kaçmaya başlar. Kurtulanlar, ordunun ele…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/independence-day-1996-izle.webp", backdrop = "", year = "1996", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kurtulus-gunu-1996-izle/", category = "Film"),
    Movie(id = 1000189, title = "Kağıttan Kentler", overview = "Quentin, çocukluğundan beri karşı komşusu Margo’ya karşı özel bir ilgi beslemektedir. Ancak yıllar geçtikçe ikilinin hayatları birbirinden uzaklaşır. Margo macerayı, gizemi ve özgürlüğü seven, çevresindeki herkesin dikkatini çeken sıra dışı bir genç kadına dönüşürken Quentin daha sakin ve planlı bir yaşam sürmektedir. Aradan dokuz yıl geçtikten sonra Margo bir gece ansızın Quentin’in kapısını çalar ve ondan beklenmedik bir konuda yardım ister. Bu buluşma, Quentin’in alıştığı düzeni tamamen değiştirecek ve onu Margo’nun peşinden sürükleyecek unutulmaz bir maceranın başlangıcı olacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/kagittan-kentler-2015-izle.webp", backdrop = "", year = "2015", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kagittan-kentler/", category = "Film"),
    Movie(id = 1000190, title = "Joy", overview = "Joy, çocukluğundan beri güçlü hayal gücü ve bitmek bilmeyen üretme isteğiyle dikkat çeken genç bir kadındır. Yeni fikirler geliştirmeyi ve günlük hayattaki sorunlara pratik çözümler bulmayı seven Joy, hayatındaki tüm zorluklara rağmen yaratıcılığından vazgeçmez. Ancak ailesi ve özel hayatı işleri hiç de kolaylaştırmaz. Boşandığı eşi, sürekli ilgi bekleyen iki çocuğu, sorunları bitmeyen annesi ve başına türlü dertler açan babası arasında kendi hayatına zaman ayırmak neredeyse imkânsızdır. Yıllar boyunca kendi hayallerini ikinci plana atan Joy, bir noktadan sonra artık bu şekilde devam edemeyeceğini fark eder. Geçmişte yarım bıraktığı fikirlerinden birine yeniden…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/joy-2015-izle.webp", backdrop = "", year = "2015", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/joy-2015-izle/", category = "Film"),
    Movie(id = 1000191, title = "Doğu Ekspresinde Cinayet", overview = "1930’lu yıllarda İstanbul ile Paris arasında yolculuk yapan Şark Ekspresi, gizemli bir cinayete sahne olur. Trenin yolcularından Amerikalı milyonerin kompartımanında ölü bulunması, yolculuğu bir anda soruşturmanın merkezine çevirir. Neyse ki trende bulunan ünlü Belçikalı dedektif Hercule Poirot, olayın peşine düşmek için gereken deneyime sahiptir. Ancak trenin kara saplanarak ilerleyememesi, Poirot’nun işini hem kolaylaştıracak hem de zorlaştıracaktır. Çünkü katil hâlâ trenin içindedir ve dedektifin yerel yetkililer olay yerine ulaşmadan önce gerçeği ortaya çıkarması gerekir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/dogu-ekspresinde-cinayet-2017-izle.webp", backdrop = "", year = "2017", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/dogu-ekspresinde-cinayet/", category = "Film"),
    Movie(id = 1000192, title = "Ajan", overview = "Susan Cooper, CIA’de masa başında çalışan, kurumun en önemli operasyonlarına uzaktan destek veren başarılı bir analisttir. Her ne kadar adı gizli kalsa da kritik görevlerin başarıyla tamamlanmasında büyük pay sahibidir. Özellikle saha ajanı Bradley Fine ile kurduğu uyumlu ekip sayesinde birçok operasyon sorunsuz şekilde sonuçlanmıştır. Ancak son görevde Fine ve CIA’in diğer önemli ajanlarından Rick Ford’un kimlikleri açığa çıkınca dengeler değişir. Tehlikeli bir silah kaçakçılığı şebekesinin planlarını durdurmak için bu kez Susan’ın sahaya çıkması gerekir. Daha önce hiç üstlenmediği bu görev, onu alışık olduğu güvenli ofis ortamından çıkarıp uluslararası bir…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/ajan-2015-izle.webp", backdrop = "", year = "2015", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ajan-2015-izle/", category = "Film"),
    Movie(id = 1000193, title = "Kirli Para", overview = "Bob Saginowski, geçmişinde suç bulunan ancak artık sakin bir hayat sürmeye çalışan bir barmendir. Kuzeni Marv ile birlikte işlettiği bar, Brooklyn’in yeraltı dünyasının önemli buluşma noktalarından biridir. Mekân, gangsterlerin kara para trafiğinde kullanılsa da Bob ve Marv olup bitenlere fazla karışmamayı tercih eder. Ancak Bob’un komşusu Nadia ile birlikte yaralı bir pitbull yavrusunu bulup sahiplenmesi, onu yeniden tehlikeli insanların arasına sürükler. Çünkü köpek, acımasız suçlu Eric Deeds’e aittir ve Deeds hem hayvanını hem de Nadia’yı geri almak için her yolu denemeye hazırdır. Üstelik barın soyulmasıyla birlikte işler daha da karmaşık…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/kirli-para-2014-izle.webp", backdrop = "", year = "2014", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kirli-para-2014-izle/", category = "Film"),
    Movie(id = 1000194, title = "Lanetli Kan", overview = "India Stoker, babasının ani ölümünün ardından annesiyle birlikte sessiz ve kapalı bir hayat sürmeye başlar. Ancak babasının cenazesinden sonra yıllardır hiç görmediği gizemli amcası Charlie’nin ortaya çıkması, evdeki tüm dengeleri değiştirir. Başlangıçta amcasına karşı mesafeli ve kuşkucu davranan India, zaman geçtikçe Charlie’nin karanlık tarafını fark etmeye başlar. Korku, merak ve öfkenin iç içe geçtiği bu tuhaf ilişki, genç kızın ailesi hakkında bildiği her şeyi sorgulamasına neden olur. Charlie’nin gelişiyle birlikte Stoker ailesinin saklı sırları yavaş yavaş ortaya çıkacaktır. Park Chan-wook’un Amerika’da çektiği ilk film olan yapımın başrollerinde Mia Wasikowska, Nicole…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/lanetli-kan-2013-izle.webp", backdrop = "", year = "2013", score = 6.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/lanetli-kan/", category = "Film"),
    Movie(id = 1000195, title = "Gizli Oyun", overview = "Eski FBI ajanı Sarah Moss, ajanlığı bıraktıktan sonra özel güvenlik şirketi Hiller Brood’da çalışmaya başlar. Şirketin yöneticisi Sharon, Sarah’ın yeteneklerini fark edince ona çok daha tehlikeli bir görev verir. Sarah’ın amacı, büyük şirketlerin karıştığı yolsuzlukları ve suçları ortaya çıkarmayı hedefleyen radikal bir grup olan The East’e sızarak örgüt hakkında bilgi toplamaktır. Ancak grubun içine girdikçe, özellikle lider Benji ile kurduğu yakın ilişki Sarah’ın düşüncelerini değiştirmeye başlar. Görevi ile giderek benimsediği idealler arasında kalan Sarah, kime ve neye sadık olduğunu sorgulamak zorunda kalır. Başrolünde Brit Marling’in yer aldığı filmin oyuncu kadrosunda…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/gizli-oyun-2013-izle.webp", backdrop = "", year = "2013", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/gizli-oyun-2013-izle/", category = "Film"),
    Movie(id = 1000196, title = "Walter Mitty’nin Gizli Yaşamı", overview = "Walter Mitty, hayatını popüler Life! dergisinin fotoğraf arşivinde çalışarak sürdüren, sakin ve sıradan bir adamdır. Gerçek dünyada oldukça içine kapanık olan Walter, hayal dünyasında kendisini bambaşka maceraların içinde bulmaktadır. Yeni iş arkadaşı Cheryl’a karşı hisler beslemeye başlamasıyla birlikte gerçek hayatı da değişmeye başlar. Tam bu sırada derginin basılı yayına son vererek dijital dünyaya geçeceğini öğrenir ve işini kaybetme tehlikesiyle karşı karşıya kalır. Üstelik son basılı sayı için hazırlanacak kapakta kullanılması gereken önemli bir fotoğraf kaybolmuştur. Fotoğrafın peşine düşen Walter, kendisini hayallerinde bile düşünemeyeceği bir maceranın içinde bulur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/walter-mittynin-gizli-yasami-2013-izle.webp", backdrop = "", year = "2013", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/walter-mittynin-gizli-yasami/", category = "Film"),
    Movie(id = 1000197, title = "Ateşli Aynasızlar", overview = "FBI ajanı Katerina James, kariyerindeki diğer görevlerden oldukça farklı bir operasyona atanır. Bu kez yanında FBI’dan bir ajan değil, Boston Polis Departmanı’ndan sıra dışı bir kadın polis olan Shannon Mullins vardır. Bir Rus gangsteri ve çetesini yakalamak için birlikte çalışmak zorunda kalan ikili, birbirinden tamamen farklı karakterleri ve yöntemleri nedeniyle başlangıçta hiç de kolay anlaşamaz. Ancak suçluların peşine düştükçe aralarındaki uyumsuzluk yerini güçlü ve eğlenceli bir ortaklığa bırakır. Görev boyunca kendilerini birbirinden komik ve tehlikeli olayların içinde bulan ikili, çeteyi yakalamak için her yolu deneyecektir. Yönetmenliğini Nedimeler ile tanınan Paul…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/atesli-aynasizlar-2013-izle.webp", backdrop = "", year = "2013", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/atesli-aynasizlar/", category = "Film"),
    Movie(id = 1000198, title = "Düşler Bahçesi", overview = "Eşini kaybettikten sonra iki çocuğuyla birlikte yeni bir hayat kurmaya çalışan Benjamin, geçmişten uzaklaşmak için ailesini şehirden uzakta, doğayla iç içe bir eve taşımaya karar verir. Ancak seçtikleri ev, sıradan bir ev değildir; içinde onlarca hayvanın bulunduğu terk edilmiş bir hayvanat bahçesidir. İlk başta büyük bir şaşkınlık yaşayan aile, kısa süre sonra bu sıra dışı yeri yeniden ayağa kaldırmaya karar verir. Fakat hayvanat bahçesini eski günlerine döndürmek, tahmin ettiklerinden çok daha büyük maddi ve manevi fedakârlık gerektirecektir. Benjamin ve çocuklarını zorlu olduğu kadar umut dolu bir macera beklemektedir. Matt Damon…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/dusler-bahcesi-2011-izle.webp", backdrop = "", year = "2011", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/dusler-bahcesi/", category = "Film"),
    Movie(id = 1000199, title = "Teklif", overview = "Margaret Tate, New York’ta başarılı bir kitap editörü olarak kariyerine odaklanmış, sert ve otoriter tavırlarıyla çevresindekileri bezdirmiş bir kadındır. Ancak Kanada vatandaşı olması nedeniyle sınır dışı edilme tehlikesiyle karşı karşıya kaldığında, hayatını kurtarmak için beklenmedik bir plan yapar. Yıllardır baskı altında tuttuğu asistanı Andrew’la nişanlandığını söyleyen Margaret, bu evliliğin gerçek olduğuna yetkilileri inandırmaya çalışır. Andrew ise bu sahte ilişkiye razı olmak için bazı şartlar öne sürer. Çift, evlilik planını inandırıcı göstermek amacıyla Andrew’ın Alaska’daki ailesini ziyaret etmek zorunda kalınca Margaret kendisini hiç alışık olmadığı bir hayatın içinde bulur. Başlangıçta yalnızca…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/teklif-2009-izle.webp", backdrop = "", year = "2009", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/teklif-2009-izle/", category = "Film"),
    Movie(id = 1000200, title = "Köy", overview = "19. yüzyılın sonlarında, dış dünyadan büyük ölçüde izole edilmiş küçük bir kasabada yaşayan insanlar, çevredeki ormanda bulunan gizemli yaratıkların korkusuyla hayatlarını sürdürmektedir. Kasaba halkı ile ormanda yaşayan varlıklar arasında yıllardır devam eden sessiz bir anlaşma vardır: İnsanlar ormana girmeyecek, yaratıklar da kasabaya yaklaşmayacaktır. Ancak genç Lucius Hunt, ormanın ardındaki sırrı merak etmeye başlayınca bu düzen tehlikeye girer. Lucius’un sınırları aşmasıyla birlikte kasabanın yıllardır koruduğu denge bozulur ve korkulan yaratıklar yeniden ortaya çıkar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/koy-2004-izle.webp", backdrop = "", year = "2004", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/koy-2004-izle/", category = "Film"),
    Movie(id = 1000201, title = "Ateşli Piliç", overview = "Jessica Spencer, lisenin en popüler ve güzel kızlarından biridir. Ancak bir gün başına gelen gizemli bir olay, hayatını tamamen altüst eder. Eski bir büyünün etkisiyle kendisini 30’lu yaşlarında bir yankesici olan Clive’ın bedeninde bulan Jessica, ne olduğunu anlamaya çalışırken Clive da onun bedenine geçmiştir. Eski haline dönebilmek için bir çözüm arayan Jessica, aynı zamanda alışık olmadığı bir hayatın içine girerek erkek gibi davranmayı ve düşünmeyi öğrenmek zorunda kalır. Clive ise bu sıra dışı durumu kendi çıkarı için kullanmaya karar verir ve işleyeceği suçların sorumluluğunu Jessica’nın üzerine bırakmayı planlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/atesli-pilic-2002-izle.webp", backdrop = "", year = "2002", score = 5.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/atesli-pilic/", category = "Film"),
    Movie(id = 1000202, title = "Ah Mary Vah Mary", overview = "Ted, lise yıllarında âşık olduğu Mary’yi aradan geçen on üç yılın ardından hâlâ unutamamıştır. Çekingen yapısına rağmen eski aşkını bulmaya karar veren Ted, bu iş için becerileri pek de parlak olmayan özel dedektif Healy’den yardım ister. Ancak Healy, Mary’yi bulduğunda ona kendisi de âşık olur. Üstelik Mary’nin etrafındaki neredeyse herkesin genç kadından hoşlandığını fark eden Ted, aşkını kazanmak için hiç beklemediği bir rekabetin içine girer. Healy ise Ted’i Mary’den uzak tutmak için türlü oyunlara başvururken, Ted eski aşkına yeniden kavuşabilmek için mücadele etmeye devam eder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/ah-mary-vah-mary-1998-izle.webp", backdrop = "", year = "1998", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ah-mary-vah-mary/", category = "Film"),
    Movie(id = 1000203, title = "İnce Kırmızı Hat", overview = "Guadalcanal’da Japon kuvvetlerine karşı savaşan Amerikalı askerler, Pasifik cephesinin en kanlı ve zorlu mücadelelerinden birinin ortasında kalır. Sürekli ölüm tehdidi altında geçen günler, askerlerin fiziksel olduğu kadar psikolojik olarak da sınırlarını zorlar. Savaş ilerledikçe korku, yalnızlık ve acı onları birbirlerine daha fazla yaklaştırır. Hayatta kalabilmek için aynı kaderi paylaşan bu insanlar, yaşadıkları olayların etkisiyle savaşın gerçek yüzünü görmeye ve kendi iç dünyalarıyla ilgili önemli gerçekleri keşfetmeye başlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-thin-red-line-1998-izle.webp", backdrop = "", year = "1998", score = 7.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ince-kirmizi-hat/", category = "Film"),
    Movie(id = 1000204, title = "Babamın Penguenleri", overview = "Tom Popper, New York’ta yaşayan başarılı ve yoğun tempolu bir iş adamıdır. Hayatı, bir anda kendisine bırakılan altı penguenle birlikte tamamen değişir. Apartman dairesini adeta buzlarla kaplı bir yaşam alanına dönüştüren Tom, bir yandan yeni misafirlerinin ihtiyaçlarıyla ilgilenirken diğer yandan kariyerini ayakta tutmaya çalışır. Penguenlerin getirdiği birbirinden komik olaylar, düzenli hayatını altüst ederken Tom için aile, sorumluluk ve mutluluk hakkında hiç beklemediği bir macera başlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/babamin-penguenleri-2011-izle.webp", backdrop = "", year = "2011", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/babamin-penguenleri/", category = "Film"),
    Movie(id = 1000205, title = "Percy Jackson 2: Canavarlar Denizi", overview = "Poseidon’un oğlu Percy Jackson, yarı tanrı olduğunu öğrendiği ilk macerasının ardından yeni ve çok daha tehlikeli bir göreve atılır. Yarı tanrıların yaşadığı kamp büyük bir tehditle karşı karşıyadır ve onu kurtarabilecek tek şey efsanevi Altın Post’tur. Percy, arkadaşlarıyla birlikte bu güçlü nesneyi bulmak için Canavarlar Denizi’ne doğru yola çıkar. Ancak yolculukları Titan saldırıları, mitolojik yaratıklar ve beklenmedik tehlikelerle doludur. Percy bir yandan ihanet eden kuzeni Luke’u durdurmaya, diğer yandan yeniden uyanmak üzere olan kadim bir kötülüğün dünyaya yayılmasını engellemeye çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/percy-jackson-2-canavarlar-denizi-2013-izle.webp", backdrop = "", year = "2013", score = 5.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/percy-jackson-2-canavarlar-denizi/", category = "Film"),
    Movie(id = 1000206, title = "Percy Jackson: Şimşek Hırsızı", overview = "Percy Jackson, sıradan bir genç olduğunu düşünürken hayatının aslında Yunan mitolojisiyle bağlantılı olduğunu öğrenir. Babasının denizlerin tanrısı Poseidon olduğunu keşfeden Percy, bir anda kendisini tanrılar, yarı tanrılar ve mitolojik yaratıklarla dolu bir dünyanın içinde bulur. Ancak Zeus’un güçlü şimşeği çalındığında suç Percy’nin üzerine kalır. Kendini ve masumiyetini kanıtlamak isteyen genç yarı tanrı, çalınan şimşeği bulmak için tehlikeli bir yolculuğa çıkar. Bu macera sırasında hem sahip olduğu güçleri keşfedecek hem de gerçek kimliğiyle yüzleşecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/percy-jackson-simsek-hirsizi-2010-izle.webp", backdrop = "", year = "2010", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/percy-jackson-simsek-hirsizi/", category = "Film"),
    Movie(id = 1000207, title = "Pers Prensi: Zamanın Kumları", overview = "Pers İmparatorluğu’nun genç prensi Dastan, savaşçı ruhu ve başına buyruk tavırlarıyla saray hayatından çok maceraya ilgi duyar. Ancak gizemli bir hançerin ortaya çıkmasıyla hayatı tamamen değişir. Zamanı geri alma gücüne sahip olan bu hançer, efsanevi Zamanın Kumları’nı kontrol edebilmenin anahtarıdır. Dastan, gizemli Prenses Tamina ile birlikte bu güçlü silahı ele geçirmek isteyen düşmanların peşine düşer. Kızgın çöllerde başlayan kovalamaca, ikiliyi ihanetlerin, gizli planların ve ölümcül tehlikelerin ortasına sürükler. Artık yalnızca kendi hayatlarını değil, tüm dünyanın kaderini etkileyebilecek bir gücün yanlış ellere geçmesini önlemeleri gerekmektedir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/pers-prensi-zamanin-kumlari-2010-izle.webp", backdrop = "", year = "2010", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/pers-prensi-zamanin-kumlari-izle/", category = "Film"),
    Movie(id = 1000208, title = "Beni Asla Bırakma", overview = "Ruth, Kathy ve Tommy, dış dünyadan uzak, huzurlu görünen bir İngiliz yatılı okulunda birlikte büyür. Çocukluk yıllarında kurdukları güçlü dostluk, gençlik dönemine geçtiklerinde karmaşık duygularla sınanmaya başlar. Ancak üç arkadaşın hayatında asıl belirleyici olan, kendilerinden yıllarca saklanan korkunç gerçektir. Yetişkinliğe adım attıkça geçmişlerinin ardındaki sırrı öğrenen Ruth, Kathy ve Tommy, değiştirmeleri mümkün olmayan kaderleriyle yüzleşmek zorunda kalır. Kazuo Ishiguro’nun romanından uyarlanan film, sevgi, kayıp ve insan olmanın anlamını karanlık bir alternatif dünyada sorguluyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/beni-asla-birakma-2010-izle.webp", backdrop = "", year = "2010", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/beni-asla-birakma-2010-izle/", category = "Film"),
    Movie(id = 1000209, title = "Cennetin Krallığı", overview = "Hayatındaki kayıpların ardından kendisini yalnız ve umutsuz hisseden Balian’ın kaderi, hiç tanımadığı babasının ortaya çıkmasıyla değişir. Uzun yıllar Kutsal Topraklar’da savaşan şövalye Godfrey, Fransa’ya döndüğünde Balian’ın oğlu olduğunu açıklar. Ona şövalyeliğin yalnızca savaşmaktan ibaret olmadığını öğreten Godfrey, oğlunu büyük bir yolculuğa hazırlar. Babasının ölümünden sonra onun kılıcını kuşanan Balian, Kudüs’e gider ve burada son derece hassas bir barış ortamıyla karşılaşır. Kral IV. Baldwin’in barışı koruma çabalarına rağmen savaşın yeniden başlaması an meselesidir. Balian, savaş meydanındaki becerileriyle ün kazanırken Kral’ın kız kardeşi Sybilla’nın da güvenini kazanır. Fakat bu durum, özellikle Guy…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/cennetin-kralligi-2005-izle.webp", backdrop = "", year = "2005", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cennetin-kralligi/", category = "Film"),
    Movie(id = 1000210, title = "Yanyol", overview = "Miles Raymond, hayatının hem özel hem de mesleki anlamda istediği gibi gitmediğini düşünen bir İngilizce öğretmenidir. Asıl hayali başarılı bir yazar olmak olsa da bu konuda bir türlü istediği noktaya ulaşamaz. Yakın arkadaşı Jack ise çok tanınmayan bir televizyon oyuncusudur ve kısa süre içinde evlenecektir. Düğün öncesinde birlikte biraz zaman geçirmek isteyen Jack ve Miles, bir hafta sürecek bir yolculuğa çıkar. Ancak bu gezi, iki arkadaş için yalnızca eğlenceli bir kaçamak olmaktan çıkarak geçmişleriyle, ilişkileriyle ve gelecekleriyle yüzleşecekleri unutulmaz bir döneme dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/sideways-2004-izle.webp", backdrop = "", year = "2004", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yanyol-2004-izle/", category = "Film"),
    Movie(id = 1000211, title = "Yürüyen Şato", overview = "Sophie, hayatı bir anda değişen genç bir kızdır. Kötü kalpli bir cadının yaptığı büyü yüzünden bir gecede doksan yaşında bir kadına dönüşür. Kimsenin kendisini tanımadığı bu yeni haliyle evinden ayrılan Sophie, yolu büyücü Howl’un gizemli ve hareket eden şatosuna düşer. Burada yalnızca kendisinin değil, şatoda yaşayan başka bir varlığın da benzer bir büyünün etkisinde olduğunu öğrenir. İki farklı kaderin kesişmesiyle Sophie ve yeni dostu, üzerlerindeki laneti bozmanın yollarını aramaya başlar. Ancak dışarıda giderek büyüyen savaş, onları kendi sorunlarından çok daha büyük bir mücadelenin içine sürükler.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/yuruyen-sato-2004-izle.webp", backdrop = "", year = "2004", score = 8.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yuruyen-sato/", category = "Film"),
    Movie(id = 1000212, title = "Yarından Sonra", overview = "Dünya, daha önce görülmemiş bir iklim felaketinin pençesine düşer. Şiddetli kasırgalar Los Angeles’ı yerle bir ederken, Yeni Delhi dondurucu soğukların altında kalır ve Tokyo devasa dolu yağışlarıyla büyük bir yıkım yaşar. New York ise yükselen dev dalgaların tehdidiyle karşı karşıyadır. İklim bilimci Jack Hall, küresel ısınmanın tetiklediği bu korkunç değişimin nedenlerini çözmeye ve insanlığın hayatta kalabilmesi için bir çıkış yolu bulmaya çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/yarindan-sonra-2004-izle.webp", backdrop = "", year = "2004", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yarindan-sonra/", category = "Film"),
    Movie(id = 1000213, title = "İşaretler", overview = "Graham Hess, ailesiyle birlikte sakin bir çiftlik hayatı sürdürürken tarlasında ortaya çıkan devasa şekillerle karşılaşır. Ekinlerin üzerinde bir gecede beliren bu gizemli işaretlerin benzerleri kısa süre içinde dünyanın farklı bölgelerinde de görülmeye başlayınca, olayın sıradan bir durum olmadığı anlaşılır. Graham ve ailesi, bu şekillerin dünya dışından gelen varlıklarla bağlantılı olabileceği ihtimaliyle giderek daha büyük bir korkuya kapılır. Dünya bilinmeyen bir tehditle karşı karşıya kalırken, aile kendilerini çevreleyen tehlikeye karşı hayatta kalmaya ve birbirlerine tutunmaya çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/isaretler-2002-izle.webp", backdrop = "", year = "2002", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/isaretler/", category = "Film"),
    Movie(id = 1000214, title = "Telefon Kulübesi", overview = "Stu Shepard, New York’ta kariyerini hızla ilerleten, başarılı ve hırslı bir reklamcıdır. Ancak gizli bir ilişki yaşadığı sırada kullandığı telefon kulübesine gelen tek bir çağrı, hayatını bir anda altüst eder. Telefonun diğer ucundaki gizemli ses, yakındaki bir binada saklanan bir nişancının Stu’yu hedef aldığını ve telefonu kapatması halinde öleceğini söyler. Üstelik ondan karısına ve sevgilisine gerçekleri itiraf etmesini ister. Polis olay yerine geldiğinde çıkmaz bir durumda kalan Stu, hem hayatta kalmak hem de karşısındaki kişinin kim olduğunu anlamak için zekâsını kullanmak zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/telefon-kulubesi-2002-izle.webp", backdrop = "", year = "2002", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/telefon-kulubesi/", category = "Film"),
    Movie(id = 1000215, title = "Pearl Harbor", overview = "Rafe McCawley ve Danny Walker, çocukluklarından beri ayrılmayan iki yakın arkadaş ve başarılı pilottur. Amerikan Hava Kuvvetleri’ne katılan ikilinin hayatı, Rafe’in cesur hemşire Evelyn Stewart’a aşık olmasıyla farklı bir yöne ilerler. Ancak Rafe’in savaşın merkezine gitme arzusu, sevdiği kadından ve en yakın arkadaşından uzaklaşmasına neden olur. Avrupa’da Nazilere karşı mücadele eden Eagle Squadron’a katılan Rafe, bir gün geri döneceğine söz vererek yola çıkar. Bu sırada Evelyn ve Danny, Pasifik’teki Pearl Harbor’a tayin edilir. Savaşın gölgesinde başlayan bu ayrılık, dostluk, aşk ve sadakat arasında zorlu bir sınava dönüşecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/pearl-harbor-2001-izle.webp", backdrop = "", year = "2001", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/pearl-harbor/", category = "Film"),
    Movie(id = 1000216, title = "Mulan", overview = "Hua Mulan, ailesinin onurunu korumak kadar kendi hayatının kontrolünü elinde tutmak isteyen genç bir kadındır. Kuzeyden gelen tehdit karşısında İmparator’un orduya asker toplama emri, Mulan’ın hayatını tamamen değiştirir. Yaşlı ve hasta babasının savaşa gitmesine izin vermeyen Mulan, erkek kılığına girerek onun yerine orduya katılır. Hua Jun kimliğiyle ağır bir eğitimden geçen genç kadın, zamanla savaş alanındaki olağanüstü yeteneklerini ortaya çıkarmaya başlar. Fakat gerçek kimliğinin ortaya çıkma tehlikesi, hem kendisini hem de birlikte savaştığı askerleri zor durumda bırakır. Mulan artık yalnızca ailesini korumak için değil, kim olduğunu göstermek için de mücadele…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/mulan-2020-izle.webp", backdrop = "", year = "2020", score = 5.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/mulan-2020-izle/", category = "Film"),
    Movie(id = 1000217, title = "Mulan 2", overview = "Mulan ve General Shang, hayatlarını birleştirmeye hazırlanırken karşılarına beklenmedik engeller çıkar. Shang’in evlilik teklifinin ardından Mulan’ın en yakın dostlarından Mushu, koruyucu ejder olarak sahip olduğu konumu kaybetme ihtimaliyle karşı karşıya kalır. Bu yüzden genç çiftin arasını açmak için gizlice harekete geçer. Tam bu sırada Mulan ve Shang’e, üç prensesi uzak bir bölgeden alarak evlenecekleri yere götürme görevi verilir. Yolculuk sırasında prenseslerin kaderlerini belirleyecek evlilikleri aslında istemediklerini öğrenen Mulan, sessiz kalmak yerine harekete geçmeye karar verir. Sevgi, dostluk ve cesaretin öne çıktığı bu macera, Mulan’ın bildiği yoldan gitmek yerine doğru olduğuna…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/mulan-2-2004-izle.webp", backdrop = "", year = "2004", score = 5.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/mulan-2-2004-izle/", category = "Film"),
    Movie(id = 1000218, title = "Unabomber", overview = "Gerçek olaylardan esinlenen bu dram, Ted Kaczynski’nin Harvard’da parlak bir öğrenci olarak başlayan hayatının zamanla nasıl bambaşka bir yöne sürüklendiğini anlatıyor. FBI’ın yıllarca peşinden gittiği Kaczynski’nin akademik dünyadaki yükselişinden Unabomber olarak tanınmasına uzanan sıra dışı hikâyesi gözler önüne seriliyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/unabomber-2026-izle.webp", backdrop = "", year = "2026", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/unabomber-2026-izle/", category = "Film"),
    Movie(id = 1000219, title = "Hız Tuzağı 2: Seyir Kontrol", overview = "Annie Porter, sevgilisiyle birlikte Karayipler’de keyifli bir tatil geçirmek için büyük bir yolcu gemisine biner. Ancak kısa süre sonra geminin bilgisayar sistemi gizemli bir hacker tarafından ele geçirilir. Geminin kontrolünü ele geçiren bu kişi, yolcuları büyük bir tehlikenin içine sürükler. Üstelik geminin belirli bir hızın altına düşmesi durumunda patlayacak şekilde hazırlanan bir düzenek, herkesi zamana karşı yarışmak zorunda bırakır. Speed 2: Cruise Control, ilk filmdeki yüksek tempolu aksiyonu bu kez karadan denize taşıyor. Başrollerde Sandra Bullock ve Jason Patric yer alırken, Willem Dafoe da filmin dikkat çeken isimleri arasında bulunuyor.…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/hiz-tuzagi-2-seyir-kontrol-1997-izle.webp", backdrop = "", year = "1997", score = 4.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hiz-tuzagi-2-seyir-kontrol/", category = "Film"),
    Movie(id = 1000220, title = "Hız Tuzağı", overview = "Jack Traven, tehlikeli suçlu Howard’ın kurduğu bir tuzağı bozarak on üç kişinin hayatını kurtarmıştır. Fakat Howard’ın asıl planının henüz sona ermediği kısa sürede ortaya çıkar. İçinde yolcular bulunan bir otobüse yerleştirilen bomba, araç belirli bir hızın altına indiğinde patlayacak şekilde hazırlanmıştır. Jack, bu ölümcül düzenekten haberdar olduğunda otobüsün kontrolünü ele geçirmek zorunda kalır. Artık tek amacı, aracın hızını güvenli seviyede tutarak yolcuları hayatta bırakmaktır. Şehir trafiğinin ortasında başlayan bu tehlikeli mücadelede Jack’in karşısındaki en büyük düşman ise yalnızca bomba değil, tükenen zamandır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/hiz-tuzagi-1994-izle.webp", backdrop = "", year = "1994", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hiz-tuzagi-1994-izle/", category = "Film"),
    Movie(id = 1000221, title = "Yırtık Rahibe", overview = "Deloris, hayatını sahnelerde şarkı söyleyerek kazanan, özgüveni yüksek ve başına buyruk bir kadındır. Ancak bir gün kendisini tehlikeli bir çetenin hedefinde bulunca hayatı tamamen değişir. Güvenliğini sağlamak için polis tarafından bir manastıra yerleştirilen Deloris, burada rahibelerin arasında gizlenerek bir süre ortadan kaybolmak zorunda kalır. Başlangıçta manastırın kurallarına ve sakin düzenine uyum sağlamakta güçlük çeken Deloris, kısa sürede kendine özgü tavırlarıyla çevresindekileri etkiler. Özellikle kilise korosunun müzik konusunda oldukça yetersiz olduğunu fark edince işe koyulur ve koroyu hareketli, neşeli bir müzik grubuna dönüştürür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/yirtik-rahibe-1992-izle.webp", backdrop = "", year = "1992", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yirtik-rahibe-1992-izle/", category = "Film"),
    Movie(id = 1000222, title = "Müthiş Dadı", overview = "Daniel Hillard, çocuklarına düşkün ve sevgi dolu bir baba olsa da sorumsuz tavırları evliliğinin sona ermesine neden olur. Miranda ile yollarını ayırmak zorunda kalan Daniel, mahkemenin çocukların anneleriyle kalmasına karar vermesiyle onları her gün göremeyecek olmanın üzüntüsünü yaşar. Çocuklarından uzak kalmaya niyeti olmayan Daniel, aklına oldukça sıra dışı bir plan getirir. Kendisini Mrs. Doubtfire adında yaşlı bir kadın gibi göstererek Miranda’nın evinde dadı olarak işe girer. Bu yeni kimlikle çocuklarıyla vakit geçirme fırsatı bulan Daniel, bir yandan aile bağlarını yeniden kurmaya çalışırken diğer yandan gerçek kimliğini gizlemek zorunda kalır. Fakat…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/muthis-dadi-1993-izle.webp", backdrop = "", year = "1993", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/muthis-dadi/", category = "Film"),
    Movie(id = 1000223, title = "Özel Bir Kadın", overview = "Edward, büyük bir servete sahip olmasına rağmen sahip olduğu gösterişli hayatın kendisine artık hiçbir şey ifade etmediğini düşünmektedir. Bir gece Los Angeles sokaklarında dolaşırken Vivian adında genç bir kadınla tanışır. Aralarında başlayan yakınlığın ardından Edward, Vivian’la bir hafta boyunca birlikte yaşamayı teklif eder. Bu süre boyunca birbirlerine sevgili gibi davranacak, bir haftanın sonunda ise ilişkilerini sonlandıracaklardır. Başlangıçta yalnızca karşılıklı bir anlaşma olarak görülen bu birliktelik, günler geçtikçe ikisinin de hayatını değiştirmeye başlar. Edward ve Vivian, birbirlerini tanıdıkça aralarındaki ilişkinin planladıklarından çok daha güçlü bir bağa dönüştüğünü fark eder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/ozel-bir-kadin-1990-izle.webp", backdrop = "", year = "1990", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ozel-bir-kadin/", category = "Film"),
    Movie(id = 1000224, title = "Beklenmeyen Şahit", overview = "Kalp rahatsızlığı nedeniyle doktorların tavsiyesiyle dinlenmeye çekilen usta avukat Sir Wilfrid Robarts, Leonard Vole’un cinayet suçlamasıyla karşı karşıya olduğunu öğrenince yeniden mesleğine dönmeye karar verir. Vole, varlıklı bir dul kadının ölümünden sorumlu tutulmaktadır ve aleyhindeki durum oldukça ciddidir. Fakat davayı daha da sıra dışı hâle getiren bir ayrıntı vardır: Vole’un eşi Christine, kocasını savunmak yerine savcılığın en önemli tanıklarından biri olacaktır. Robarts, mahkeme salonunda Vole’un masumiyetini kanıtlamaya çalışırken hem delillerle hem de beklenmedik tanıklıklarla mücadele etmek zorunda kalır. Gerçek ile yalan arasındaki sınır giderek belirsizleşirken dava şaşırtıcı bir noktaya ulaşır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/witness-for-the-prosecution-1957-izle.webp", backdrop = "", year = "1957", score = 8.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/beklenmeyen-sahit/", category = "Film"),
    Movie(id = 1000225, title = "Sunset Bulvarı", overview = "Genç senarist Joe Gillis, Hollywood’da istediği başarıyı yakalayamayınca hem parasız hem de borç içinde kalır. Alacaklılarından kaçarken yolu Sunset Bulvarı’ndaki gizemli bir malikaneye düşer. Burada karşılaştığı kişi, sessiz filmler döneminde büyük bir yıldız olan ancak zamanla sinema dünyasından uzaklaşan Norma Desmond’dır. Norma, geçmişteki şöhretinin hâlâ sürdüğüne inanmakta ve hazırladığı senaryoyla yeniden beyaz perdeye dönmeyi planlamaktadır. Joe ise bu fırsatı değerlendirerek Norma’nın senaryosunu geliştirmesine yardım etmeye başlar ve karşılığında malikanede kalacak bir yer edinir. Ancak Hollywood hayalleri, geçmişe tutunma ve giderek büyüyen takıntılar, Joe’yu hiç beklemediği bir sona doğru sürükler.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/sunset-boulevard-1950-izle.webp", backdrop = "", year = "1950", score = 8.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sunset-bulvari/", category = "Film"),
    Movie(id = 1000226, title = "Nil’de Ölüm", overview = "Nil Nehri üzerinde romantik bir balayı geçiren Linnet Doyle ve eşi, kısa süre içinde kendilerini korkunç bir olayın ortasında bulur. Linnet’in gemide öldürülmesi, sakin başlayan yolculuğu karmaşık bir cinayet soruşturmasına çevirir. O sırada gemide bulunan ünlü dedektif Hercule Poirot, kaptanın talebiyle olayın sorumlularını bulmak için harekete geçer. Gemideki herkesin şüpheli hale geldiği soruşturmada Poirot, cinayetin ardındaki gerçeği ortaya çıkarmak için ipuçlarını tek tek bir araya getirmek zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/nilde-olum-2022-izle.webp", backdrop = "", year = "2022", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/nilde-olum-2022-izle/", category = "Film"),
    Movie(id = 1000227, title = "Cruella", overview = "Estella, Londra sokaklarında kendi ayakları üzerinde durmaya çalışan, yaratıcı ve yetenekli genç bir kadındır. Moda konusundaki sıra dışı yeteneğini kullanarak kendine bir gelecek kurmak isteyen Estella, iki genç hırsızla tanışmasının ardından hayatını onların yanında sürdürmeye başlar. Tasarımları sayesinde kısa sürede moda dünyasının dikkatini çeken genç kadın, dönemin en güçlü isimlerinden Barones von Hellman’ın radarına girer. Ancak aralarındaki karmaşık ilişki, Estella’nın içindeki karanlık tarafı ortaya çıkarır ve onu zamanla Cruella olarak bilinen cesur ve acımasız kadına dönüştürür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/cruella-2021-izle.webp", backdrop = "", year = "2021", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/cruella-2021-izle/", category = "Film"),
    Movie(id = 1000228, title = "Gizli Bir Yaşam", overview = "II. Dünya Savaşı’nın karanlık günlerinde yaşayan Avusturyalı çiftçi Franz Jägerstätter, Nazi rejimi adına savaşmayı reddederek vicdanının sesini dinlemeyi seçer. Bu karar, onu hem çevresindeki insanların baskısıyla hem de ölüm cezasıyla karşı karşıya bırakır. Terence Malick, gerçek bir olaydan uyarladığı filmde Franz’ın inançlarını, ailesiyle ilişkisini ve verdiği zorlu kararın sonuçlarını ele alıyor. Yönetmenin kendine özgü görsel anlatımıyla şekillenen yapım, savaşın ortasında bireysel duruşun ve vicdanın anlamı üzerine düşündürücü bir hikâye sunuyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/gizli-bir-yasam-2019-izle.webp", backdrop = "", year = "2019", score = 7.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/gizli-bir-yasam-2019-izle/", category = "Film"),
    Movie(id = 1000229, title = "Alaaddin", overview = "Agrabah’ta sokaklarda yaşayan genç bir hırsız olan Aladdin, sahip olduğu her şeye rağmen yardımseverliği ve cesaretiyle dikkat çeker. Hayatı, karşılaştığı gizemli bir genç kızla tanışmasıyla bambaşka bir hal alır. Bu kızın Sultan’ın kızı Jasmine olduğunu öğrenen Aladdin, ona duyduğu aşkın peşinden gitmeye karar verir. Ancak kader onu Harikalar Mağarası’na götürdüğünde, bulduğu sihirli lamba sayesinde üç dilek hakkı bulunan eğlenceli bir cinle tanışır. Aladdin’in hayatını değiştirebilecek bu güç, aynı zamanda tehlikeli bir adamın da ilgisini çeker. Sultan’ın danışmanı Jafar, lambayı ele geçirerek kendi amaçlarına ulaşmak için harekete geçer.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/aladdin-2019-izle.webp", backdrop = "", year = "2019", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/alaaddin-2019-izle/", category = "Film"),
    Movie(id = 1000230, title = "El Royale’de Zor Zamanlar", overview = "Tahoe Gölü kıyısındaki eski ve bakımsız El Royale Oteli, birbirinden tamamen farklı yollardan gelen yedi yabancının buluşma noktası olur. Her birinin ardında gizlediği karanlık bir geçmiş ve kimseyle paylaşmak istemediği sırları vardır. Gece ilerledikçe oteldeki dengeler değişir ve saklanan gerçekler birer birer ortaya çıkmaya başlar. Artık geçmişlerinden kaçmak yerine onunla yüzleşmek zorun da olan bu yedi kişi için hayatta kalmak ve kendilerini kurtarmak hiç kolay olmayacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/bad-times-at-the-el-royale-2018-izle.webp", backdrop = "", year = "2018", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/el-royalede-zor-zamanlar/", category = "Film"),
    Movie(id = 1000231, title = "Free Solo", overview = "Alex Honnold, sınırları zorlayan serbest tırmanış kariyerinde daha önce hiç denemediği bir meydan okumayla karşı karşıyadır. Sevdiklerinin onu bu kararından vazgeçirme çabalarına rağmen Honnold, Yosemite’deki devasa El Capitan kayalığına ip ve herhangi bir güvenlik ekipmanı olmadan çıkmaya karar verir. Bu tırmanış yalnızca fiziksel gücünü değil, konsantrasyonunu ve korkularını kontrol etme becerisini de sınayacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/free-solo-2018-izle.webp", backdrop = "", year = "2018", score = 8.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/free-solo/", category = "Film"),
    Movie(id = 1000232, title = "En İyiler Yarışıyor", overview = "Çocukluklarından beri yakın arkadaş olan iki genç, UCLA’in rekabetçi Bollywood füzyon dans takımına katılarak kendilerini yepyeni bir dünyanın içinde bulur. ABD Şampiyonası’na ulaşma hayaliyle yola çıkan ikili, takım içindeki rekabetin ve yoğun antrenmanların düşündüklerinden çok daha zorlu olduğunu fark eder. Başarıya ulaşmak için yalnızca yeteneklerini değil, dostluklarını ve birbirlerine olan güvenlerini de sınamaları gerekecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/best-of-the-best-2026-izle.webp", backdrop = "", year = "2026", score = 4.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/en-iyiler-yarisiyor/", category = "Film"),
    Movie(id = 1000233, title = "Deha", overview = "Hayatında pek çok başarısızlık yaşamış olan Frank Adler, Florida kırsalında küçük yeğeni Mary’yi tek başına büyütmektedir. Mary’nin okula başlamasıyla birlikte sıra dışı matematik yeteneği kısa sürede fark edilir ve genç kızın geleceğiyle ilgili planlar yapılmaya başlanır. Ancak Frank, Mary’nin normal bir çocukluk geçirmesini isterken, çocuğun annesi Evelyn onun üstün yeteneğinin değerlendirilmesi gerektiğini düşünür. İkili arasındaki fikir ayrılığı kısa sürede Mary’nin velayeti konusunda büyük bir mücadeleye dönüşür ve mesele mahkeme salonlarına taşınır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/deha-2017-izle.webp", backdrop = "", year = "2017", score = 7.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/deha-2017-izle/", category = "Film"),
    Movie(id = 1000234, title = "Sindirella", overview = "Ella’nın hayatı, önce annesini, ardından çok sevdiği babasını kaybetmesiyle tamamen değişir. Babasının yeniden evlenmesiyle birlikte ailesine katılan Tremaine, Anastasia ve Drizella’yı başlangıçta sevgiyle karşılayan genç kız, babasının ölümünden sonra onların gerçek yüzleriyle karşılaşır. Üvey annesi ve kız kardeşleri tarafından kendi evinde hizmetçi gibi çalıştırılan Ella, yaşadığı tüm zorluklara rağmen umudunu korumaya çabalar. Tam her şeyin sona erdiğini düşündüğü sırada şehirde düzenlenecek görkemli bir balo, ona yeni bir hayatın kapısını aralar. Baloda tanışacağı gizemli adam ise Ella’nın hayallerinin ötesinde bir değişimin başlangıcı olur. Lily James’in başrolünde yer aldığı bu Cinderella uyarlamasında…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/sindirella-2015-izle.webp", backdrop = "", year = "2015", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sindirella-2015-izle/", category = "Film"),
    Movie(id = 1000235, title = "Brooklyn", overview = "Eilis Lacey, İrlanda’nın küçük ve yoksul bir kasabasında, geleceği için fazla seçenek bulamadan yaşamını sürdürmektedir. Annesinin desteği ve kasabanın papazının yardımıyla Amerika’ya gitme fırsatı yakalayan genç kadın, 1950’li yılların New York’unda yeni bir hayata başlamak üzere Brooklyn’e yerleşir. Başlangıçta yalnızlık ve yabancılık duygusuyla mücadele eden Eilis, zamanla kendi ayakları üzerinde durmayı öğrenir ve genç bir adama karşı duygular beslemeye başlar. Ancak memleketinden gelen bir haber onu yeniden İrlanda’ya dönmeye zorlar. Eski hayatı ile Amerika’da kurduğu yeni dünya arasında kalan Eilis, kalbinin ve geleceğinin hangi tarafa ait olduğuna karar vermek zorunda…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/brooklyn-2015-izle.webp", backdrop = "", year = "2015", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/brooklyn-2015-izle/", category = "Film"),
    Movie(id = 1000236, title = "Liseli Polisler 2", overview = "Schmidt ve Jenko, lisedeki başarılı gizli görevlerinin ardından yeniden birlikte sahaya çıkar. Bu kez yolları bir üniversiteye düşen iki polis, öğrenci kılığına girerek yeni bir operasyonun peşine düşer. Ancak üniversite hayatı, ikilinin beklediğinden çok daha karmaşık hale gelir. Jenko kendisini okulun futbol takımında bulurken Schmidt bir tiyatro grubuna katılır ve ikisi de yeni çevrelerinde farklı bir hayat kurmaya başlar. Zamanla hem görevlerini hem de aralarındaki ortaklığı sorgulayan ikili, yetişkinliğe adım atarken dostluklarını koruyup koruyamayacaklarını da sınamak zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/liseli-polisler-2-2014-izle.webp", backdrop = "", year = "2014", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/liseli-polisler-2-2014-izle-1/", category = "Film"),
    Movie(id = 1000237, title = "Liseli Polisler", overview = "Polis akademisinden yeni mezun olan Schmidt ve Jenko, ilk görevlerinde hiç beklemedikleri bir operasyonun içine düşer. İki genç polis, lise öğrencisi kılığına girerek bir liseye gönderilir ve burada öğrenciler arasındaki uyuşturucu, alkol ve diğer yasa dışı olayları araştırmaları istenir. Ancak yeniden lise hayatına dönmek, ikilinin geçmişte bıraktığını sandığı ergenlik sorunlarını da beraberinde getirir. Görevlerini yerine getirmek yerine okul hayatının cazibesine kapılmaya başlayan Schmidt ve Jenko, hem suçluları bulmaya hem de kendi gençlikleriyle yüzleşmeye çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/liseli-polisler-2012-izle.webp", backdrop = "", year = "2012", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/liseli-polisler-2012-izle-1/", category = "Film"),
    Movie(id = 1000238, title = "Aşk Hipotezi", overview = "Doktora öğrencisi Olive, akademik hayatında oldukça zor bir dönem geçirirken kendisini beklenmedik bir durumun içinde bulur. Bölümün sert mizacı ve korkulan profesörü Adam Carlsen’ı bir anda öpmesi, ikisinin hayatında yeni bir sayfa açar. Başlangıçta yalnızca belirli bir amaca hizmet eden sahte bir ilişki kurmaya karar veren ikili, zaman geçtikçe aralarındaki çekimin sandıklarından çok daha gerçek olduğunu fark eder. Bilimsel araştırmalar ve akademik rekabet arasında başlayan bu oyun, yavaş yavaş aşkın açıklanması zor formülüne dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-love-hypothesis-2026-izle.webp", backdrop = "", year = "2026", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ask-hipotezi-2026-izle-2/", category = "Film"),
    Movie(id = 1000239, title = "Alis Harikalar Diyarında 2: Aynanın İçinden", overview = "Alis Kingsleigh, yıllar sonra yeniden Harikalar Diyarı’nın büyülü dünyasına geri döner. Bu kez karşısında çok daha farklı bir sorun vardır: Çılgın Şapkacı kendisinde olmayan eski neşesini kaybetmiş ve geçmişiyle ilgili büyük bir sırrın etkisi altına girmiştir. Alis, Şapkacı’yı kurtarmanın yolunu bulabilmek için zamanın kendisiyle yüzleşmek zorunda kalır. Mirana’nın yardımıyla Büyük Saat’in odasından Renkküreyi alan Alis, geçmişe doğru tehlikeli bir yolculuğa çıkar. Zamanın farklı noktalarında arkadaşlarının ve düşmanlarının gençlik dönemleriyle karşılaşan Alis, süre dolmadan Şapkacı’yı kurtarmanın bir yolunu bulmaya çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/alis-harikalar-diyarinda-2-aynanin-icinden-2016-izle.webp", backdrop = "", year = "2016", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/alis-harikalar-diyarinda-2-aynanin-icinden/", category = "Film"),
    Movie(id = 1000240, title = "Alis Harikalar Diyarında", overview = "Tim Burton’ın kendine özgü fantastik dünyasıyla yeniden yorumladığı Alice Harikalar Diyarında, 17 yaşındaki Alice’in gizemli bir maceraya sürüklenmesini konu ediyor. Sosyeteye tanıtım partisinde kendisini takip eden beyaz tavşanın peşinden giden Alice, bir anda Harikalar Diyarı’nda bulur kendini. Ancak bu dünya onun için tamamen yabancı değildir. Alice, aslında çocukken burayı daha önce ziyaret etmiştir fakat yaşadığı olayları ve bu fantastik dünyayı zamanla unutmuştur. Yeniden karşısına çıkan tuhaf karakterler arasında Çılgın Şapkacı da vardır. Johnny Depp’in canlandırdığı bu karakter, Alice’in macerasında önemli bir yere sahip olurken, Helena Bonham Carter Kırmızı Kraliçe olarak…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/alis-harikalar-diyarinda-2010-izle.webp", backdrop = "", year = "2010", score = 0.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/alis-harikalar-diyarinda/", category = "Film"),
    Movie(id = 1000241, title = "127 Saat", overview = "Gerçek bir yaşam öyküsünden uyarlanan film, genç dağcı Aron Ralston’un Utah’ta çıktığı zorlu yolculuğun kabusa dönüşmesini konu ediyor. Tek başına keşfe çıkan Aron, dev bir kayanın arasında sıkışıp kalınca bulunduğu yerden kurtulamayacağını fark eder. Yanında yalnızca sınırlı miktarda su ve yiyecek bulunan genç adam, zaman ilerledikçe hem fiziksel hem de psikolojik olarak büyük bir mücadele vermeye başlar. Yaşadıklarını kamerasına kaydederek kendisini ayakta tutmaya çalışan Aron, zaman zaman halüsinasyonlar görür. Hayatta kalabilmek için ailesine, özellikle de anne ve babasına duyduğu sevgiyi yeniden hatırlayan genç dağcı, özgürlüğüne kavuşmak için zorlu bir karar…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/127-saat-2010-izle.webp", backdrop = "", year = "2010", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/127-saat-2010-izle/", category = "Film"),
    Movie(id = 1000242, title = "Benimle Evlenir Misin?", overview = "Jane, hayatı boyunca tam 27 kez nedimelik yapmış ve her defasında başkalarının mutluluğuna tanıklık etmiştir. Nedimelik artık onun için sıradan bir görevden çok hayatının bir parçası haline gelmiştir. Kız kardeşinin evleneceğini öğrenince, bir kez daha bu görevi üstlenmekten hiç çekinmez. Ancak düğün hazırlıkları sırasında damadı gördüğünde işler tamamen değişir. Çünkü müstakbel damat, Jane’in uzun zamandır gizlice âşık olduğu Kevin’dir. Kardeşinin düğününü kusursuz hale getirmeye çalışırken kendi duygularıyla da yüzleşmek zorunda kalan Jane, hiç beklemediği bir aşk mücadelesinin içine sürüklenir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/benimle-evlenir-misin-2008-izle.webp", backdrop = "", year = "2008", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/benimle-evlenir-misin/", category = "Film"),
    Movie(id = 1000243, title = "Deja Vu", overview = "New Orleans’ta meydana gelen büyük bir patlama, Ajan Doug Carlin’i alışılmışın dışında bir soruşturmanın içine sürükler. Olayı çözebilmek için son derece gelişmiş bir teknoloji kullanan Carlin, geçmişte yaşananları ayrıntılarıyla izleme ve olayların akışını yeniden değerlendirme fırsatı bulur. Ancak sistemin sunduğu imkanlar, Carlin’in yalnızca geçmişi gözlemlemesini değil, belirli bir noktaya geri dönerek yaşananlara müdahale etmesini de mümkün kılar. Patlamadan kısa bir süre öncesine ulaşan Carlin, hem gerçeği ortaya çıkarmak hem de yaklaşan felaketi engellemek için zamanla yarışmaya başlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/deja-vu-2006-izle.webp", backdrop = "", year = "2006", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/deja-vu-2006-izle/", category = "Film"),
    Movie(id = 1000244, title = "İyi Bir Yıl", overview = "Londra’da yatırım danışmanı olarak çalışan Max Skinner, amcasından kalan Provence’daki üzüm bağını satmak için Fransa’ya gider. Amacı, miras kalan mülkü elinden çıkarıp hayatına kaldığı yerden devam etmektir. Ancak bağın kendisine ait olduğunu söyleyen Amerikalı bir kadının ortaya çıkması, Max’in planlarını altüst eder. Başlangıçta bu durumdan oldukça rahatsız olan Max, zaman geçtikçe Provence’ın huzurlu atmosferine ve burada kurduğu yeni ilişkilere kendini kaptırmaya başlar. Satmak için geldiği üzüm bağı, kısa sürede onun hayatını yeniden değerlendirmesine neden olacak bir yere dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/a-good-year-2006-izle.webp", backdrop = "", year = "2006", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/iyi-bir-yil-2006-izle/", category = "Film"),
    Movie(id = 1000245, title = "Ben Robot", overview = "2035 yılında robotlar insanların günlük yaşamının vazgeçilmez bir parçası haline gelmiştir. Ancak Chicago Polis Departmanı’nda görev yapan dedektif Del Spooner, gelişen teknolojiye ve robotlara karşı derin bir güvensizlik beslemektedir. Bir bilim insanının şüpheli ölümüyle görevlendirildiğinde ise korkuları daha da güçlenir. Dr. Miles Hogenmiller’ın ölümünün ardında sıradan bir cinayetten çok daha fazlası olduğu ortaya çıkar. Üstelik soruşturmanın izleri, insanlara zarar vermesi mümkün olmadığı düşünülen bir robota kadar uzanmaktadır. Spooner, gizli bir projenin peşine düştükçe olayların göründüğünden çok daha tehlikeli olduğunu keşfeder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/ben-robot-2004-izle.webp", backdrop = "", year = "2004", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ben-robot-2004-izle/", category = "Film"),
    Movie(id = 1000246, title = "Aman Tanrım 2", overview = "Evan Baxter, gazeteciliği geride bırakıp siyasete atılarak hayatında yeni bir sayfa açmaya karar verir. Kariyerindeki değişimin ardından Buffalo’dan Virginia’ya taşınan Evan, her şeyin istediği gibi ilerlediğini düşünürken karşısına gizemli bir ziyaretçi çıkar. Bu kişinin Tanrı olduğunu öğrenen Evan, ondan aldığı beklenmedik bir görevle hayatının en sıra dışı dönemine adım atar. Tanrı, Evan’dan Nuh’un gemisine benzer devasa bir tekne inşa etmesini ister. Görevi kabul eden Evan’ın davranışları giderek tuhaflaşırken ailesi de yaşananların ardındaki gerçeği anlamaya çalışır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/aman-tanrim-2-2007-izle.webp", backdrop = "", year = "2007", score = 5.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/aman-tanrim-2-2007-izle/", category = "Film"),
    Movie(id = 1000247, title = "Senden Nefret Etmemin 10 Sebebi", overview = "Bianca, üniversitede güzelliği ve popülerliğiyle dikkat çeken genç bir kızdır. Ancak aşk hayatının önündeki en büyük engel, erkeklere ilgi göstermeyen ablasıdır. Çünkü ailelerinin koyduğu katı bir kurala göre, iki kardeşten biri sevgili olmadan diğerinin de ilişki yaşamasına izin verilmez. Bu durum Bianca’nın hoşuna gitmese de kuralları değiştirebilmek için kendi yöntemini geliştirmeye karar verir. Ablasını bir şekilde aşka ikna edebilirse, kendi istediği ilişkiyi yaşamasının da önü açılacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/senden-nefret-etmemin-10-sebebi-1999-izle.webp", backdrop = "", year = "1999", score = 7.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/senden-nefret-etmemin-10-sebebi/", category = "Film"),
    Movie(id = 1000248, title = "Yüz Yüze", overview = "FBI ajanı Sean Archer, yıllardır oğlunun ölümünün acısını taşımakta ve cinayetten sorumlu tuttuğu azılı suçlu Castor Troy’un peşini bırakmamaktadır. Nihayet Troy’u yakaladığında, Los Angeles’ı yerle bir edebilecek bir bombanın hazırlandığını öğrenir. Bombanın yerini bilen tek kişi ise Castor’un kardeşi Pollux’tur ve sorguya rağmen konuşmaya yanaşmaz. Bunun üzerine Archer, gizli bir operasyonla Castor Troy’un yüzünü kendi yüzüne taşıtarak Pollux’un karşısına çıkmaya karar verir. Ancak plan beklenmedik bir şekilde tersine döner ve Castor’un bilinci geri geldiğinde, Archer’ın kimliğini ve hayatını ele geçirir. Artık iki düşman, birbirlerinin yüzünü ve yaşamını kullanarak amansız bir…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/yuz-yuze-1997-izle.webp", backdrop = "", year = "1997", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yuz-yuze-1997-izle/", category = "Film"),
    Movie(id = 1000249, title = "Zafer Yolları", overview = "Birinci Dünya Savaşı’nın acımasız atmosferinde General Broulard, General Mireau’ya Almanların kontrolündeki Ant Tepesi’ni ele geçirme emri verir. Mireau, askerlerinin hayatını büyük bir tehlikeye atacak bu saldırıyı kendi kariyerini ve konumunu güçlendirme fırsatı olarak görür. Ancak operasyon beklenildiği gibi ilerlemez ve birlik ağır bir başarısızlıkla karşı karşıya kalır. Bunun üzerine Mireau, kendi sorumluluğunu gizlemek için askerleri hedef alan acımasız kararlar almaya başlar. Savaşın yalnızca cephede değil, emirlerin ve güç hırsının gölgesinde de insan hayatını nasıl ezip geçtiğini gözler önüne seren film, askeri disiplin ve otorite kavramlarını sert bir şekilde sorgular.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/zafer-yollari-1957-izle.webp", backdrop = "", year = "1957", score = 8.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/zafer-yollari-1957-izle/", category = "Film"),
    Movie(id = 1000250, title = "Kuzeyli", overview = "Viking prensi Amleth, çocuk yaşta babasının amcası Fjölnir tarafından öldürülmesine tanık olur. Tahtı ele geçirmek isteyen Fjölnir, kral Aurvandil’i öldürerek krallığın kontrolünü ele geçirirken Amleth kaçarak hayatta kalmayı başarır. Kaçışı sırasında annesi Kraliçe Gudrun’un da amcasının eline geçtiğini gören genç prens, bir gün geri dönerek babasının intikamını alacağına, annesini kurtaracağına ve Fjölnir’i öldüreceğine yemin eder. Aradan yirmi yıl geçer ve Amleth, savaşçı olarak güçlenir. Bir kahinle karşılaşması, ona verdiği sözü hatırlatınca Amleth geçmişiyle yüzleşmek için yeniden yola çıkar. Artık tek amacı vardır: ailesinin hesabını kapatmak ve yıllar önce yarım bıraktığı…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/kuzeyli-2022-izle.webp", backdrop = "", year = "2022", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kuzeyli-2022-izle/", category = "Film"),
    Movie(id = 1000251, title = "Yanlış Missy", overview = "Tim Morris, sonunda hayallerindeki kadını bulduğuna inanan genç bir adamdır. Tanıştığı kadınla mesajlaşarak aralarındaki yakınlığı artıran Tim, bu ilişkiyi bir adım ileri taşımak için onu şirketinin düzenlediği özel bir geziye davet eder. Ancak davetin ardından büyük bir hata yaptığını fark eder. Uzun süredir mesajlaştığı kişinin sandığı kadın olmadığını anlayan Tim, daveti yanlışlıkla tamamen farklı bir Missy’ye göndermiştir. Artık geri dönüşü olmayan bir durumun içinde kalan Tim, tatil boyunca ortaya çıkacak sürprizlerle baş etmek zorunda kalacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/yanlis-missy-2020-izle.webp", backdrop = "", year = "2020", score = 5.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yanlis-missy/", category = "Film"),
    Movie(id = 1000252, title = "Çıplak Silah 3: Son Hakaret", overview = "Frank Drebin, yıllarını verdiği polislik kariyerini geride bırakıp emekli olduğunda nihayet kendisine ve ev hayatına zaman ayırmaya karar verir. Ütü yapmak, alışverişe çıkmak ve yemek hazırlamak gibi sıradan işlerle ilgilenmeye başlayan Drebin, çok geçmeden sakin yaşamın ona göre olmadığını fark eder. Eski mesai arkadaşları Ed Hocken ve Nordberg yardım istemek için kapısını çaldığında ise yeniden göreve dönmekten kendini alamaz. Tehlikeli bir bombacının yakalanması, çok daha büyük bir terör örgütünün varlığını ortaya çıkarır. Örgütün Oscar törenini hedef alan planı öğrenildiğinde Drebin yeniden harekete geçer ve dünyayı kurtarmak için eski günlerdeki gibi…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/ciplak-silah-3-son-hakaret-1994-izle.webp", backdrop = "", year = "1994", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ciplak-silah-3-son-hakaret/", category = "Film"),
    Movie(id = 1000253, title = "Çıplak Silah 2: Korkunun Kokusu", overview = "Teğmen Frank Drebin, hayatın en büyük gizemlerini çözmeye kendini adamış sıra dışı bir polistir. Ancak bu kez karşısında yalnızca cevaplanması zor sorular değil, çok daha ciddi bir tehdit vardır. Çevreyi hiçe sayan Quentin Hapsburg, kendi çıkarları uğruna tehlikeli bir plan hazırlamaktadır. Drebin, Hapsburg’un planlarını bozmak için harekete geçerken her zamanki gibi ciddi bir görevi birbirinden absürt olayların içine dönüştürür. Şimdi hem dünyayı büyük bir tehlikeden kurtarmalı hem de bunu kendine özgü yöntemleriyle başarmalıdır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-naked-gun-2-the-smell-of-fear-1991-izle.webp", backdrop = "", year = "1991", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ciplak-silah-2-korkunun-kokusu/", category = "Film"),
    Movie(id = 1000254, title = "Çıplak Silah: Polis Dosyalarından", overview = "Frank Drebin, yetenekleri konusunda fazlasıyla özgüvenli olmasına rağmen etrafındaki herkes için tam bir felaket olan sıra dışı bir polis memurudur. Los Angeles Polis Departmanı’nda görev yapan Drebin, Kraliçe II. Elizabeth’in ziyareti sırasında planlanan suikast girişimini engellemekle görevlendirilir. Dünyanın en önemli güvenlik operasyonlarından biri haline gelen bu görev, Drebin’in elinde kısa sürede tam bir kaosa dönüşür. Olayları çözmeye çalışırken istemeden ortalığı birbirine katan deneyimli dedektif, hem kraliçeyi korumak hem de suçluların planını bozmak zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-naked-gun-1988-izle.webp", backdrop = "", year = "1988", score = 7.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ciplak-silah-polis-dosyalarindan/", category = "Film"),
    Movie(id = 1000255, title = "Gerçeğe Çağrı", overview = "Douglas Quaid, sevdiği eşiyle birlikte sıradan bir hayat süren ve monoton işinden giderek bunalan bir işçidir. Günlük yaşamının sıkıcılığından kurtulmak isteyen Douglas, hiç yaşamadığı maceraları gerçekmiş gibi deneyimleyebilmek için Rekall adlı şirkete başvurur. Ancak işlem sırasında yaşanan beklenmedik bir hata, onun zihnine aranan bir ajanın anılarının yüklenmesine neden olur. Bir anda kendisini tehlikeli bir kovalamacanın içinde bulan Douglas, Cohaagen’ın yönettiği güçlerin hedefi haline gelir. Hayatta kalabilmek için bir direnişçiyle iş birliği yapan Douglas, yeraltındaki direnişin liderine ulaşarak Cohaagen’ın planlarını durdurmaya çalışır. Fakat gerçek anılarla zihnine yerleştirilen sahte görüntüler birbirine karıştıkça…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/gercege-cagri-2012-izle.webp", backdrop = "", year = "2012", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/gercege-cagri-2012-izle-1/", category = "Film"),
    Movie(id = 1000256, title = "Kurt Adam", overview = "Lawrence Talbot, çocuk yaşta annesini kaybettikten sonra büyüdüğü köyü geride bırakıp ailesinden uzak bir hayat sürmeye başlar. Yıllar sonra kardeşinin nişanlısından gelen haber, onu istemeden de olsa geçmişiyle yeniden yüzleşmeye zorlar. Kardeşinin kaybolduğunu öğrenen Lawrence, ailesinin evine döner ve babasıyla yeniden bir araya gelir. İkili, kayıp kardeşin izini sürmeye başladığında köyde yaşanan korkunç cinayetlerin ardındaki sırrı da keşfetmeye çalışır. Çünkü geceleri ortaya çıkan gizemli ve vahşi bir yaratık, köylüleri dehşete düşürmektedir. Olayı araştıran İskoç müfettiş Aberline ise yaratığın izini sürerken Lawrence’ı da giderek daha karanlık bir gerçeğin içine çeker.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/kurt-adam-2010-izle.webp", backdrop = "", year = "2010", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kurt-adam-2010-izle/", category = "Film"),
    Movie(id = 1000257, title = "Uluslararası", overview = "Interpol ajanı Louis Salinger, dünya çapında faaliyet gösteren güçlü bir bankanın yasa dışı işlerini ortaya çıkarmak için harekete geçer. Manhattan Savcı Yardımcısı Eleanor Whitman ile birlikte yürüttüğü soruşturma, kısa sürede New York’tan Berlin ve Milano’ya, oradan da İstanbul’a uzanan uluslararası bir takibe dönüşür. Salinger, araştırdıkça karşısındaki yapının sıradan bir finans kuruluşundan çok daha fazlası olduğunu fark eder. Bankanın küresel ölçekte terör ve savaş faaliyetlerine kaynak sağladığından şüphelenen ajan, gerçeğe yaklaştıkça kendi hayatını da büyük bir tehlikenin içine atar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/uluslararasi-2009-izle.webp", backdrop = "", year = "2009", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/uluslararasi-2009-izle/", category = "Film"),
    Movie(id = 1000258, title = "Burada Olan Burada Kalır", overview = "Jack Fuller ve Joy McNally, Las Vegas’ta geçirecekleri çılgın bir hafta sonunun hayatlarını tamamen değiştireceğinden habersizdir. Birbirlerini tanımayan bu iki New Yorklu, gecenin ilerleyen saatlerinde aldıkları bir kararla Las Vegas usulü bir evlilik yapar. Ertesi gün ise bu evliliğin yalnızca bir tatil macerası olmadığını fark ederler. Büyük bir ödülün peşine düşen Jack ve Joy, altı ay boyunca evli kalmaları şartıyla ciddi bir para kazanma fırsatı elde eder. Ancak birbirlerinden hiç hoşlanmayan bu iki inatçı insan için aynı hayatı paylaşmak hiç kolay olmayacaktır. Sürekli çatışan Jack ve Joy, zamanla aralarındaki öfkenin…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/burada-olan-burada-kalir-2008-izle.webp", backdrop = "", year = "2008", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/burada-olan-burada-kalir/", category = "Film"),
    Movie(id = 1000259, title = "Tavşan Kız", overview = "Shelly, Playboy köşkünde geçirdiği rahat ve sorunsuz günlerin ardından bir anda kendisini evsiz kalmış halde bulur. Gidecek hiçbir yeri olmayan genç kadın, sonunda Zeta Alpha Zeta adlı kız öğrenci birliğinin kapısını çalar. Ancak grubun da kendi sorunları vardır. Kızlar, yaşadıkları evi kaybetmemek için gerekli sözleşmeyi imzalamak zorundadır ve bu konuda Shelly’nin yardımına ihtiyaç duyarlar. Erkekler ve makyaj konusunda oldukça deneyimli olan Shelly, sosyal açıdan çekingen kızlara özgüven kazandırmaya çalışırken, onlar da Shelly’nin hayatına farklı bir yön vermeye başlar. Zamanla birbirlerinden öğrendikleri sayesinde kızlar başkalarını taklit etmek yerine kendi kimliklerini keşfetmeye…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/tavsan-kiz-2008-izle.webp", backdrop = "", year = "2008", score = 5.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/tavsan-kiz-2008-izle/", category = "Film"),
    Movie(id = 1000260, title = "Ölümden Daha Soğuk", overview = "Noel arifesinde Delaware’deki evine gitmek üzere yola çıkan genç bir üniversite öğrencisi, yolculuğunu çok yakından tanımadığı bir erkek arkadaşıyla paylaşmak zorunda kalır. Zamandan kazanmak için ana yoldan ayrılan ikili, kısa süre sonra şiddetli bir kar fırtınasının ortasında mahsur kalır. Araçları hareket edemez hale gelirken telefonlarının da çekmemesi, yardım istemelerini imkânsızlaştırır. Soğukta beklemekten başka seçenekleri kalmayan gençler, saatler geçtikçe birbirlerini daha yakından tanımaya başlar. Ancak mahsur kaldıkları yerin geçmişinde karanlık ve açıklanamayan olayların yaşandığını fark ettiklerinde, asıl tehlikenin fırtına olmadığını anlarlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/wind-chill-2007-izle.webp", backdrop = "", year = "2007", score = 5.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/olumden-daha-soguk/", category = "Film"),
    Movie(id = 1000261, title = "Şıpsevdi", overview = "Eddie, kırk yaşına kadar evlilikten uzak durmuş yalnız bir adamdır. Eski nişanlısını kaybettikten sonra karşısına çıkan Lila ise ona hayatının aşkını bulduğunu düşündürür. İyi kalpli ve yardımsever görünen Lila, Eddie’nin ailesi ve dostlarının da teşvikiyle yaptığı evlilik teklifini kabul eder. İkili, tanışmalarından sadece altı hafta sonra evlenir. Fakat Eddie kısa süre içinde yeni eşinin hiç de hayal ettiği gibi biri olmadığını keşfeder. Lila’nın olgunlaşmamış tavırları, tuhaf alışkanlıkları ve sıra dışı yaşam biçimi evliliği zorlaştırırken, kadının çalışmadan yaşamasını sağlayan büyük bir servete sahip olduğu da ortaya çıkar. Cabo’daki balayında Miranda ile…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/sipsevdi-2007-izle.webp", backdrop = "", year = "2007", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sipsevdi-2007-izle/", category = "Film"),
    Movie(id = 1000262, title = "Yapımcılar", overview = "Max Bialystock’un yapımcılığını üstlendiği “Funny Boy”, Hamlet’in müzikal uyarlaması olarak Broadway sahnesine çıkar ancak ilk gösterimin ardından beklenmedik şekilde kapanır. Bu başarısızlığın ardından Max’in muhasebecisi Leo Bloom, ikisinin de büyük miktarda para kazanabileceği bir plan geliştirir. Leo’nun fikrine göre yeni bir müzikalin maliyetinden çok daha fazla yatırım toplanacak, ardından yapım bilerek başarısızlığa uğratılarak elde edilen para ortadan kaybedilecektir. Bunun için seçtikleri eser ise “Hitler’in Baharı” adlı tuhaf bir müzikaldir. Fakat hesapta olmayan gelişmeler, basit bir dolandırıcılık olarak başlayan planın giderek içinden çıkılmaz bir maceraya dönüşmesine yol açar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-producers-2005-izle.webp", backdrop = "", year = "2005", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yapimcilar-2005-izle/", category = "Film"),
    Movie(id = 1000263, title = "Panama Terzisi", overview = "Panama’ya sürgün edilen İngiliz ajan Andy Osnard, görevine geri dönebilmek için burada kendine yeni bir yol aramaya başlar. Bölgedeki nüfuzlu kişiler hakkında bilgi toplamak isteyen Andy’nin dikkatini, Panama’nın zenginlerine hizmet veren başarılı terzi Harry Pendel çeker. Ancak Harry’nin geçmişi göründüğü kadar temiz değildir; eski bir dolandırıcı olan Harry, gerçek kimliğini gizlemek için Andy’ye birbirinden ilginç hikâyeler anlatmaya başlar. Başlangıçta yalnızca uydurma dedikodulardan ibaret olan bu anlatılar giderek büyür ve ikilinin kontrol edemeyeceği sonuçlara yol açar. Harry’nin kurguladığı hikâyeler, zamanla Panama’nın siyasi geleceğini etkileyebilecek tehlikeli bir oyunun fitilini ateşler.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/panama-terzisi-2001-izle.webp", backdrop = "", year = "2001", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/panama-terzisi/", category = "Film"),
    Movie(id = 1000264, title = "Söz", overview = "Nevada polis teşkilatından emekli olan Jerry Black, sakin bir hayat sürmeye hazırlanırken genç bir kızın cinayetiyle karşı karşıya kalır. Cinayetin çözüldüğünü ve suçlunun yakalandığını söyleyen polisin açıklamalarına ikna olmayan Jerry, kızın annesine katili bulacağına dair söz verir. Gerçeğin peşinden gitmek için olayın yaşandığı bölgeye yerleşen Jerry, kendi başına soruşturma yürütmeye başlar. Araştırmaları onu yeni şüphelilere ve olası kurbanlara götürürken, bu süreçte bir annenin hayatına da giderek daha fazla dahil olur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-pledge-2001-izle.webp", backdrop = "", year = "2001", score = 6.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/soz-2001-izle/", category = "Film"),
    Movie(id = 1000265, title = "Fanatik", overview = "Bobby Rayburn, milyonlarca beyzbol hayranının gözünde yalnızca başarılı bir sporcu değil, adeta bir efsanedir. Onun maçlarını izlemek, posterlerini taşımak ve attığı her adımı takip etmek fanları için hayatlarının önemli bir parçasıdır. Bu hayranlardan biri olan Gil Renard ise Bobby’ye duyduğu bağlılığı giderek tehlikeli bir takıntıya dönüştürür. Bobby’nin kariyerinde yaşadığı düşüş, Gil’in kendi hayatındaki sorunlarla birleşince işler kontrolden çıkmaya başlar. Yıldız oyuncunun eski günlerine dönme çabası, fanatik hayranının sınırları aşmasıyla birlikte karanlık ve gerilim dolu bir mücadeleye dönüşür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-fan-1996-izle.webp", backdrop = "", year = "1996", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/fanatik-1996-izle/", category = "Film"),
    Movie(id = 1000266, title = "Navaron’un Topları", overview = "İkinci Dünya Savaşı’nın en zorlu görevlerinden biri için seçilen bir komando ekibi, Almanların kontrolündeki Ege adalarından birine gönderilir. Adadaki stratejik kanal, güçlü Alman topları tarafından korunmaktadır ve İngiliz kuvvetlerinin bölgeye ilerleyebilmesi için bu savunma hattının etkisiz hale getirilmesi gerekir. Komandolar, düşman topraklarında hem zamanla hem de Alman askerleriyle mücadele ederek topları imha etmeye çalışır. Alistair MacLean’in romanından beyaz perdeye uyarlanan film, sürükleyici savaş atmosferi, güçlü oyuncu kadrosu ve etkileyici görsel efektleriyle klasikleşen yapımlar arasında yer alıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/the-guns-of-navarone-1961-izle.webp", backdrop = "", year = "1961", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/navaronun-toplari/", category = "Film"),
    Movie(id = 1000267, title = "Kwai Köprüsü", overview = "Japonya’nın savaş esirleri üzerindeki baskısının sürdüğü günlerde, Albay Nicholson’ın komutasındaki İngiliz askerlerine zorlu bir görev verilir: Kwai Nehri’ni aşacak bir köprü inşa etmek. Köprünün tamamlanması, Japon ordusunun bölgedeki lojistik faaliyetlerini önemli ölçüde kolaylaştıracaktır. Nicholson başlangıçta bu emre karşı çıksa da kısa süre içinde köprünün yapımını askerlerinin disiplinini ve özgüvenini yeniden kazanabilecekleri bir mücadeleye dönüştürür. Fakat ortaya çıkan sonuç, onun düşündüğünden çok daha karmaşık bir tablo yaratacaktır. David Lean’in yönettiği Kwai Köprüsü, savaşın insan psikolojisi üzerindeki etkisini güçlü karakterler üzerinden anlatıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/kwai-koprusu-1957-izle.webp", backdrop = "", year = "1957", score = 8.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kwai-koprusu/", category = "Film"),
    Movie(id = 1000268, title = "Rocketman", overview = "Elton John’un müzik dünyasında sıradan bir yetenekten uluslararası bir süperstara dönüşme hikâyesi, çocukluk yıllarından başlayan renkli ve inişli çıkışlı bir yolculukla anlatılıyor. Royal Müzik Akademisi’nde dikkat çeken genç Elton, kısa sürede kendine özgü tarzını bulurken söz yazarı Bernie Taupin ile tanışması kariyerinde önemli bir dönüm noktası olur. İkilinin yıllar boyunca süren yaratıcı ortaklığı, unutulmaz şarkıların ortaya çıkmasını sağlar. Şöhret arttıkça Elton’un özel hayatındaki mücadeleler, ilişkileri ve yaşadığı zorluklar da giderek daha görünür hale gelir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/rocketman-2019-izle.webp", backdrop = "", year = "2019", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/rocketman-2019-izle/", category = "Film"),
    Movie(id = 1000269, title = "Gece Hayvanları", overview = "Hayatını geride bıraktığını düşündüğü geçmişten gelen bir roman taslağı, Susan Morrow’un tüm düzenini altüst eder. Yıllar önce terk ettiği eski eşi Edward, ilk romanının yayımlanmamış metnini Susan’a gönderir ve onun fikrini merak ettiğini belirtir. Susan, Tony adlı bir matematik profesörünün ailesiyle çıktığı yolculuk sırasında yaşadığı dehşet dolu olayları anlatan kitaptan kendini alamaz. Sayfalar ilerledikçe romandaki karakterlerin yaşadığı acılar Susan’ın kendi geçmişini hatırlamasına yol açar. Edward’ın hikâyesinin ardında ne olduğunu anlamaya çalışırken, yıllar önce verdiği kararların sonuçlarıyla yeniden yüzleşmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/gece-hayvanlari-2016-izle.webp", backdrop = "", year = "2016", score = 7.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/gece-hayvanlari/", category = "Film"),
    Movie(id = 1000270, title = "Küçük Deniz Kızı Ponyo", overview = "Denizin derinliklerinde yaşayan küçük Japon balığı Ponyo’nun en büyük dileği insan olmaktır. Bir gün yaşadığı dünyadan uzaklaşıp yüzeye çıkan Ponyo, burada beş yaşındaki Sosuke ile tanışır. İkili arasında kısa sürede güçlü bir arkadaşlık oluşur ve bu karşılaşma Ponyo’nun hayatını tamamen değiştirir. İnsan dünyasına duyduğu merak giderek büyüyen Ponyo, hayalini gerçekleştirmek için büyük bir maceraya atılır. Ancak onun bu isteği yalnızca kendi yaşamını değil, denizin ve doğanın dengesini de etkileyebilecek olayların başlamasına neden olur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/kucuk-deniz-kizi-ponyo-2008-izle.webp", backdrop = "", year = "2008", score = 7.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kucuk-deniz-kizi-ponyo/", category = "Film"),
    Movie(id = 1000271, title = "Tetikçi", overview = "Yetenekli bir keskin nişancı olan Bob Lee Swagger, geçmişte yaşadığı bir operasyonun ardından ordudan ayrılmış ve kendisini toplumdan uzak bir hayata çekmiştir. Fakat eski görev arkadaşlarından gelen teklif, onu son bir operasyon için yeniden harekete geçirir. Swagger’dan, Başkan’a yönelik bir suikast planını engellemesi istenir. Görevin ayrıntılarını araştırdıkça kendisine anlatılanların gerçeği yansıtmadığını fark eden Swagger, kısa süre içinde tehlikeli bir komplonun içine düştüğünü anlar. Artık peşindeki güçlerden kaçarken olayın arkasındaki kişileri bulmak ve kurulan oyunu bozmak zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/tetikci-2007-izle.webp", backdrop = "", year = "2007", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/tetikci-2007-izle-1/", category = "Film"),
    Movie(id = 1000272, title = "Hellboy", overview = "II. Dünya Savaşı’nın son günlerinde Naziler, savaşın gidişatını değiştirmek amacıyla karanlık bir ritüel gerçekleştirir. Ancak planları beklenmedik bir şekilde sonuçlanır ve başka bir dünyadan gelen küçük bir iblis, Hellboy, Dünya’ya getirilir. Müttefiklerin baskınıyla ritüel yarıda kalsa da Hellboy artık bu dünyanın bir parçasıdır. Onu, kara büyünün ardındaki isimlerden biri olan Rasputin’den kurtulan Profesör Broom yetiştirir. Yıllar içinde büyüyen Hellboy, kökenlerinin aksine kötülüğü seçmek yerine insanlığın yanında yer alır. Özel yeteneklere sahip ekibiyle birlikte doğaüstü tehditlere karşı mücadele eden Hellboy, bir gün dünyaya gelişinin ardındaki gerçek amacı keşfetmek zorunda kalacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/hellboy-2004-izle.webp", backdrop = "", year = "2004", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/hellboy-2004-izle/", category = "Film"),
    Movie(id = 1000273, title = "Tetikçinin Gecesi", overview = "Vincent, Los Angeles’ta gerçekleştirmesi gereken bir dizi iş için gece boyunca kullanacağı bir taksiye ihtiyaç duyan profesyonel bir kiralık katildir. Taksi şoförü Max, karşısındaki adamın gerçek kimliğinden habersiz bir şekilde Vincent’ın teklifini kabul eder ve kendisini beklenmedik bir gecenin içinde bulur. Başlangıçta yolculuğun sıradan bir iş olduğunu düşünen Max, Vincent’ın peş peşe gerçekleştirdiği cinayetleri görünce dehşete kapılır. Ancak artık geri dönmesi mümkün değildir; çünkü Vincent silahıyla onu kontrol altında tutmaktadır. Gece ilerledikçe Max, Vincent’ın hedeflerinden birinin kendi hayatında özel bir yere sahip olduğunu öğrenir ve olaylar onun için kişisel bir…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/tetikcinin-gecesi-2004-izle.webp", backdrop = "", year = "2004", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/tetikcinin-gecesi/", category = "Film"),
    Movie(id = 1000274, title = "Bizim Dansımız", overview = "17 yaşındaki Sara, profesyonel bir balerin olma hayali kurarken annesini geçirdiği trafik kazasında kaybeder. Bu acı olayın ardından dans hayallerini geride bırakmak zorunda kalan genç kız, Chicago’da yaşayan babasının yanına taşınır. Yeni hayatına alışmaya çalışırken dans tutkusundan tamamen kopamayan Sara, kendisini kulüplerde dans ederek ifade etmeye devam eder. Burada dansa onun kadar bağlı olan Derek ile tanışır ve kısa sürede Derek ile kız kardeşi Chenille’in yakın çevresine girer. Sara ve Derek arasındaki ilişki derinleştikçe ailelerinin ve çevrelerinin baskısıyla karşılaşırlar. Buna rağmen iki genç, hem hayallerini gerçekleştirmek hem de birbirlerini kaybetmemek…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/save-the-last-dance-2001-izle.webp", backdrop = "", year = "2001", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/bizim-dansimiz/", category = "Film"),
    Movie(id = 1000275, title = "28 Gün", overview = "Gwen Cummings, New York’ta başarılı bir yazar olmasının yanı sıra eğlenceyi hayatının merkezine koymuş özgür ruhlu bir kadındır. Erkek arkadaşı Jasper ile birlikte geceleri kulüplerde ve barlarda geçirirken sorumluluklardan uzak bir yaşam sürer. Ancak kız kardeşinin düğününde yaşanan talihsiz bir olay, Gwen’in hayatını bir anda değiştirir ve mahkeme tarafından 28 günlük rehabilitasyon programına gönderilir. Alıştığı özgür yaşamın aksine burada sıkı kurallar ve hiç bilmediği bir düzenle karşılaşır. Başlangıçta çevresindeki insanlara ve tedavi sürecine direnç gösteren Gwen, danışmanı Cornell’in desteğiyle kendi hayatına ve davranışlarına farklı bir gözle bakmaya başlar. Zamanla yeni…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/28-days-2000-izle.webp", backdrop = "", year = "2000", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/28-gun-2000-izle/", category = "Film"),
    Movie(id = 1000276, title = "Köstebek", overview = "FBI ajanı Joe Pistone, mafya hakkında bilgi toplamak amacıyla uzun süreli ve son derece riskli bir gizli göreve gönderilir. Donnie Brasco adını kullanarak kendisini deneyimli bir mücevher hırsızı gibi gösteren Pistone, kısa sürede suç dünyasının güvenini kazanır. Ancak operasyon ilerledikçe mafya üyeleriyle kurduğu ilişkiler beklenmedik bir boyuta ulaşır. Pistone, yıllarca sürdürdüğü sahte hayatın etkisiyle gerçek kimliğiyle yarattığı karakter arasında sıkışmaya başlar. Görevi uğruna ailesinden ve normal yaşamından uzaklaşan ajan için artık en büyük mücadele, mafyanın içinden sağ çıkmak kadar kendisi olarak kalabilmektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/kostebek-1997-izle.webp", backdrop = "", year = "1997", score = 7.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kostebek-1997-izle/", category = "Film"),
    Movie(id = 1000277, title = "Vuruş Mesafesi", overview = "Babası gibi polislik yapan Tom Hardy, babasının görev sırasında öldürülmesinin ardından bu olayın peşini bırakmaz. Yaptığı araştırmalar ve ortaya attığı iddialar amirleri tarafından fazla ileri görülünce nehir devriyesine atanır ve yeni görevinde kadın bir polisle ortak çalışmaya başlar. Başlangıçta hem görevinden hem de ortağından memnun olmayan Tom, zamanla yeni düzenine alışır. Ancak babasının ölümünün ardındaki gerçeği araştırmaya gizlice devam eder. Bu durum, katilin kimliğinin ortaya çıkmasından korkmasına neden olur ve Tom’u susturmak için harekete geçer. Fakat Tom, karşısındaki kişinin ne kadar tehlikeli olduğunu bilse de gerçeğe ulaşmaktan vazgeçmeye niyetli değildir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/striking-distance-1993-izle.webp", backdrop = "", year = "1993", score = 5.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/vurus-mesafesi/", category = "Film"),
    Movie(id = 1000278, title = "Çelik Manolyalar", overview = "1980’lerin Louisiana’sında küçük bir güzellik salonu, hayatın farklı sınavlarından geçen bir grup kadının buluşma noktasıdır. Kimi eşini kaybetmiş, kimi evliliğinde sorunlar yaşayan, kimi ise hayatında istediği düzeni bir türlü kuramayan bu kadınlar, zamanla birbirlerinin en yakın dostu olur. Salonun samimi ortamında dertlerini paylaşırken bolca sohbet eder, çevrelerinde olup bitenleri konuşmaktan da geri durmazlar. Gülüşlerin, gözyaşlarının ve bitmek bilmeyen dedikoduların arasında, dış dünyada bulamadıkları dayanışmayı birbirlerinde keşfederler.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/steel-magnolias-1989-izle.webp", backdrop = "", year = "1989", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/celik-manolyalar/", category = "Film"),
    Movie(id = 1000279, title = "Yıldız Adam", overview = "Voyager 1’in gönderdiği mesaja karşılık Dünya’ya barış amacıyla gelen bir uzaylının gemisi beklenmedik şekilde düşer. Yakalanacağını anlayan uzaylı pilot, hayatta kalabilmek için bir insanın kimliğine bürünür ve Jenny’nin hayatına girer. Genç kadının hayatını kaybeden eşinin yerine geçen bu gizemli yabancı, başlangıçta güven kazanmakta zorlansa da zamanla onun iyi niyetini gösterir. İkili, uzaylı dostlarının kendisini almak üzere geleceği Nevada çölüne ulaşmak için tehlikeli bir yolculuğa çıkar. Ancak peşlerindeki yetkililer, bu sıra dışı varlığı ele geçirerek üzerinde deneyler yapmak istemektedir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/starman-1984-izle.webp", backdrop = "", year = "1984", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yildiz-adam/", category = "Film"),
    Movie(id = 1000280, title = "Şeytan Çocuk", overview = "Baturay Özdemir, üç yıldır sahnelerde yer alan “Şeytan Çocuk” gösterisinde modern şehir yaşamının getirdiği değişimleri mizahi bir dille ele alıyor. 30’lu yaşlarla birlikte farklılaşan hayat düzeni, kuşaklar arasındaki anlaşmazlıklar ve çocuk sahibi olma düşüncesinin yarattığı endişeler, Özdemir’in kişisel deneyimleri ve gözlemleriyle şekilleniyor. Kendi çocukluğundaki “şeytan çocuk” döneminden yola çıkan komedyen, günümüz çocuklarının karşılaştığı baskıları ve nesiller arasındaki giderek büyüyen farkı kendine özgü anlatımıyla sahneye taşıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/seytan-cocuk-2026-izle.webp", backdrop = "", year = "2026", score = 6.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/seytan-cocuk-2026-izle/", category = "Film"),
    Movie(id = 1000281, title = "I Care a Lot", overview = "Marla Grayson, mahkeme tarafından atanmış profesyonel bir vasi olarak yalnız yaşayan yaşlı insanların servetlerini yönetmektedir. Ancak yaptığı iş, göründüğü kadar masum değildir. Yasal boşlukları ustaca kullanarak koruması altındaki kişilerin varlıklarını ele geçiren Marla, ortağı ve sevgilisi Fran ile birlikte kusursuz işleyen bir düzen kurmuştur. Son hedefleri Jennifer Peterson olduğunda ise planları beklenmedik şekilde bozulur. Jennifer’ın arkasındaki gizem ve güçlü bağlantılar ortaya çıktıkça Marla, karşısında şimdiye kadar karşılaştığı en tehlikeli rakibin olduğunu fark eder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/i-care-a-lot-2020-izle.webp", backdrop = "", year = "2020", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/i-care-a-lot/", category = "Film"),
    Movie(id = 1000282, title = "Gitmesine İzin Ver", overview = "Oğullarını kaybetmenin acısıyla yaşayan emekli şerif George Blackledge ve eşi Margaret, geride kalan tek aile bağları olan torunlarını korumaya karar verir. Torunlarının Dakota’da tehlikeli Weboy ailesinin yanında kaldığını öğrenen çift, Montana’daki çiftliklerini bırakarak onu geri almak için yola çıkar. Ancak Blanche Weboy’un liderliğindeki aile, çocuğu teslim etmeye hiç niyetli değildir. George ve Margaret, torunlarını kurtarmak için geçmişte sahip oldukları tüm güç ve cesareti yeniden ortaya koymak zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/gitmesine-izin-ver-2020-izle.webp", backdrop = "", year = "2020", score = 6.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/gitmesine-izin-ver/", category = "Film"),
    Movie(id = 1000283, title = "Havari", overview = "1905 yılında Londra’da yaşayan Thomas Richardson, uzun süredir uzak kaldığı ailesinin yanına dönmek zorunda kalır. Kız kardeşinin gizemli bir tarikat tarafından kaçırıldığını öğrenen Thomas, onu kurtarmak için tarikatın yaşadığı izole adaya gider. Liderleri Peygamber Malcolm’un istediği fidyeyi ödemek yerine topluluğun içine gizlice sızan genç adam, adadaki yaşamın göründüğü kadar masum olmadığını kısa sürede fark eder. Kız kardeşine ulaşmaya çalışırken keşfettiği sır, Thomas’ı korkunç bir gerçeğin tam ortasına sürükler.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/apostle-2018-izle.webp", backdrop = "", year = "2018", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/havari-2018-izle/", category = "Film"),
    Movie(id = 1000284, title = "Overlord Operasyonu", overview = "İkinci Dünya Savaşı’nın en kritik günlerinden biri yaklaşırken, Müttefik kuvvetlerinin Normandiya çıkarmasına saatler kalmıştır. Amerikalı bir grup paraşütçü, düşman hatlarının gerisine indirilerek işgalin başarısı için hayati önem taşıyan bir görevi yerine getirmekle görevlendirilir. Ancak Nazi kontrolündeki bir köye ulaştıklarında, burada yürütülen operasyonun göründüğünden çok daha karanlık olduğunu keşfederler. Askerler artık yalnızca düşman birlikleriyle değil, açıklaması zor korkunç bir tehditle de mücadele etmek zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/overlord-operasyonu-2018-izle.webp", backdrop = "", year = "2018", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/overlord-operasyonu/", category = "Film"),
    Movie(id = 1000285, title = "Yeniden Başla", overview = "Eşini trajik bir trafik kazasında kaybeden başarılı bankacı Davis Mitchell, yaşadığı acının ardından hayatına devam etmekte zorlanır. Kayınpederi Phil’in tüm çabalarına rağmen giderek içine kapanan Davis, bir gün hastanede parasını yutan bir otomat yüzünden şirkete alışılmadık bir şikâyet mektubu gönderir. Müşteri temsilcisi Karen Mareno’nun dikkatini çeken bu mektup, ikisi arasında beklenmedik bir yazışmanın başlamasına neden olur. Kendi yaralarıyla mücadele eden Karen ve oğlu Chris, Davis’in hayatını yeniden kurabilmesi için geçmişini söküp atmasına yardımcı olur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/yeniden-basla-2015-izle.webp", backdrop = "", year = "2015", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/yeniden-basla-2015-izle/", category = "Film"),
    Movie(id = 1000286, title = "Sonsuzluk Projesi", overview = "Todd, yedinci yaş gününe ait eski bir videoyu izlerken görüntünün arka planında bugünkü halini fark eder. Gördüğü şey karşısında şaşkına dönen Todd, durumu arkadaşlarına anlatır ve hep birlikte bu gizemin peşine düşer. Garajda yaptıkları araştırma sırasında gizli bir projeye ait planları keşfederler. Planların bir zaman makinesine ait olduğunu anlayınca makineyi kendileri yapmaya karar verirler. Ancak geçmiş ve gelecek arasında oynadıkları bu oyun, kısa sürede beklemedikleri sonuçlar doğurur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/sonsuzluk-projesi-2015-izle.webp", backdrop = "", year = "2015", score = 6.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/sonsuzluk-projesi/", category = "Film"),
    Movie(id = 1000287, title = "Uçuş", overview = "Whip, tehlikeli bir uçuş sırasında uçağın kontrolünü kaybetmesine rağmen soğukkanlılığını korur ve neredeyse imkânsız görünen bir iniş gerçekleştirir. Yaşanan felaketten çok sayıda insan sağ kurtulurken Whip kısa sürede bir kahraman ilan edilir. Fakat kazanın nedenlerini araştıran ekip, pilotun uçuş öncesinde alkol aldığını tespit eder. Şimdi Whip için asıl mücadele başlamıştır. Kurtardığı hayatlar onun lehine konuşsa da hakkındaki suçlamalar giderek ağırlaşır ve başarılı pilot, mesleğini, itibarını ve özgürlüğünü tehdit eden zorlu bir soruşturmanın ortasında kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/ucus-2012-izle.webp", backdrop = "", year = "2012", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/ucus-2012-izle/", category = "Film"),
    Movie(id = 1000288, title = "Bağlanmak Yok", overview = "Emma ve Adam yıllar önce bir yaz kampında tanışmış, ancak aralarında hiçbir şey yaşanmadan yollarını ayırmıştır. Aradan geçen zamanın ardından yeniden karşılaşan ikili, beklemedikleri bir yakınlaşmanın içinde bulur kendini. İkisi de ilişki yaşamaktan kaçınmaktadır ve bu yüzden duygulara yer olmayan bir anlaşma yapmaya karar verirler: Sadece birlikte olacak, birbirlerinden hiçbir şey beklemeyeceklerdir. Ancak kalplerin yapılan anlaşmalara pek aldırmaması, bu kusursuz görünen planı kısa sürede karmaşık bir hale getirir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/baglanmak-yok-2011-izle.webp", backdrop = "", year = "2011", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/baglanmak-yok/", category = "Film"),
    Movie(id = 1000289, title = "Ateşli Gençlik", overview = "Shawn ve Nick, futbol sezonunun ardından yazı bir başka futbol kampında geçirmek düşüncesinden bile rahatsızdır. Nick, bu kaderden kurtulmak için yaptığı kurnazlıkla ikisinin kamp yerini değiştirmeyi başarır. Fakat kendilerini okulun amigo kızlarının kampında bulduklarında işler beklenmedik bir hal alır. İki futbolcu, hem kimliklerini gizlemek hem de bu sıra dışı yaz tatilinin tadını çıkarmak zorunda kalacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/atesli-genclik-2009-izle.webp", backdrop = "", year = "2009", score = 6.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/atesli-genclik/", category = "Film"),
    Movie(id = 1000290, title = "Rachel Evleniyor", overview = "Uyuşturucu bağımlılığı nedeniyle bir rehabilitasyon merkezinde tedavi gören Kym, kız kardeşi Rachel’ın düğünü için ailesinin yanına döner. Ancak birkaç gün sürecek bu mutlu kutlama, geçmişte yaşanan acıların ve aile içinde yıllardır biriken sorunların yeniden gündeme gelmesine neden olur. Düğün hazırlıkları devam ederken herkes kendi yaralarıyla yüzleşmek zorunda kalır ve Kym’in dönüşü, ailenin sakladığı gerçekleri gün yüzüne çıkarır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/rachel-getting-married-2008-izle.webp", backdrop = "", year = "2008", score = 6.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/rachel-evleniyor/", category = "Film"),
    Movie(id = 1000291, title = "Marie Antoinette", overview = "Marie Antoinette, henüz on beş yaşındayken Fransa tahtının varisi XVI. Louis ile evlenerek kendisini hiç tanımadığı bir dünyanın içinde bulur. Genç yaşta kraliçe olan Marie, Versailles Sarayı’nın ihtişamı, entrikaları ve yalnızlığı arasında giderek kendi kimliğini aramaya başlar. Tarihin çoğu zaman tek bir yüzünü gösterdiği bu genç kadın, filmde ne bir kötü karakter ne de kusursuz bir kraliçe olarak ele alınır. Hikâye, onun gençliğinden Versailles’ın çöküşüne uzanan çalkantılı yaşamını farklı ve renkli bir bakışla anlatır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/marie-antoinette-2006-izle.webp", backdrop = "", year = "2006", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/marie-antoinette/", category = "Film"),
    Movie(id = 1000292, title = "Dogtown’ın Lordları", overview = "1970’li yılların özgürlükçü ruhu, gençleri sınırları zorlamaya ve kendi yollarını çizmeye teşvik eder. Tam da böyle bir dönemde ortaya çıkan üç genç, kaykay dünyasında yeni bir dönemin kapılarını aralar. Cesaretleri, tarzları ve sıra dışı yetenekleriyle bu sporun gelişimini kökten değiştirerek kaykay tarihine damga vururlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/dogtownin-lordlari-2005-izle.webp", backdrop = "", year = "2005", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/dogtownin-lordlari/", category = "Film"),
    Movie(id = 1000293, title = "50 İlk Öpücük", overview = "Hawaii’de yaşayan doktor Henry Roth, hayatını ciddi ilişkilerden uzak, günübirlik aşklar yaşayarak geçirmektedir. Ancak Lucy Whitmore ile karşılaşması, onun bütün alışkanlıklarını geride bırakmasına neden olur. İkili arasında güzel bir yakınlaşma başlarken Lucy’nin ertesi gün Henry’yi hiç tanımaması büyük bir şaşkınlık yaratır. Henry kısa süre içinde Lucy’nin her gece yaşadığı günün anılarını kaybettiğini öğrenir. Buna rağmen ondan vazgeçmeyen Henry, her sabah Lucy’nin karşısına yeniden çıkıp kalbini bir kez daha kazanmanın yollarını aramaya başlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/50-ilk-opucuk-2004-izle.webp", backdrop = "", year = "2004", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/50-ilk-opucuk-izle/", category = "Film"),
    Movie(id = 1000294, title = "Radyo", overview = "Harold Jones, hayatını futbol takımına adamış, işinden başka pek az şeyle ilgilenen disiplinli bir koçtur. Küçük bir kasabada yaşayan James Robert Kennedy ise zihinsel gelişimindeki farklılıklar nedeniyle çevresindeki insanlar tarafından çoğu zaman küçümsenen ve alay konusu edilen yalnız bir adamdır. Herkesin ona “Radio” diye seslenmesiyle tanınan James’in hayatı, Harold ile tanışmasıyla değişmeye başlar. Başlangıçta sıradan görünen bu karşılaşma, zamanla iki adam arasında güçlü bir dostluğun kurulmasına ve her ikisinin de hayatlarının farklı bir yöne ilerlemesine neden olur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/radio-2003-izle.webp", backdrop = "", year = "2003", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/radyo-2003-izle/", category = "Film"),
    Movie(id = 1000295, title = "Not Another Teen Movie", overview = "Lise filmlerinde yıllardır karşımıza çıkan klişeler bu kez mizahın hedefinde. Okulun yıldız sporcuları, popüler amigo kızlar, içine kapanık öğrenciler, sürekli yemek yiyen şişman genç ve dış görünüşüyle dikkat çeken yabancı öğrenci gibi tanıdık karakterler, alışılmış rollerinin parodisi hâline geliyor. John Hughes tarzı gençlik filmlerinden korku ve komedi klasiklerine kadar pek çok yapımın kalıplarını tiye alan film, lise hayatını abartılı ve eğlenceli bir şekilde yeniden ele alıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/not-another-teen-movie-2001-izle.webp", backdrop = "", year = "2001", score = 5.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/not-another-teen-movie/", category = "Film"),
    Movie(id = 1000296, title = "Bridget Jones’un Günlüğü", overview = "Bridget Jones için yeni yıl, hayatının kontrolünü yeniden ele geçirmek için bir fırsattır. 32 yaşındaki Bridget, bundan sonra yaşadığı her şeyi kendi günlüğünde kayıt altına almaya karar verir. Aşk, arkadaşlık, iş hayatı, yemekler ve kişisel sorunlar derken günlükleri onun hayatındaki tüm iniş çıkışların aynası hâline gelir. Tam hayatını düzene sokmaya çalışırken karşısına iki farklı erkek çıkar. Daniel Cleaver’ın cazibesi ile Mark Darcy’nin gizemli tavırları arasında kalan Bridget, kendisini hiç beklemediği bir aşk üçgeninin ortasında bulur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/bridget-jonesun-gunlugu-2001-izle.webp", backdrop = "", year = "2001", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/bridget-jonesun-gunlugu/", category = "Film"),
    Movie(id = 1000297, title = "Kaplan ve Ejderha", overview = "Antik Çin’de, savaşçıların ve soylu ailelerin hüküm sürdüğü bir dönemde değerli bir kılıcın çalınması büyük bir takibin başlamasına neden olur. Kılıcı geri almak için yola çıkan iki savaşçı, izlerini sürdükleri gizemli bir kaçakla bağlantılı beklenmedik bir genç kadınla karşılaşır. Soylu bir ailenin kızı olan bu genç kadın, görünüşünün aksine dövüş sanatlarında oldukça yeteneklidir. Üçünün yollarının kesişmesiyle başlayan yolculuk, onları geçmişleriyle yüzleşecekleri ve hayatlarını değiştirecek seçimler yapmak zorunda kalacakları unutulmaz bir maceraya sürükler.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/crouching-tiger-hidden-dragon-2000-izle.webp", backdrop = "", year = "2000", score = 7.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/kaplan-ve-ejderha-izle/", category = "Film"),
    Movie(id = 1000298, title = "Forrester’ı Bulmak", overview = "16 yaşındaki Jamal Wallace, üstün zekâsı ve sınavlardaki başarısı sayesinde prestijli Mailor-Collow okulunda burslu eğitim alma fırsatı yakalar. Kenar mahalleden gelen Jamal, varlıklı öğrencilerin arasında başlangıçta kendisini yabancı hissetse de spor yeteneği ve yazarlığa olan ilgisiyle dikkat çekmeyi başarır. Bir gün arkadaşlarının yaptığı bir iddia yüzünden gizemli bir yazarın evine giren Jamal, kaçarken çantasını orada bırakır. Çantasını geri aldığında ise içindeki yazıların üzerine bazı notlar eklendiğini fark eder. Bu olay, genç öğrencinin yıllardır insanlardan uzak yaşayan ve bir zamanlar çok ünlü bir roman yazmış William Forrester ile tanışmasına ve hayatını…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/finding-forrester-2000-izle.webp", backdrop = "", year = "2000", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/forresteri-bulmak/", category = "Film"),
    Movie(id = 1000299, title = "Robot Adam", overview = "Richard Martin, ailesinin günlük işlerine yardımcı olması için gelişmiş bir robot satın alır. Başlangıçta yalnızca ev işlerini yerine getiren bu robot, zamanla çevresinden öğrendiklerini kullanarak kendisini geliştirmeye başlar. Küçük kız Amanda’nın ona Andrew adını vermesiyle robot artık ailenin hayatının bir parçası olur. Richard’ın ona bir makine gibi değil, ailenin bir üyesi gibi davranılmasını istemesi ise Andrew’da beklenmedik değişimlere yol açar. Giderek daha insani davranışlar sergileyen Andrew, robotlarla insanlar arasındaki sınırların sorgulanmasına neden olur.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/robot-adam-1999-izle.webp", backdrop = "", year = "1999", score = 6.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/robot-adam/", category = "Film"),
    Movie(id = 1000300, title = "Seni Tanıyorum", overview = "Funda, annelik sorumluluklarıyla sanat kariyerini bir arada yürütmeye çalışırken giderek daha fazla zorlanır. İmdadına yetişen gizemli bir çocuk bakıcısı sayesinde hayatını yeniden düzene sokabileceğini düşünür. Ancak bakıcının geçmişi ve sakladığı sırlar, Funda’nın tahmin ettiğinden çok daha büyük sorunların habercisidir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/seni-taniyorum-2026-izle.webp", backdrop = "", year = "2026", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/seni-taniyorum/", category = "Yerli Diziler"),
    Movie(id = 1000301, title = "The Queen’s Gambit", overview = "Walter Tevis’in aynı adlı romanından uyarlanan The Queen’s Gambit, Soğuk Savaş yıllarında geçen etkileyici bir başarı hikayesini ekrana taşıyor. Küçük yaşta ailesini kaybeden Beth Harmon, bir yetimhanede büyürken satrançla tanışır ve kısa sürede sıra dışı yeteneğini keşfeder. Rakiplerini birer birer geride bırakan Beth, dünyanın en güçlü satranç oyuncularına meydan okurken hem kişisel sorunlarıyla hem de başarı baskısıyla mücadele etmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/07/the-queens-gambit-2020-izle.webp", backdrop = "", year = "2020", score = 8.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/the-queens-gambit/", category = "Dizi"),
    Movie(id = 1000302, title = "Asırlık Gece", overview = "Hüseyin Aydın’ın kaleme aldığı eserden uyarlanan bu yapım, Türkiye’nin yakın tarihinde iz bırakan olayları ayrıntılı bir şekilde ele alıyor. Darbe girişimine giden süreçte yaşanan gelişmeler, kritik karar anları ve o geceye tanıklık eden kişilerin anlatımlarıyla ekrana taşınıyor. Cumhurbaşkanlığı Külliyesi, TBMM, TRT binası ve İstanbul’daki köprülerde yaşanan olaylara odaklanan dizi, tarihi gecenin bilinmeyen yönlerini gözler önüne seriyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/07/asirlik-gece-2026-izle.webp", backdrop = "", year = "2026", score = 5.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/asirlik-gece/", category = "Yerli Diziler"),
    Movie(id = 1000303, title = "Black Bird", overview = "Uyuşturucu ticareti nedeniyle aldığı 10 yıllık hapis cezasını çekmeye başlayan Jimmy Keene, hayatını tamamen değiştirebilecek tehlikeli bir teklif alır. FBI ile yaptığı gizli anlaşma kapsamında, maksimum güvenlikli bir cezaevine transfer edilerek seri cinayet şüphelisi Larry Hall’a yaklaşması istenir. Jimmy’nin amacı, yıllardır çözülemeyen kayıp vakalarına ışık tutacak bir itiraf elde etmektir. Ancak Hall’un gerçekten bir katil mi yoksa yalnızca dikkat çekmek için yalan söyleyen biri mi olduğu belirsizdir. Gerilim ve psikolojik mücadeleyle örülü hikâye, izleyiciyi sürekli şüphe içinde bırakıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/07/black-bird-2022-izle.webp", backdrop = "", year = "2022", score = 8.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/black-bird/", category = "Dizi"),
    Movie(id = 1000304, title = "Harman Yeri", overview = "Bir zamanların başarılı güreşçilerinden Hamza, düşman iki aileyi karşı karşıya getiren tüm engellere rağmen Cemre ile evlenerek yeni bir hayat kurar. Ancak çocuk sahibi olma konusundaki fikir ayrılıkları evliliklerinde derin yaralar açar. Ailesinden uzaklaşan Hamza, yaşadığı kayıpların ardından yeniden köklerine dönmek zorunda kalır. Kardeş acısı ve Harman Yeri’nin elden gitme tehlikesi karşısında mücadele etmeye karar veren Hamza, geçmişte bıraktığını düşündüğü güreş meydanlarına yeniden adım atar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/07/harman-yeri-2026-izle.webp", backdrop = "", year = "2026", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/harman-yeri-izle-1/", category = "Yerli Diziler"),
    Movie(id = 1000305, title = "Camp Snoopy", overview = "Snoopy ve Köpek İzciler, birliklerinin geleceğini koruyabilmek için zorlu bir doğa macerasına atılır. Rozetlerini kazanmak adına engellerle dolu bir yolculuğa çıkan ekip, dostluk ve dayanışmanın önemini yeniden keşfeder. Öte yandan Charlie Brown ile arkadaşları, Spring Gölü Kampı’nda unutulmaz bir yaz geçirirken birbirinden eğlenceli maceralar ve sürprizlerle karşılaşır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/06/camp-snoopy-2024-izle.webp", backdrop = "", year = "2024", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/camp-snoopy/", category = "Dizi"),
    Movie(id = 1000306, title = "Alice and Steve", overview = "Alice’in hayatı, yıllardır en yakın dostu olan Steve’in, kendi kızından çok da büyük olmayan 26 yaşındaki kızı Izzy ile ilişkiye başlamasıyla altüst olur. Bu beklenmedik ilişkiyi kabul etmekte zorlanan Alice, dostluğunu ve ailesini riske atacak kadar ileri gider. Ancak Steve geri adım atmaya niyetli değildir. Giderek büyüyen gerilim, yılların dostluğunu acımasız bir savaşa dönüştürürken, Alice’in eşi Daniel da eşinin hiç bilmediği yönleriyle yüzleşmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/06/alice-and-steve-2026-izle.webp", backdrop = "", year = "2026", score = 5.7, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/alice-and-steve/", category = "Dizi"),
    Movie(id = 1000307, title = "Doğu", overview = "Hayatını ailesinin beklentilerine göre şekillendiren Doğu, yıllardır sürdürdüğü üniversite eğitiminde bir türlü ilerleme kaydedemez. Akademik kariyerinin çıkmaza girdiğini anlayan genç adam, asıl hayalinin komedyenlik olduğunu kabul eder. Sahnelere uzanan bu zorlu yolculukta hem kendi sınırlarını keşfeder hem de hayatın absürt taraflarıyla yüzleşir. Dizi, başarı, aile baskısı ve hayaller arasında sıkışan bir gencin eğlenceli hikâyesini anlatıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/06/dogu-2021-izle.webp", backdrop = "", year = "2021", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/dogu-izle-4/", category = "Yerli Diziler"),
    Movie(id = 1000308, title = "Perfect Crown", overview = "21.yüzyıl Kore’sinde modern hayat ile kraliyet geleneklerinin iç içe geçtiği görkemli bir düzende, toplum hâlâ sert sınıf ayrımlarıyla yönetilmektedir. Başarılı bir holding ailesinin zeki varisi ve genç CEO’su Seong Huiju, sahip olduğu servet ve güce rağmen soylu olmadığı için hiçbir zaman gerçek anlamda kabul görmez. Ailesinin bitmek bilmeyen evlilik baskısından kaçmaya çalışan Huiju’nun yolu, Kraliyet Doğum Günü Şöleni’nde Büyük Prens Ian ile kesişir. Biri statüye, diğeri özgürlüğe ihtiyaç duyan bu iki genç, çıkar üzerine kurulu bir evlilik anlaşması yapar. Ancak saray entrikaları, toplum baskısı ve duygular devreye girdikçe planları beklenmedik…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/perfect-crown-2026-izle.webp", backdrop = "", year = "2026", score = 7.9, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/perfect-crown/", category = "Dizi"),
    Movie(id = 1000309, title = "Leyla Hâli", overview = "Hayatındaki en büyük kaybın ardından yeni bir başlangıç yapmak isteyen Leyla, kendisine kalan dükkânı hayalini kurduğu restorana dönüştürmek için harekete geçer. Çocukluk arkadaşları Peri ve Deniz’in desteğiyle başlayan bu serüvende, başarılı şef Mürsel’in ekibe katılmasıyla işler bambaşka bir boyut kazanır. Birlikte verilen mücadeleler, karakterlerin hem birbirlerine hem de kendi hayallerine daha sıkı tutunmasını sağlar. Dostluk, umut ve kendini keşfetme temalarını içten bir hikâyeyle ekrana taşıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/leyla-hali-2026-izle.webp", backdrop = "", year = "2026", score = 4.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/leyla-hali-izle-64/", category = "Yerli Diziler"),
    Movie(id = 1000310, title = "Maximum Pleasure Guaranteed", overview = "Hayatındaki büyük değişimlerle mücadele eden Paula, sıradan görünen bir olayın ardında karanlık bir gerçeğin saklandığını fark eder. Gençlik futbolu etrafında gelişen gizemli olaylar, onu şantaj ve cinayetle örülü tehlikeli bir ağın içine çeker. Kendi soruşturmasını yürütmeye başlayan Paula, bir yandan ailesini ayakta tutmaya çalışırken diğer yandan hayatını değiştirecek gerçeklerle yüzleşmek zorunda kalır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/maximum-pleasure-guaranteed-2026-izle.webp", backdrop = "", year = "2026", score = 7.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/maximum-pleasure-guaranteed/", category = "Dizi"),
    Movie(id = 1000311, title = "Gomorrah: The Origins", overview = "1970’li yılların karmaşık Napoli sokaklarında geçen hikâye, genç Pietro Savastano’nun suç dünyasına attığı ilk adımları merkezine alıyor. Güç, ihanet ve hayatta kalma mücadelesi içinde şekillenen Pietro, zamanla şehrin en korkulan isimlerinden biri haline gelir. Dizi, bir suç imparatorunun yükselişini karanlık ve sürükleyici bir atmosfer eşliğinde anlatıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/gomorrah-the-origins-2026-izle.webp", backdrop = "", year = "2026", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/gomorrah-the-origins/", category = "Dizi"),
    Movie(id = 1000312, title = "Good Omens", overview = "Dünyanın sonuna doğru geri sayım başlarken, birbirine tamamen zıt iki varlık beklenmedik bir ortaklık kurar. Cenneti temsil eden melek Aziraphale ile cehennemin asi temsilcisi Crowley, yaklaşan kıyameti durdurmak için güçlerini birleştirir. Fantastik unsurları mizahla harmanlayan dizi, Neil Gaiman ve Terry Pratchett’in kült romanından ekrana uyarlanıyor. Başrollerde ise Michael Sheen ve David Tennant dikkat çekiyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/good-omens-2019-izle.webp", backdrop = "", year = "2019", score = 8.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/good-omens-izle-7/", category = "Dizi"),
    Movie(id = 1000313, title = "Off Campus", overview = "Briar Üniversitesi’nde yolları kesişen iki zıt karakterin hikâyesi, beklenmedik bir aşka dönüşür. Hokey kültüründen uzak durmaya çalışan sivri dilli bir müzik öğrencisi ile kampüsün gözde spor yıldızı arasında başlayan yakınlaşma, ikisinin de hayatını değiştirecek olayları beraberinde getirir. OFF CAMPUS’ın ilk sezonu; gençlik, tutku ve romantizmi eğlenceli bir atmosferde buluşturuyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/off-campus-2026-izle.webp", backdrop = "", year = "2026", score = 7.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/off-campus-izle-7/", category = "Dizi"),
    Movie(id = 1000314, title = "Regular Show: The Lost Tapes", overview = "Mordecai ve Rigby, şehir parkında çalışan iki yakın arkadaştır. Ancak günlük işleri tamamlamaya çalışırken kendilerini sürekli beklenmedik olayların ve çılgın maceraların içinde bulurlar. Basit görünen görevlerin kısa sürede kontrolden çıktığı dizi, absürt mizahı ve eğlenceli karakterleriyle dikkat çekiyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/regular-show-the-lost-tapes-2026-izle.webp", backdrop = "", year = "2026", score = 9.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/regular-show-the-lost-tapes/", category = "Dizi"),
    Movie(id = 1000315, title = "Unconditional", overview = "Moskova’da geçirdikleri tatil sırasında kızı Gali’nin uyuşturucu kaçakçılığı suçlamasıyla gözaltına alınması, Orna’nın hayatını altüst eder. Kızının suçsuz olduğuna inanan fedakâr anne, gerçeği ortaya çıkarmak için kendisini karanlık ilişkiler, yozlaşmış sistemler ve tehlikeli suç örgütlerinin ortasında bulur. Unconditional, bir annenin evladı uğruna sınır tanımayan mücadelesini sürükleyici bir gerilim hikayesiyle ekranlara taşıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/unconditional-2026-izle.webp", backdrop = "", year = "2026", score = 6.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/unconditional/", category = "Dizi"),
    Movie(id = 1000316, title = "P.A.Y", overview = "Osman Hamdi Bey’in değerli eseri “Yeşil Cami Önünde”, yüksek bir bedelle özel bir vakfa satılırken gizemli bir şekilde ortadan kaybolur. Tabloyu ele geçirmek isteyen karanlık bir yeraltı ağı, çürümeye terk edilmiş bir depoda harekete geçer. Ancak bu süreçte yolları kesişen birbirinden farklı karakterler, farkında olmadan aynı tehlikeli oyunun içine çekilir. Suçlular, geçmişin yükünü taşıyan aşıklar ve kayıplarla mücadele eden insanlar, büyük bir planın ortasında hayatta kalmaya çalışırken gerilim giderek artar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/pay-2026-izle.webp", backdrop = "", year = "2026", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/p-a-y-izle-34/", category = "Yerli Diziler"),
    Movie(id = 1000317, title = "Gold Land", overview = "Tesadüfi bir karşılaşma, Heeju’nun hayatını geri dönülmez biçimde değiştirir. Bir kaçakçılık şebekesine ait altın külçelerinin eline geçmesiyle kendini tehlikeli bir oyunun içinde bulur. Açgözlülüğün ve ihanetin kol gezdiği bu dünyada, hayatta kalmak ve tüm altınları ele geçirmek için zekâsını ve cesaretini sonuna kadar kullanmak zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/05/gold-land-2026-izle.webp", backdrop = "", year = "2026", score = 8.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/gold-land/", category = "Dizi"),
    Movie(id = 1000318, title = "Jessica Jones", overview = "Kimyasal bir kazanın ardından olağanüstü güçler kazanan Jessica Jones, artık hem fiziksel dayanıklılığı hem de neredeyse ses hızına ulaşan uçuş yeteneğiyle dikkat çekiyor. Marvel ve Netflix iş birliğinin öne çıkan yapımlarından biri olan dizi, yeni sezonuyla izleyici karşısına çıkmaya hazırlanıyor. Daha çok yetişkin izleyici kitlesine hitap eden karanlık atmosferiyle bilinen yapımda Jessica, geçmişin izlerini silmeye çalışırken kendini daha karmaşık ve tehlikeli olayların içinde buluyor. İlk sezonda yaşadığı büyük mücadelelerin ardından, bu kez onu çok daha çetin sınavlar bekliyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/jessica-jones-2015-izle.webp", backdrop = "", year = "2015", score = 7.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/jessica-jones/", category = "Dizi"),
    Movie(id = 1000319, title = "Ashab-ı Kehf", overview = "Roma İmparatorluğu’nun sert baskısı altında yaşayan halk arasında tek tanrı inancı hızla yayılmaya başlar. Bu durum, çok tanrılı düzene bağlı Romalılar için büyük bir tehdit haline gelir. İnançlarından vazgeçmeyen cesur insanlar ağır işkencelere rağmen yollarından dönmez. Hz. İsa’nın öğretilerine bağlı kalan inananlar ile putperest düzen arasında büyük bir çatışma yaşanır. Bu zorlu dönemde, inançları uğruna her şeyi göze alan yedi genç, tarihe geçecek bir mucizenin parçası olur. Kur’an-ı Kerim’de de bahsi geçen Yedi Uyurlar’ın hikâyesi, izleyiciyi derin bir yolculuğa çıkarıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/ashab-i-kehf-1997-izle.webp", backdrop = "", year = "1997", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/ashab-i-kehf/", category = "Dizi"),
    Movie(id = 1000320, title = "Temiz Para", overview = "Hayatı borçlarla kuşatılmış bir muhasebeci olan Soner, yaptığı büyük bir hatayla mafyanın hedefi haline gelir. Kaybettiği parayı geri kazanmak için riskli bir plan devreye girer: Amatör bir film çekimi bahanesiyle para aklamak. Mafyanın sağ kolu Fatih ile birlikte yürüttüğü bu plan, set ortamında gelişen duygusal yakınlaşmalarla beklenmedik bir hal alır. İki kadınla kurulan bağlar, hem Soner’in hem de Fatih’in iç dünyasını sarsarken, suç ve vicdan arasındaki çizgi giderek bulanıklaşır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/temiz-para-2026-izle.webp", backdrop = "", year = "2026", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/temiz-para-izle/", category = "Yerli Diziler"),
    Movie(id = 1000321, title = "Kara Kış", overview = "1939 Erzincan depremi, yalnızca bir felaket değil, aynı zamanda insan ruhunun sınandığı bir dönüm noktası olur. Genç savcı İzzet Akçal, cezaevindeki mahkûmlarla birlikte enkaz altındaki insanları kurtarmak için zorlu bir mücadeleye girişir. Bu süreçte suç, adalet ve vicdan kavramları onun için yeniden şekillenir. Olayları yakından takip eden gazeteci Sinan Seyfi ise hem bu sıra dışı kurtarma hikâyesine hem de yıllar sonra darbe mahkemesinde yeniden karşılaşacakları İzzet’in değişimine tanıklık eder.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/kara-kis-2026-izle.webp", backdrop = "", year = "2026", score = 6.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/kara-kis-izle-63/", category = "Yerli Diziler"),
    Movie(id = 1000322, title = "My Brother the Minotaur", overview = "Yarısı insan, yarısı boğa olan genç bir minotaurun sıradışı hikâyesini anlatan My Brother The Minotaur, farklılıkların ortasında büyümenin zorluklarını ve gücünü gözler önüne seriyor. İnsan dünyasında yetiştirilen bu gizemli genç, kendisine her koşulda destek olan kardeşiyle birlikte geçmişine dair sırları ortaya çıkarmaya çalışır. Bu yolculukta kurduğu dostluklar ve karşısına çıkan karanlık tehditler, onu kaderine bir adım daha yaklaştırırken izleyiciyi de sürükleyici bir maceraya davet ediyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/my-brother-the-minotaur-2026-izle.webp", backdrop = "", year = "2026", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/my-brother-the-minotaur/", category = "Dizi"),
    Movie(id = 1000323, title = "Arrow", overview = "Denizde yaşanan gizemli bir kazanın ardından öldüğü düşünülen Oliver Queen, yıllar sonra ıssız bir adada hayatta kaldığı ortaya çıkar. Beş yıl süren zorlu yaşam mücadelesi onu bambaşka birine dönüştürmüştür. Şehrine geri döndüğünde ise artık eski hayatına uyum sağlamakta zorlanır. Geçmişte yaptığı hataların yükünü taşıyan Oliver, kendine yeni bir amaç edinir: suçlularla savaşmak. Kimliğini gizleyerek “Arrow” olarak adalet dağıtmaya başlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/arrow-2012-izle.webp", backdrop = "", year = "2012", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/arrow/", category = "Dizi"),
    Movie(id = 1000324, title = "Dear Killer Nannies", overview = "Juampi’nin hayatı dışarıdan bakıldığında ayrıcalıklarla doludur; korumalar, lüks yaşam ve güvenli bir dünya… Ancak bu düzen, babasının gerçek kimliğini öğrenmesiyle paramparça olur. Sevgi duyduğu insanların aslında ölümcül görevler üstlenen profesyoneller olduğunu fark eden Juampi, kendini hiç seçmediği bir savaşın ortasında bulur. Ailesinin soyadı, onun için bir güç değil, kaçınılmaz bir kader haline gelir. Bu etkileyici hikaye, Medellín Karteli’nin gölgesinde büyüyen bir çocuğun dramatik dönüşümünü gözler önüne seriyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/dear-killer-nannies-2026-izle.webp", backdrop = "", year = "2026", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/dear-killer-nannies/", category = "Dizi"),
    Movie(id = 1000325, title = "Bless This Mess", overview = "Yeni evli Rio ve Mike, kalabalık ve yorucu New York hayatını geride bırakıp Nebraska’nın sakin kırsalına taşınarak yepyeni bir başlangıç yapmayı hedefler. Şehir yaşamının karmaşasından uzaklaşıp çiftlik hayatına adım atan çift, hayallerinin sandıkları kadar kolay olmadığını kısa sürede fark eder. Doğanın zorlukları, alışılmadık sorumluluklar ve beklenmedik olaylar karşısında Rio ve Mike, hem ilişkilerini hem de yeni yaşamlarını ayakta tutmanın yollarını keşfetmek zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/bless-this-mess-2019-izle.webp", backdrop = "", year = "2019", score = 7.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/bless-this-mess/", category = "Dizi"),
    Movie(id = 1000326, title = "Home Before Dark", overview = "Henüz 11 yaşında olmasına rağmen gazeteciliğe büyük bir tutku duyan Hilde, ailesiyle birlikte sakin bir göl kasabasına taşınır. Ancak bu küçük yerleşim yerinin göründüğü kadar masum olmadığını kısa sürede fark eder. Kasaba halkının üstünü kapatmaya çalıştığı karanlık bir olayı araştırmaya başlayan Hilde, cesareti ve merakıyla dikkat çeker. Gerçek bir hikâyeden uyarlanan bu dizi, genç bir kızın büyük bir sırrı ortaya çıkarma mücadelesini etkileyici bir şekilde anlatıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/home-before-dark-2020-izle.webp", backdrop = "", year = "2020", score = 7.4, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/home-before-dark/", category = "Dizi"),
    Movie(id = 1000327, title = "Onbeşliler", overview = "Birinci Dünya Savaşı’nın gölgesi Osmanlı topraklarına düşerken, imparatorluk yalnızca dış tehditlerle değil, içeride fırsat kollayan düşmanlarla da mücadele etmektedir. Edebiyat öğretmeni Mehmet Sadık’ın Tokat’a atanmasıyla birlikte, sakin görünen şehirde yaklaşan büyük fırtınanın izleri hissedilmeye başlar. Küçük anlaşmazlıkların hızla büyüdüğü bu ortamda, vatansever gençler hem şehirlerini hem de ülkelerini korumak için zorlu bir mücadeleye girişir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/onbesliler-2026-izle.webp", backdrop = "", year = "2026", score = 8.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/onbesliler-izle-64/", category = "Yerli Diziler"),
    Movie(id = 1000328, title = "İmam Gazâlî Hüccetü’l-İslâm", overview = "11. yüzyılın Selçuklu coğrafyasında geçen bu etkileyici tarihî drama, Gazâlî’nin çalkantılarla dolu yaşamını merkezine alıyor. Saray içindeki güç oyunları, mezhepler arası gerilimler ve derin felsefi tartışmalar arasında sıkışan Gazâlî; şüphe, tutku ve inanç arasında zorlu bir sınav verir. Bu hikâye, yalnızca bir insanın içsel yolculuğunu değil, aynı zamanda İslam düşünce tarihine yön veren kritik bir dönemi gözler önüne serer.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/imam-gazali-2026-izle.webp", backdrop = "", year = "2026", score = 8.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/imam-gazali-huccetul-islam-izle-27/", category = "Yerli Diziler"),
    Movie(id = 1000329, title = "Malcolm in the Middle: Life’s Still Unfair", overview = "Malcolm ve ailesiyle yollarımızın kesişmesinin üzerinden uzun yıllar geçmiştir, ancak onların değişmeye hiç niyeti yoktur. Anne ve babasının evlilik yıl dönümü vesilesiyle yeniden bir araya gelen Malcolm, kendi kurduğu düzeni bir kenara bırakıp çocukluğunun karmaşasıyla yüzleşmek zorunda kalır. Eski defterler açılırken, aile içindeki eğlenceli ama bir o kadar da çılgın anlar yeniden gün yüzüne çıkar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/malcolm-in-the-middle-lifes-still-unfair-2026-izle.webp", backdrop = "", year = "2026", score = 7.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/malcolm-in-the-middle-lifes-still-unfair/", category = "Dizi"),
    Movie(id = 1000330, title = "Krank: Berlin", overview = "Hayatı altüst olduktan sonra her şeyi geride bırakıp yeni bir sayfa açmak isteyen genç bir doktor, Berlin’in en yoğun ve en problemli hastanelerinden birinde göreve başlar. Acil servisin başına geçtiğinde onu sadece hastalar değil, sisteme olan inancını kaybetmiş bir ekip de beklemektedir. Dirençle karşılaşsa da, düzeni yeniden kurmak ve hayat kurtarmak için sınırlarını zorlamak zorundadır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/04/krank-berlin-2025-izle.webp", backdrop = "", year = "2025", score = 7.3, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/krank-berlin/", category = "Dizi"),
    Movie(id = 1000331, title = "The Traitors Türkiye", overview = "Türkiye’nin tanınmış 20 ismi, gizemli bir kalede bir araya gelerek zihin oyunlarının merkezine adım atıyor. Gündüzleri ekip olarak hareket edip ortak ödül havuzunu büyütmeye çalışan yarışmacılar, geceleri ise büyük bir güvensizlikle yüzleşiyor. Aralarına gizlenmiş hainler, her gece bir ismi oyundan çıkarırken; masumlar Yuvarlak Masa’da doğru kişileri bulmak için strateji ve sezgilerini kullanmak zorunda kalıyor. Gerilim ve psikolojik mücadele her an yükseliyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/03/the-traitors-turkiye-2026-izle.webp", backdrop = "", year = "2026", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/the-traitors-turkiye-izle-7/", category = "Yerli Diziler"),
    Movie(id = 1000332, title = "Jury Duty Presents: Company Retreat", overview = "Hayatını geçici işlerle sürdüren Anthony, kendini bir anda Rockin’ Grandma’nın Acı Sosu şirketinin kritik bir döneminde bulur. CEO Doug son kez ekibiyle birlikte yola çıkarken, yerine geçmesi beklenen Dougie Jr. liderlik konusunda sınıfta kalmamak için çabalar. Ancak şirketi ele geçirmek isteyen güçlü yatırımcıların devreye girmesi, bu yolculuğu sıradan bir iş gezisinden çok daha fazlasına dönüştürür.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/03/jury-duty-presents-company-retreat-2026-izle.webp", backdrop = "", year = "2026", score = 8.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/jury-duty-presents-company-retreat/", category = "Dizi"),
    Movie(id = 1000333, title = "Film Club", overview = "Noa ve Evie’nin hayatında özel bir yere sahip olan küçük ama anlamlı bir film kulübünün etrafında şekillenen sıcak bir hikâye sunuyor. İki yakın arkadaş için bu kulüp yalnızca film izlemekten ibaret değildir; aynı zamanda hayallerini, düşüncelerini ve hayatın karmaşasını paylaştıkları bir alan haline gelir. Her filmle birlikte hem kendilerini hem de birbirlerini daha iyi tanımaya başlayan Noa ve Evie’nin dostluğu, sinemanın birleştirici gücüyle daha da derinleşir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/03/film-club-2025-izle.webp", backdrop = "", year = "2025", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/film-club/", category = "Dizi"),
    Movie(id = 1000334, title = "Goat Girl", overview = "Keçiler tarafından büyütülerek alışılmadık bir çocukluk geçiren Gigi, ilk kez okula adım atar. İnsanların dünyasıyla yeni tanışan Gigi için her gün bambaşka bir maceraya dönüşür. Yeni arkadaşlar edinmeye çalışan ve okul hayatına uyum sağlamaya uğraşan Gigi’nin eğlenceli, zaman zaman da duygusal anlarla dolu hikâyesi, farklı olmanın aslında ne kadar özel olabileceğini gösteriyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/03/goat-girl-2026-izle.webp", backdrop = "", year = "2026", score = 7.6, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/goat-girl/", category = "Dizi"),
    Movie(id = 1000335, title = "Higher Learning", overview = "Colombus Üniversitesi, farklı ülkelerden ve birbirinden farklı kültürel geçmişlerden gelen gençlerin bir arada eğitim gördüğü hareketli bir kampüstür. Okula yeni başlayan Malik, Kristen ve Remy ise bu renkli ortamda kendi sorunlarıyla mücadele etmeye çalışır. Gelecek vadeden bir atlet olan Malik başarı baskısıyla uğraşırken, çekingen Kristen yeni çevresine ayak uydurmakta zorlanır. Kendini yalnız hisseden Remy ise insanlarla iletişim kurmakta güçlük çeker. Üç gencin üniversite hayatı ilerledikçe ırkçılık, önyargı ve toplum tarafından kabul görme gibi sorunlarla yüzleşmeleri gerekecektir.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/higher-learning-1995-izle.webp", backdrop = "", year = "1995", score = 6.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/higher-learning/", category = "Film"),
    Movie(id = 1000336, title = "Uyanışlar", overview = "Dr. Malcolm Sayer, insanlarla iletişim kurmakta zorlanan ve kariyerinin büyük bölümünü laboratuvarlarda geçirmiş bir doktordur. Bir hastanede çalışmaya başlamasıyla birlikte, yıllardır bilinçsiz ve hareketsiz durumda olan hastalarla karşılaşır. Onların tamamen umutsuz vakalar olmadığını düşünen Sayer, tedavi edilebileceklerine inanır. Bir konferansta dikkatini çeken L-Dopa ilacının bu hastalar üzerinde işe yarayabileceğini düşünerek deneme yapılması için izin alır. İlacı Leonard Lowe üzerinde uyguladığında beklenmedik bir gelişme yaşanır ve Leonard yıllar sonra yeniden hayata döner. Ancak bu mucizevi gelişmenin beraberinde ciddi sonuçları olacaktır.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/uyanislar-1990-izle.webp", backdrop = "", year = "1990", score = 7.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/uyanislar/", category = "Film"),
    Movie(id = 1000337, title = "Düşler Tarlası", overview = "Ray Kinsella’nın Iowa’daki yeni yaşamı, tarlasından gelen gizemli bir sesle bambaşka bir yöne sürüklenir. Duyduğu “İnşa edersen gelecekler” sözlerinin anlamını çözmeye çalışan Ray, bunun tarlasına bir beyzbol sahası yapması gerektiğine inanır. Ailesinin desteğiyle hayalini gerçekleştirmeye başlayan genç çiftçi, kısa süre sonra bunun yalnızca bir spor sahası olmadığını fark eder. Gizemli yönlendirmeler onu Terence Mann’ın kapısına götürür. Ray ve Terence, kendilerine ulaşan mesajları takip ettikçe geçmişin unutulmuş hikâyeleriyle ve hayatlarını değiştirecek sürprizlerle karşılaşırlar.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/09/dusler-tarlasi-1989-izle.webp", backdrop = "", year = "1989", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/film/dusler-tarlasi/", category = "Film"),
    Movie(id = 1000338, title = "Women’s Hell", overview = "II. Dünya Savaşı’nın gölgesinin Avrupa üzerine düşmeye başladığı yıllarda, Polonya’da geçen çarpıcı bir dramı anlatır. Toplumun katı kuralları ve adaletsizliğiyle mücadele eden genç bir kadın, cinsel saldırı mağduru kadınların haklarını savunmak için tehlikeli bir yola adım atar. Gerçeğin ortaya çıkması için verdiği bu mücadele, onu hem güçlü düşmanlarla karşı karşıya bırakır hem de kendi özgürlüğü ve kimliği için verdiği kişisel bir savaşa dönüşür. Dönemin karanlık atmosferi içinde kadınların adalet ve bağımsızlık arayışını etkileyici bir hikâyeyle ekrana taşıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/03/womens-hell-2026-izle.webp", backdrop = "", year = "2026", score = 6.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/womens-hell/", category = "Dizi"),
    Movie(id = 1000339, title = "City of God: The Fight Rages On", overview = "2000’li yılların başında geçen bu çarpıcı dizi, hapishaneden çıkan genç bir uyuşturucu satıcısının dönüşüyle birlikte yeniden alevlenen bir mahallenin hikâyesini merkezine alıyor. City of God olarak bilinen bu bölgede dengeler hızla değişirken, sokaklar bir kez daha uyuşturucu çeteleri, silahlı milis grupları ve kamu otoriteleri arasındaki güç savaşına sahne olur. En büyük bedeli ise arada kalan sıradan insanlar öder. Baskı, korku ve belirsizlik içinde yaşamaya çalışan mahalle sakinleri, yıllardır süren şiddet döngüsünden kurtulmanın yolunu arar. Ancak bu kez hayatta kalmak yeterli değildir; zalim düzenle yüzleşmek ve geleceklerini geri almak için birlik…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/03/city-of-god-the-fight-rages-on-2024-izle.webp", backdrop = "", year = "2024", score = 7.2, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/city-of-god-the-fight-rages-on/", category = "Dizi"),
    Movie(id = 1000340, title = "Hz. Ömer", overview = "İslam tarihinin en kritik kırılma noktalarından birine ışık tutan Hz. Ömer dizisi, adaleti, devlet yönetimindeki kararlılığı ve ileri görüşlülüğüyle öne çıkan büyük bir liderin hayatını ekranlara taşıyor. Halifeliği döneminde sadece bir coğrafyayı değil, hukuk ve yönetim anlayışını da derinden etkileyen Hz. Ömer’in yaşamı; siyasi mücadeleler, toplumsal dönüşümler ve insanî yönleriyle birlikte kapsamlı bir anlatımla izleyiciye sunuluyor. Yapım süreci iki yılı aşkın bir zaman dilimine yayılan ve on binlerce oyuncu ile figüranın görev aldığı bu dev proje, Arap televizyon tarihinin en iddialı ve yüksek bütçeli yapımlarından biri olarak dikkat çekiyor. Ortadoğu…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/02/hazreti-omer-2012-izle.webp", backdrop = "", year = "2012", score = 9.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/hz-omer/", category = "Dizi"),
    Movie(id = 1000341, title = "All Her Fault", overview = "Marissa Irvine, küçük oğlu Milo’yu ilk oyun buluşmasından almak için kapıyı çaldığında hayatının en büyük şokuyla karşılaşır. Kapıyı açan kadın ne tanıdığı bir annedir ne de Milo’yu gördüğünü kabul eder. Dahası, çocuğun adını bile duymadığını söyler. Bir annenin yaşayabileceği en büyük korku gerçeğe dönüşürken, kayıp bir çocuğun izini sürmek için başlayan arayış kısa sürede çok daha karmaşık ve karanlık bir hâl alır. Marissa cevap aradıkça, ortaya çıkan her yeni detay aile içinde saklanan sırları ve Irvine ailesinin kusursuz görünen hayatındaki çatlakları gün yüzüne çıkarır. Güvenin sarsıldığı, gerilimin adım adım yükseldiği…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/02/all-her-fault-2025-izle.webp", backdrop = "", year = "2025", score = 7.5, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/all-her-fault/", category = "Dizi"),
    Movie(id = 1000342, title = "Banksters", overview = "Yusuf, henüz hayatının baharındayken adı art arda gerçekleşen banka soygunlarına karışır ve tutuklanarak cezaevine gönderilir. Ancak bu hikâye onun hapse girmesiyle bitmez; asıl mücadele dışarıda başlar. Kız kardeşi, hem kaybolan paranın peşine düşer hem de Yusuf’u kimin, neden ele verdiğini araştırmaya koyulur. Attığı her adım onu daha karanlık ilişkilerin, gizli hesapların ve tehlikeli insanların ortasına sürükler. Aile bağlarının sınandığı, ihanetin gölgesinde ilerleyen bu suç ve gerilim dizisi, sürükleyici atmosferiyle izleyiciyi ekran başına kilitliyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/02/banksters-2026-izle.webp", backdrop = "", year = "2026", score = 5.0, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/banksters/", category = "Dizi"),
    Movie(id = 1000343, title = "Watching You", overview = "Lina’nın hayatı, tesadüfen kaydedilen gizli bir kamera görüntüsünün ortaya çıkmasıyla geri dönülmez şekilde değişir. Masum görünen bir karşılaşma, kısa sürede güvenin yerle bir olduğu, sırların bir bir açığa çıktığı karanlık bir sürecin kapısını aralar. Yaşanan şok edici bir ölüm ise tüm dengeleri altüst eder ve nişanlısının tutuklanmasıyla Lina kendisini olayların tam merkezinde bulur. Gerilim dozu giderek artarken, Lina bir yandan yeni bir ilişkiyle hayata tutunmaya çalışır, diğer yandan peşini bırakmayan tehlikeli bir gözetleyicinin varlığını fark eder. Görünenin ardında çok daha büyük ve karmaşık bir plan olduğunu keşfettikçe, hem kendi güvenliği…", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/02/watching-you-2025-izle.webp", backdrop = "", year = "2025", score = 5.8, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/watching-you/", category = "Dizi"),
    Movie(id = 1000344, title = "The Snoopy Show", overview = "Hayal kurmayı seven sevimli beagle Snoopy, yakın dostu Woodstock ve Peanuts ekibinin enerjisiyle dopdolu, eğlenceli bir serüvene davet ediyor. Dansın, dostluğun ve gökyüzüne uzanan büyük hayallerin peşinden giden bu sıcacık hikâye; neşeli anları, içten mizahı ve umut veren atmosferiyle her yaştan izleyiciye keyifli bir kaçış sunuyor. Aile boyu izlenebilecek bu renkli macera, küçük mutlulukların bile ne kadar büyük anlamlar taşıyabileceğini hatırlatıyor.", poster = "https://www.hdfilmcehennemi.land/thumb_/149x224-1/wp-content/uploads/2026/02/the-snoopy-show-2021-izle.webp", backdrop = "", year = "2021", score = 8.1, genreIds = emptyList(), provider = "HDFilmcehennemi", webUrl = "https://www.hdfilmcehennemi.land/dizi/the-snoopy-show/", category = "Dizi")
)
